window.QUESTIONS=[{"id": 1, "type": "单选", "question": "道德的特点是通过( )、传统习俗和自觉自愿行为来起作用的。", "options": [{"key": "A", "text": "社会舆论"}, {"key": "B", "text": "法律"}, {"key": "C", "text": "制度"}, {"key": "D", "text": "规章"}], "answer": "A", "analysis": "道德依靠社会舆论、传统习俗和内心信念（自觉自愿）来调整人的行为，这是道德与法律（靠国家强制力）的本质区别。选项中只有“社会舆论”属于道德发挥作用的三大途径之一，故选A。"}, {"id": 2, "type": "单选", "question": "职业道德对员工在职业活动中规范自己的言行及调节行为习惯起着( )作用。", "options": [{"key": "A", "text": "一般"}, {"key": "B", "text": "多余"}, {"key": "C", "text": "无效"}, {"key": "D", "text": "重要"}], "answer": "D", "analysis": "职业道德是从业人员在职业活动中应遵循的行为规范，对规范言行、调节职业行为习惯具有重要作用。它既不是“一般”“多余”也不是“无效”，因此选“重要”。"}, {"id": 3, "type": "单选", "question": "当一意外事故发生时，岗位从业人员及时呼救，并积极抢救，直至以身殉职，该事例集中反映了企业职工的( )精神。", "options": [{"key": "A", "text": "遵纪守法"}, {"key": "B", "text": "执行规范"}, {"key": "C", "text": "忠于职守"}, {"key": "D", "text": "精益求精"}], "answer": "C", "analysis": "从业人员在意外事故中及时呼救、积极抢救甚至以身殉职，体现的是恪尽职守、尽职尽责的职业精神，即“忠于职守”。遵纪守法、执行规范、精益求精均不能准确概括这一行为。"}, {"id": 4, "type": "单选", "question": "粮食仓储某从业人员在熏蒸杀虫时不穿戴防护用品，其行为违背了( )的职业守则。", "options": [{"key": "A", "text": "团结合作"}, {"key": "B", "text": "文明生产"}, {"key": "C", "text": "执行规范"}, {"key": "D", "text": "遵纪守法"}], "answer": "C", "analysis": "熏蒸杀虫属高风险作业，必须严格按规程穿戴防毒面具等防护用品。不穿戴防护用品直接违反了“执行规范”这一职业守则，而非团结合作、文明生产或遵纪守法层面的问题。"}, {"id": 5, "type": "单选", "question": "粮油在储藏过程中（ ）。", "options": [{"key": "A", "text": "既存在无氧呼吸，也存在氧呼吸"}, {"key": "B", "text": "只存在有氧呼吸"}, {"key": "C", "text": "只存在无氧呼吸"}, {"key": "D", "text": "不存在呼吸"}], "answer": "A", "analysis": "粮食和油料是有生命的活体，储藏过程中同时进行有氧呼吸和无氧呼吸：有氧条件下以有氧呼吸为主，缺氧条件下转为无氧呼吸并产生酒精。因此既存在无氧呼吸也存在有氧呼吸。"}, {"id": 6, "type": "单选", "question": "水分对粮食和油料呼吸作用的影响受（ ）条件的限制。", "options": [{"key": "A", "text": "温度"}, {"key": "B", "text": "氧气浓度"}, {"key": "C", "text": "CO 浓度"}, {"key": "D", "text": "乙醇浓度"}], "answer": "A", "analysis": "水分和温度是影响粮油呼吸强度的两大主要因素，二者相互制约。水分对呼吸作用的促进程度受温度条件限制，温度越高，高水分粮的呼吸越强，故选“温度”。"}, {"id": 7, "type": "单选", "question": "粮食和油料种子的发芽率达到（ ）以上作为完全成熟的标志。", "options": [{"key": "A", "text": "50%"}, {"key": "B", "text": "60%"}, {"key": "C", "text": "70%"}, {"key": "D", "text": "80%"}], "answer": "D", "analysis": "种子生理成熟以发芽率为标志，发芽率达到80%以上即视为完全成熟。这是判断粮油种子成熟度的常用临界指标。"}, {"id": 8, "type": "单选", "question": "中国储备粮管理总公司直属企业是专门储存中央储备粮的企业，同时规定中央储备粮也可以由( )代储。", "options": [{"key": "A", "text": "国家粮食储备库"}, {"key": "B", "text": "省级粮食储备库"}, {"key": "C", "text": "具备条件的其他企业"}, {"key": "D", "text": "具备条件的农民"}], "answer": "C", "analysis": "按《中央储备粮管理条例》，中储粮直属企业专储中央储备粮，也可由具备条件的其他企业代储，并非仅限某级储备库或农民。故选“具备条件的其他企业”。"}, {"id": 9, "type": "单选", "question": "( )工作除了保护劳动者安全、健康外，还包括保障机器设备安全运行及财产安全。", "options": [{"key": "A", "text": "社会保护"}, {"key": "B", "text": "劳动保护"}, {"key": "C", "text": "安全生产"}, {"key": "D", "text": "社会救助"}], "answer": "C", "analysis": "安全生产的含义最广：不仅保护劳动者的安全和健康，还包括保障机器设备安全运行及财产安全。劳动保护侧重人身安全，社会救助、社会保护不符题意。"}, {"id": 10, "type": "单选", "question": "劳动者应当履行的义务包括：( )，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。", "options": [{"key": "A", "text": "完成劳动任务"}, {"key": "B", "text": "主动完成劳动任务"}, {"key": "C", "text": "积极完成劳动任务"}, {"key": "D", "text": "拼命完成劳动任务"}], "answer": "A", "analysis": "《劳动法》规定劳动者义务包括：完成劳动任务、提高职业技能、执行劳动安全卫生规程、遵守劳动纪律和职业道德。选项中规范表述为“完成劳动任务”。"}, {"id": 11, "type": "单选", "question": "用托盘天平进行称量时，称量物不能直接放在托盘上而应盛放在容器中后再放在托盘上进行称量。下述用具中不能用作称量物品的容器是( )。", "options": [{"key": "A", "text": "蜡光纸"}, {"key": "B", "text": "表面皿"}, {"key": "C", "text": "旧报纸"}, {"key": "D", "text": "称量瓶"}], "answer": "C", "analysis": "托盘天平称量物应盛于洁净、不吸湿、不掉屑的容器（如表面皿、称量瓶、蜡光纸）。旧报纸易吸湿、掉纸屑且可能带杂质，会污染、增重称量物，不能用作称量容器。"}, {"id": 12, "type": "单选", "question": "储粮微生物可将粮食中的糖类首先分解为( )。", "options": [{"key": "A", "text": "维生素"}, {"key": "B", "text": "氨基酸"}, {"key": "C", "text": "葡萄糖"}, {"key": "D", "text": "脂肪酸"}], "answer": "C", "analysis": "储粮微生物分解粮食成分时，首先将多糖（淀粉等糖类）分解为葡萄糖等单糖，再进一步代谢产热、产酸。因此糖类首先被分解为葡萄糖。"}, {"id": 13, "type": "单选", "question": "关于触杀性空仓杀虫剂的使用，下列说法( )是正确的。", "options": [{"key": "A", "text": "能作为防护剂使用"}, {"key": "B", "text": "能与粮油直接接触"}, {"key": "C", "text": "能用于空仓或器材杀虫"}, {"key": "D", "text": "能用于实仓粮面上的空间"}], "answer": "C", "analysis": "触杀性空仓杀虫剂只能用于空仓、器材杀虫，不能直接接触粮油，也不能作为防护剂用于实仓粮面。选项中只有“能用于空仓或器材杀虫”正确。"}, {"id": 14, "type": "单选", "question": "做好空仓和器材杀虫的安全防护很重要，以下说法不正确的是 ( )。", "options": [{"key": "A", "text": "配制和施药时，若不慎溅入眼中，应立即用淡盐水清洗干净。"}, {"key": "B", "text": "施药时，应逆风退行，不要在高温、大风、下雨等条件下施药。"}, {"key": "C", "text": "每次每人施药操作不要超过3h"}, {"key": "D", "text": "如出现乏力、头昏、恶心、呕吐、皮肤红肿等中毒现象，应立即离开现场"}], "answer": "C", "analysis": "安全施药规定每人每次连续施药时间不宜过长（通常不超过2h），选项中“每次每人施药操作不要超过3h”超出了安全限度，故不正确；其余A（溅入眼用清水/淡盐水冲洗）、B（逆风退行、避开高温大风雨天）、D（中毒即离现场）均符合安全要求。"}, {"id": 15, "type": "单选", "question": "带式输送机输送带跑偏的原因，不包括以下( )", "options": [{"key": "A", "text": "机头部或在输送带上有水，造成驱动滚输送输送筒和输送带间的摩擦系数降低"}, {"key": "B", "text": "机头传动滚筒与尾部滚筒不平行"}, {"key": "C", "text": "传动滚筒、尾部滚筒轴中心线与机身中心线不垂直。"}, {"key": "D", "text": "托辊安装不正"}], "answer": "A", "analysis": "机头部或输送带上有水会降低摩擦系数，导致的是输送带“打滑”而非“跑偏”。跑偏主要由滚筒不平行、中心线不垂直、托辊安装不正等引起，故A不属于跑偏原因。"}, {"id": 16, "type": "单选", "question": "预防与处理输送带打滑，以下( )的做法是错误的。", "options": [{"key": "A", "text": "经常检查输送带的张紧程度，适度拉紧输送带"}, {"key": "B", "text": "装载量要控制，超载不超过1%时可以运行"}, {"key": "C", "text": "经常检查输送带接头情况"}, {"key": "D", "text": "停机时要卸完输送带上的粮油，且不得再装载"}], "answer": "B", "analysis": "预防打滑要求控制装载量、严禁超载，所谓“超载不超过1%时可以运行”是错误的。正确做法为经常检查张紧程度、检查接头、停机卸完粮后再停。"}, {"id": 17, "type": "单选", "question": "目前使用的油泵根据工作原理可分次齿轮泵、螺杆泵等。齿轮泵由泵体、齿轮、前后泵盖、 ( )、轴承及密封装置等部件组成。", "options": [{"key": "A", "text": "液压阀"}, {"key": "B", "text": "负压阀"}, {"key": "C", "text": "安全阀"}, {"key": "D", "text": "单向阀"}], "answer": "C", "analysis": "齿轮油泵由泵体、齿轮、前后泵盖、安全阀、轴承及密封装置等组成，安全阀用于在系统过载时泄压保护。液压阀、负压阀、单向阀均非其标准组成部件表述。"}, {"id": 18, "type": "单选", "question": "房式仓具有( )等储藏性能优势。", "options": [{"key": "A", "text": "仓隔热性能好"}, {"key": "B", "text": "仓密闭性能好"}, {"key": "C", "text": "便于清扫、翻倒粮堆"}, {"key": "D", "text": "进出仓作业效率高"}], "answer": "C", "analysis": "房式仓（平房仓）空间开阔、粮堆暴露，便于人工清扫、翻倒粮堆和日常检查，这是其储藏性能优势。隔热、密闭性能并非房式仓突出优势，进出仓效率也不及筒仓。"}, {"id": 19, "type": "单选", "question": "下列( )不属于筒仓安全性能检查的内容", "options": [{"key": "A", "text": "检查输粮流程，对轴承进行润滑保养"}, {"key": "B", "text": "检查磷化氢环流熏蒸风机及管道、测温电缆、照明等设备外观完好，可正常运行"}, {"key": "C", "text": "检查入粮质量和入粮环节的清理"}, {"key": "D", "text": "检查仓顶通风口、进出粮口是否保持紧闭"}], "answer": "C", "analysis": "筒仓安全性能检查针对设备与仓体（输粮流程润滑、环流熏蒸风机管道、测温电缆、通风口紧闭等）。入粮质量和清理属于入库质量管理环节，不属于筒仓安全性能检查内容。"}, {"id": 20, "type": "单选", "question": "关于浅圆仓储藏性能的说法，( ) 是不对的。", "options": [{"key": "A", "text": "进出粮机械化水平比平房仓的高，比筒仓的低"}, {"key": "B", "text": "吨粮单位造价远低于平房仓和筒仓"}, {"key": "C", "text": "浅圆仓入粮时，自动分级现象要比平房仓的严重"}, {"key": "D", "text": "出仓自流后残余的粮油可用清仓机械或吸粮机等设备完成"}], "answer": "B", "analysis": "浅圆仓吨粮单位造价低于筒仓但高于平房仓，选项中“远低于平房仓和筒仓”不正确。其机械化水平介于平房仓与筒仓之间、自动分级比平房仓严重、出仓可用清仓机械均正确。"}, {"id": 21, "type": "单选", "question": "在加工和储存过程中，油脂中的水分、磷脂、( )、蛋白质、饼屑以及泥土等杂质，沉淀到大罐底层形成油脚。", "options": [{"key": "A", "text": "脱磷脂"}, {"key": "B", "text": "糖类"}, {"key": "C", "text": "白蜡"}, {"key": "D", "text": "蜂蜡"}], "answer": "B", "analysis": "油脂在加工储存中，水分、磷脂、糖类、蛋白质、饼屑及泥土等杂质会逐渐沉淀到大罐底层形成油脚。糖类是其中一类可沉降的杂质。"}, {"id": 22, "type": "单选", "question": "各类稻谷以三等为中等标准，粳型稻谷的出糙率中等标准为 ( )。", "options": [{"key": "A", "text": "79.0%～80.9%"}, {"key": "B", "text": "77.0%～78.9%"}, {"key": "C", "text": "75.0%～76.9%"}, {"key": "D", "text": "73.0%～74.9%"}], "answer": "B", "analysis": "稻谷分1–5等，以三等为中等。粳型稻谷三等出糙率标准为77.0%～78.9%（籼型稻谷为75.0%～76.9%），故选B。"}, {"id": 23, "type": "单选", "question": "稻谷的不完善粒是指未成熟或受到损伤但尚有使用价值的稻谷颗粒，不包括( )。", "options": [{"key": "A", "text": "霉变粒"}, {"key": "B", "text": "破碎粒"}, {"key": "C", "text": "虫蚀粒"}, {"key": "D", "text": "病斑粒"}], "answer": "B", "analysis": "稻谷不完善粒指未成熟或受损伤但有使用价值的颗粒，如未熟粒、虫蚀粒、病斑粒、生芽粒、霉变粒等。破碎粒按标准不属于不完善粒，故“不包括破碎粒”。"}, {"id": 24, "type": "单选", "question": "小麦按容重分等，以三等为中等质量标准，其容重为( ) 克/升。", "options": [{"key": "A", "text": "≥790"}, {"key": "B", "text": "≥770且<790"}, {"key": "C", "text": "≥750且<770"}, {"key": "D", "text": "≥730且<750"}], "answer": "D", "analysis": "小麦按容重分1–5等，以三等为中等。本题选项划分下三等对应容重≥730且<750 g/L（提示：现行GB 1351《小麦》国标中三等容重为≥750 g/L，等别区间口径与本题选项略有差异，复习时以官方最新教材为准）。"}, {"id": 25, "type": "单选", "question": "小麦的不完善粒，不包括( )。", "options": [{"key": "A", "text": "生芽粒"}, {"key": "B", "text": "破损粒"}, {"key": "C", "text": "生霉粒"}, {"key": "D", "text": "未熟粒"}], "answer": "D", "analysis": "小麦不完善粒包括虫蚀粒、病斑粒、生芽粒、生霉粒、破损粒等受到伤害但有使用价值的颗粒。未熟粒不属于不完善粒范畴，故不包括未熟粒。"}, {"id": 26, "type": "单选", "question": "玉米根据容重大小分等。低于 ( )的为等外玉米。", "options": [{"key": "A", "text": "三等"}, {"key": "B", "text": "四等"}, {"key": "C", "text": "五等"}, {"key": "D", "text": "六等"}], "answer": "C", "analysis": "玉米按容重分为1–5等，低于五等（即容重低于五等下限）的玉米列为等外玉米，不再分等。"}, {"id": 27, "type": "单选", "question": "对于玉米，因籽粒在果穗上着生的部位不同，其( )差别明显，因而容重差别较大。", "options": [{"key": "A", "text": "粒形"}, {"key": "B", "text": "成熟度"}, {"key": "C", "text": "饱满度"}, {"key": "D", "text": "以上都是"}], "answer": "D", "analysis": "玉米籽粒在果穗上着生部位不同，其粒形、成熟度、饱满度均有明显差别，三者共同导致容重差异较大，故选“以上都是”。"}, {"id": 28, "type": "单选", "question": "植物油脂一般含有大量的( )，在储藏过程中很容易氧化分解。", "options": [{"key": "A", "text": "饱和脂肪酸"}, {"key": "B", "text": "不饱和脂肪酸"}, {"key": "C", "text": "油酸"}, {"key": "D", "text": "磷脂"}], "answer": "B", "analysis": "植物油脂含大量不饱和脂肪酸（如油酸、亚油酸），其碳链上的双键化学性质活泼，易氧化分解而酸败，故储藏中稳定性差。"}, {"id": 29, "type": "单选", "question": "油脂色泽是油脂的一项重要物理指标，不同品种、不同加工等级的油脂色泽不同。菜籽油一般呈( )", "options": [{"key": "A", "text": "淡黄色至橙黄色"}, {"key": "B", "text": "黄色至棕黄色"}, {"key": "C", "text": "黄色至棕色"}, {"key": "D", "text": "橙黄至棕色"}], "answer": "C", "analysis": "不同品种、不同加工等级的油脂色泽不同，菜籽油一般呈黄色至棕色（常带绿褐调）。故选“黄色至棕色”。"}, {"id": 30, "type": "单选", "question": "感官判定油脂色泽、透明度时，( )在日出前和日落后进行。", "options": [{"key": "A", "text": "可以"}, {"key": "B", "text": "尽量"}, {"key": "C", "text": "应避免"}, {"key": "D", "text": "应选择"}], "answer": "C", "analysis": "感官判定油脂色泽、透明度需在充足自然光下进行，日出前和日落后光线不足会导致判断不准，故应避免在此时段进行。"}, {"id": 31, "type": "单选", "question": "斗式提升机的机座部分，不包括下列( )。", "options": [{"key": "A", "text": "进料斗"}, {"key": "B", "text": "牵引构件"}, {"key": "C", "text": "张紧机构"}, {"key": "D", "text": "底轮"}], "answer": "B", "analysis": "斗式提升机机座由进料斗、张紧机构、底轮（及机座壳体）等组成。牵引构件（畚斗带）贯穿整机，并非机座部件，故选“牵引构件”。"}, {"id": 32, "type": "单选", "question": "下列( ) 是斗式提升机的缺点。", "options": [{"key": "A", "text": "有良好的密封性"}, {"key": "B", "text": "容易引起粉尘爆炸"}, {"key": "C", "text": "工作平稳可靠，提升高度高"}, {"key": "D", "text": "产量大，耗用动力少"}], "answer": "B", "analysis": "提升机输送粉状物料、易扬尘且密闭性相对较差，存在粉尘爆炸危险，这是其缺点。密封性好、平稳可靠、产量大、耗电少均属优点。"}, {"id": 33, "type": "单选", "question": "关于斗式提升机设置泄爆孔，下列( )的描述是不正确的。", "options": [{"key": "A", "text": "当压力增大时，手动泄爆降压"}, {"key": "B", "text": "泄爆孔多数设置于机头"}, {"key": "C", "text": "泄爆孔可设置于机座"}, {"key": "D", "text": "泄爆孔是在机壳上开设若干个圆孔"}], "answer": "A", "analysis": "泄爆孔是在机壳上开设若干圆孔（多在机头、也可在机座），超压时自动泄爆降压，而非“手动泄爆”。故“压力增大时手动泄爆降压”描述不正确。"}, {"id": 34, "type": "单选", "question": "在使用斗式提升机时，不列做法 ( ) 是不对的。", "options": [{"key": "A", "text": "先开机，待运转正常后，再给料"}, {"key": "B", "text": "进料要均匀，出料管应通畅，以免引起堵塞"}, {"key": "C", "text": "发现堵塞，应直接用手或工具伸进底座排除堵塞"}, {"key": "D", "text": "发生突然停机，应先将机座内积存的物料排出后再开机"}], "answer": "C", "analysis": "提升机发生堵塞时严禁直接用手或工具伸入底座排除（有卷入、绞伤危险），应先停机断电再处理。先开机后给料、均匀进料、突然停机先排积料均正确，故选C。"}, {"id": 35, "type": "单选", "question": "下列做法( )，不符合刮板输送机的安全使用要求。", "options": [{"key": "A", "text": "正确地选型"}, {"key": "B", "text": "可以输送任何粉尘状、小颗粒状及小块状物料"}, {"key": "C", "text": "开机后，操作人员不得在运行过程中离机"}, {"key": "D", "text": "若无特殊情况不得负载停机"}], "answer": "B", "analysis": "刮板输送机有适用物料范围，并非“任何”粉状、小颗粒及小块状物料都能输送（如过大块、强磨琢、易碎物料不宜）。正确选型、运行中不离机、不负载停机均符合安全要求，故选B。"}, {"id": 36, "type": "单选", "question": "电子汽车衡和非连续累计料斗秤使用之前，要检查( )的接线是否正确，有无松动断线现象。", "options": [{"key": "A", "text": "计算机"}, {"key": "B", "text": "传感器和仪表"}, {"key": "C", "text": "打印机"}, {"key": "D", "text": "称重部件"}], "answer": "B", "analysis": "衡器依靠称重传感器和显示仪表工作，使用前须检查传感器和仪表的接线是否正确、有无松动断线，以保证称量准确。"}, {"id": 37, "type": "单选", "question": "有关电子汽车衡的安装， ( )是正确的。", "options": [{"key": "A", "text": "地上衡采用无基坑"}, {"key": "B", "text": "无基坑秤台两端采用混凝士浇筑引坡"}, {"key": "C", "text": "秤台上不安装专供吊运用的吊环螺钉"}, {"key": "D", "text": "传感器与秤台不安装在一起"}], "answer": "A", "analysis": "电子汽车衡地上衡采用无基坑结构，基础简单、便于维护，符合安装规范。秤台应设吊装用吊环、传感器与秤台组装在一起（C、D表述错误），故选A。"}, {"id": 38, "type": "单选", "question": "实垛的特点为粮包挤靠甚紧，包间孔隙小，受外界空气影响( )，可以充分利用仓容，一般适用于长期保存干燥的粮食。", "options": [{"key": "A", "text": "大"}, {"key": "B", "text": "较强"}, {"key": "C", "text": "较弱"}, {"key": "D", "text": "明显"}], "answer": "C", "analysis": "实垛粮包挤靠紧密、包间孔隙小，与外界空气交换少，受外界空气影响弱，利于充分利用仓容并长期保存干燥粮食。故选“较弱”。"}, {"id": 39, "type": "单选", "question": "粮油保管自然损耗量等于入库总量减出库总量，再减( )。", "options": [{"key": "A", "text": "水分杂质减量"}, {"key": "B", "text": "运输损耗量"}, {"key": "C", "text": "实际损耗量"}, {"key": "D", "text": "定额损耗量"}], "answer": "A", "analysis": "粮油保管自然损耗（纯保管损耗）等于入库总量减出库总量，再减水分杂质减量。水分杂质减量是入出库正常的减重，不计入保管损耗。"}, {"id": 40, "type": "单选", "question": "启动计算机粮情检测系统时，应按顺序启动( )、检测主机、系统软件。", "options": [{"key": "A", "text": "工作电源、计算机"}, {"key": "B", "text": "计算机、工作电源"}, {"key": "C", "text": "工作电源"}, {"key": "D", "text": "计算机"}], "answer": "A", "analysis": "启动粮情检测系统应先供工作电源，再开计算机，后启检测主机与系统软件，确保设备依次正常初始化，避免冲击。"}, {"id": 41, "type": "单选", "question": "利用计算机粮情检测系统检测温度时，应包括( )检测、仓温检测、粮温检测。", "options": [{"key": "A", "text": "气温"}, {"key": "B", "text": "内温"}, {"key": "C", "text": "货温"}, {"key": "D", "text": "墙温"}], "answer": "A", "analysis": "粮情温度检测包括气温（外温）、仓温和粮温三类，共同构成“三温”监测体系，用于判断粮堆安全状态。"}, {"id": 42, "type": "单选", "question": "粮情检测系统应由专人负责，操作人员须具备( )知识和电器设备知识，经培训合格后方可上岗。", "options": [{"key": "A", "text": "粮食保管"}, {"key": "B", "text": "粮食检验"}, {"key": "C", "text": "粮食经营"}, {"key": "D", "text": "粮食法规"}], "answer": "A", "analysis": "粮情检测系统由专人操作，须具备粮食保管知识和电器设备知识，经培训合格上岗，保管知识是正确判断粮情的基础。"}, {"id": 43, "type": "单选", "question": "粮情检测系统控制室应到达( )、通风，且防尘性能良好的要求。", "options": [{"key": "A", "text": "干燥"}, {"key": "B", "text": "采光"}, {"key": "C", "text": "密闭"}, {"key": "D", "text": "隔热"}], "answer": "A", "analysis": "控制室内有电子检测设备，怕潮怕尘，应达到干燥、通风且防尘性能良好的要求，以保证仪器正常运行。"}, {"id": 44, "type": "单选", "question": "校正粮情测控系统标准温度计的最小分度值为( )℃。", "options": [{"key": "A", "text": "0.1"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "answer": "A", "analysis": "用于校正粮情测控系统测温电缆的标准温度计精度要求高，其最小分度值应为0.1℃，才能准确校准测温误差。"}, {"id": 45, "type": "单选", "question": "电容式粮油水分检测仪是通过测量粮油( )的大小，间接表示出粮油的水分含量。", "options": [{"key": "A", "text": "电流量"}, {"key": "B", "text": "电压量"}, {"key": "C", "text": "介电系数"}, {"key": "D", "text": "电阻大小"}], "answer": "C", "analysis": "粮油水分不同则其介电常数（介电系数）不同，电容式水分检测仪通过测量介电系数大小，间接表示出粮油的水分含量。"}, {"id": 46, "type": "单选", "question": "在秋冬季节转换时期，有时粮堆表层发生结露，原因是粮温( )气温，粮堆内部热空气上升，遇到冷的粮面，便发生结露。", "options": [{"key": "A", "text": "高于"}, {"key": "B", "text": "低于"}, {"key": "C", "text": "等于"}, {"key": "D", "text": "小于"}], "answer": "A", "analysis": "秋冬转换时粮温高于气温，粮堆内部湿热空气上升，遇到温度较低的粮面便冷却凝结成露，导致表层结露。故原因是粮温“高于”气温。"}, {"id": 47, "type": "单选", "question": "磷化氢浓度检测仪可用于检测( )。", "options": [{"key": "A", "text": "所有气体浓度"}, {"key": "B", "text": "氧气浓度"}, {"key": "C", "text": "磷化氢气体浓度"}, {"key": "D", "text": "磷化氢和二氧化碳浓度"}], "answer": "C", "analysis": "磷化氢浓度检测仪专用于检测熏蒸中磷化氢（PH₃）气体浓度，不能检测所有气体或氧气，与报警仪、检测管配套使用。"}, {"id": 48, "type": "单选", "question": "磷化氢浓度检测装置包括( )、抽气泵、检测仪、报警仪、检测管等。", "options": [{"key": "A", "text": "取样管、取样阀、检测箱"}, {"key": "B", "text": "取样针、取样阀、检测箱"}, {"key": "C", "text": "取样管、取样架、检测箱"}, {"key": "D", "text": "取样管、取样阀、发生器"}], "answer": "A", "analysis": "磷化氢浓度检测装置由取样管、取样阀、检测箱、抽气泵、检测仪、报警仪、检测管等组成，用于在环流管道或仓内取样检测。"}, {"id": 49, "type": "单选", "question": "立筒仓和浅圆仓磷化氢气体检测取样点设置，要求在环流管道上设置气体取样点，必要时可在( )或粮堆中设置气体取样点。", "options": [{"key": "A", "text": "仓房仓顶外"}, {"key": "B", "text": "仓房墙壁外"}, {"key": "C", "text": "仓内空间"}, {"key": "D", "text": "仓外空间"}], "answer": "C", "analysis": "立筒仓和浅圆仓除在环流管道上设气体取样点外，必要时可在仓内空间或粮堆中设置取样点，以监测仓内PH₃浓度分布。"}, {"id": 50, "type": "单选", "question": "磷化氢气体检测仪和报警仪的传感器通常采用( )原理。", "options": [{"key": "A", "text": "定电压电解法"}, {"key": "B", "text": "定电压法"}, {"key": "C", "text": "定电解法"}, {"key": "D", "text": "电解法"}], "answer": "A", "analysis": "磷化氢检测仪和报警仪的电化学传感器通常采用定电压电解法，PH₃在电极上发生电解反应产生与浓度成正比的电流信号。"}, {"id": 51, "type": "单选", "question": "磷化氢气体检测仪内装有印刷电路板、( )、充电电池、电化学传感器等部件。", "options": [{"key": "A", "text": "声光报警器"}, {"key": "B", "text": "充电器"}, {"key": "C", "text": "充气器"}, {"key": "D", "text": "电解器"}], "answer": "A", "analysis": "便携式中磷化氢检测仪内装印刷电路板、声光报警器、充电电池、电化学传感器等，声光报警用于在浓度超限时警示人员。"}, {"id": 52, "type": "单选", "question": "用于磷化氢熏蒸环境中的安全监测的仪器是( )。", "options": [{"key": "A", "text": "磷化氢检测管"}, {"key": "B", "text": "磷化氢检测仪"}, {"key": "C", "text": "磷化氢报警仪"}, {"key": "D", "text": "气体浓度仪表"}], "answer": "C", "analysis": "用于磷化氢熏蒸环境中人员安全防护、超限声光报警的是磷化氢报警仪；检测管、检测仪用于浓度测定，安全监测首选报警仪。"}, {"id": 53, "type": "单选", "question": "磷化氢气体报警仪的测量范围为：( )。", "options": [{"key": "A", "text": "0 -20 ml/m3"}, {"key": "B", "text": "0–20 l/m3"}, {"key": "C", "text": "0 -1000 ml/m3"}, {"key": "D", "text": "0 -1000 l/m3"}], "answer": "A", "analysis": "磷化氢报警仪用于作业现场人员安全防护，测量范围通常为0–20 ml/m³（ppm级），对应职业接触安全限值，而非0–1000。"}, {"id": 54, "type": "单选", "question": "储粮害虫的检查期限规定：( )低于15℃时，检查期限由各地自定。", "options": [{"key": "A", "text": "粮温"}, {"key": "B", "text": "仓温"}, {"key": "C", "text": "气温"}, {"key": "D", "text": "平均温度"}], "answer": "A", "analysis": "储粮害虫检查期限与温度相关：粮温低于15℃时害虫活动弱，检查期限可适当放宽，由各地自定；高温季节需勤查。"}, {"id": 55, "type": "单选", "question": "锯谷盗身体呈细长扁平，黑褐色；头部呈梯形，后颊与复眼大小接近，外角钝圆；前胸背板纵长方形，背面有三条明显纵脊，中脊直，两侧脊稍成弧形，两侧缘各有( )锯齿状突起。", "options": [{"key": "A", "text": "4个"}, {"key": "B", "text": "5个"}, {"key": "C", "text": "6个"}, {"key": "D", "text": "7个"}], "answer": "C", "analysis": "锯谷盗的形态鉴别要点：前胸背板有三条明显纵脊，两侧缘各具6个锯齿状突起。这是与近似种区分的关键特征。"}, {"id": 56, "type": "单选", "question": "烟草甲身体呈( )，暗赤褐色，有光泽；触角11节锯齿状；前胸背板半圆形，后缘与鞘翅基部等宽；鞘翅表面光滑，无纵刻点纹。", "options": [{"key": "A", "text": "椭圆形"}, {"key": "B", "text": "扁长形"}, {"key": "C", "text": "细长形"}, {"key": "D", "text": "扁圆形"}], "answer": "A", "analysis": "烟草甲成虫体呈椭圆形、暗赤褐色有光泽，触角11节锯齿状，前胸背板半圆形，鞘翅表面光滑无纵刻点纹。故选“椭圆形”。"}, {"id": 57, "type": "单选", "question": "黄粉虫体形、体大小与黑粉虫相似，主要区别是:体暗赤褐色，无光泽；触角第3节短于1、2两节之和，末节长大于宽；前胸背板( )，鞘翅末端圆钝。", "options": [{"key": "A", "text": "宽等于长，近方形"}, {"key": "B", "text": "宽等于长，正方形"}, {"key": "C", "text": "宽大于长，横长方形"}, {"key": "D", "text": "长大于宽，纵长方形"}], "answer": "C", "analysis": "黄粉虫与黑粉虫主要区别：黄粉虫前胸背板宽大于长、呈横长方形，触角第3节短于1、2两节之和，鞘翅末端圆钝。故选C。"}, {"id": 58, "type": "单选", "question": "( ) 不是离心式通风机的主要组成部件。", "options": [{"key": "A", "text": "机壳"}, {"key": "B", "text": "电机"}, {"key": "C", "text": "风网"}, {"key": "D", "text": "出风口"}], "answer": "C", "analysis": "离心式通风机本体由机壳、叶轮、电机、进风口、出风口等组成；风网是配套的风道管路系统，不属于风机本身组成部件。"}, {"id": 59, "type": "单选", "question": "轴流式通风机的工作原理：当电动机带动叶轮旋转后，空气由进风口吸入，经过 叶片，获得能量，再经( )，这时部分动能转为静压，空气流出，送到风网。", "options": [{"key": "A", "text": "机壳"}, {"key": "B", "text": "电机"}, {"key": "C", "text": "扩散筒"}, {"key": "D", "text": "出风口"}], "answer": "C", "analysis": "轴流风机电动机带动叶轮旋转，空气经叶片获能后进入扩散筒，扩散筒使部分动压转为静压，再流出送至风网。故选“扩散筒”。"}, {"id": 60, "type": "单选", "question": "通风机的性能参数主要包括风量、风压、( )等。", "options": [{"key": "A", "text": "功率"}, {"key": "B", "text": "效率"}, {"key": "C", "text": "转速"}, {"key": "D", "text": "以上都是"}], "answer": "D", "analysis": "通风机主要性能参数包括风量、风压、功率、效率、转速、噪声等，题中“风量、风压、功率”之外效率、转速也均属于，故选“以上都是”。"}, {"id": 61, "type": "单选", "question": "通风机的空气输入端和输出端，分别与粮堆风网的空气输出端和输入端相联接的密闭循环通风系统，适用于( )。", "options": [{"key": "A", "text": "降温通风"}, {"key": "B", "text": "降水通风"}, {"key": "C", "text": "局部通风"}, {"key": "D", "text": "环流熏蒸"}], "answer": "D", "analysis": "通风机进、输出端分别与粮堆风网输出端、输入端相接形成密闭循环、气体不外排的系统，正是环流熏蒸所需，使PH₃在仓内循环；不适用于需换气的降温/降水通风。"}, {"id": 62, "type": "单选", "question": "冬季通风降温时，一定要注意通风初期仓顶( )问题。", "options": [{"key": "A", "text": "结块"}, {"key": "B", "text": "发热"}, {"key": "C", "text": "结露"}, {"key": "D", "text": "挂壁"}], "answer": "C", "analysis": "冬季通风降温时仓内湿热空气遇冷仓顶易凝结，通风初期要特别注意仓顶结露问题，必要时采取防止措施。故选“结露”。"}, {"id": 63, "type": "单选", "question": "填好通风记录卡是为了在日常管理中判断通风( )是否达到设计的要求等。对使用过程中数据进行分析后，从而提出改进方案。", "options": [{"key": "A", "text": "效果"}, {"key": "B", "text": "湿度"}, {"key": "C", "text": "时间"}, {"key": "D", "text": "条件"}], "answer": "A", "analysis": "填写通风记录卡是为了在日常管理中分析实际通风效果是否达到设计要求，据数据提出改进方案。故选“效果”。"}, {"id": 64, "type": "单选", "question": "机械通风操作开始之前不用填写记录卡的内容是( )。", "options": [{"key": "A", "text": "仓型"}, {"key": "B", "text": "尺寸"}, {"key": "C", "text": "粮食种类"}, {"key": "D", "text": "气体成分"}], "answer": "D", "analysis": "机械通风前记录卡应填仓型、尺寸、粮食种类、堆高、通风目的等，气体成分属于熏蒸/气调监测内容，非通风前必填项。"}, {"id": 65, "type": "单选", "question": "把导热系数小于( )的建筑材料称为隔热材料或保温材料。", "options": [{"key": "A", "text": "0.10瓦/米·度"}, {"key": "B", "text": "0.23瓦/米·度"}, {"key": "C", "text": "0.30瓦/米·度"}, {"key": "D", "text": "0.50瓦/米·度"}], "answer": "B", "analysis": "按建筑热工划分，导热系数小于0.23 W/(m·K)的材料称为隔热（保温）材料，数值越小隔热性越好（常见教材取0.23）。"}, {"id": 66, "type": "单选", "question": "膨胀珍珠岩是目前国内低温库、民用住宅及工业建筑中常用的( )状隔热材料。", "options": [{"key": "A", "text": "粉末"}, {"key": "B", "text": "块"}, {"key": "C", "text": "散粒"}, {"key": "D", "text": "板材"}], "answer": "C", "analysis": "膨胀珍珠岩质轻、多孔，呈散粒状，是国内低温库及工业建筑中常用的散粒状隔热材料，便于填充施工。"}, {"id": 67, "type": "单选", "question": "在空调机的布置形式上，对称分布可以使得仓房空间的( )气流掺混较好，温度较为均匀，但墙角附近区域的情况则较差。", "options": [{"key": "A", "text": "墙边区域"}, {"key": "B", "text": "中心区域"}, {"key": "C", "text": "进风口附近"}, {"key": "D", "text": "出风口附近"}], "answer": "B", "analysis": "空调机对称分布可使仓房中心区域气流掺混较好、温度较均匀，但墙角附近区域的气流混合和温度均匀性较差。故选“中心区域”。"}, {"id": 68, "type": "单选", "question": "采用单管通风降低储粮局部温度时，下列( )操作是不正确的。", "options": [{"key": "A", "text": "准备温湿度检测仪器及相关工具和用具检"}, {"key": "B", "text": "测仓内、外温湿度和粮温，判断能否进行降温处理"}, {"key": "C", "text": "关闭仓窗或通风换气口，启动风机，进行通风降温操作"}, {"key": "D", "text": "通风过程中及时检测仓内外温湿度和处理部位粮油温度"}], "answer": "C", "analysis": "单管通风降温应开启仓窗或通风换气口以排出湿热空气，“关闭仓窗启动风机”不正确；其余测温度、判断可行性、过程监测均正确。"}, {"id": 69, "type": "单选", "question": "单管通风设备是一种移动式通风降温设备，是由中压离心风机、通风管、( )及压管减速机组成", "options": [{"key": "A", "text": "进风口"}, {"key": "B", "text": "出风口"}, {"key": "C", "text": "交换器"}, {"key": "D", "text": "电控箱"}], "answer": "C", "analysis": "单管通风设备由中压离心风机、通风管、交换器及压管减速机等组成，交换器用于调节风量风压，实现移动式局部降温。"}, {"id": 70, "type": "单选", "question": "根据机械通风降水对通风参数的要求，按粮油水分高低选用与之相匹配的通风量。若粮油水分为14%，应匹配不低于( )的最低单位通风量。", "options": [{"key": "A", "text": "10m3/h.t"}, {"key": "B", "text": "15m3/h.t"}, {"key": "C", "text": "20m3/h.t"}, {"key": "D", "text": "25m3/h.t"}], "answer": "D", "analysis": "机械通风降水按粮油水分高低选配通风量，水分越高所需风量越大；水分14%时应匹配不低于25 m³/h·t的最低单位通风量（常见标准值，以官方教材为准）。"}, {"id": 71, "type": "单选", "question": "降水通风时为了避免出现因为粮温变化而发生通风效果逆转现象，直接将( )等于气温作为查定粮油平衡绝对湿度的条件。", "options": [{"key": "A", "text": "大气露点温度"}, {"key": "B", "text": "仓温"}, {"key": "C", "text": "粮温"}, {"key": "D", "text": "干燥温度"}], "answer": "C", "analysis": "为避免粮温变化引起通风效果逆转，降水通风时直接以“粮温等于气温”为条件查定粮油平衡绝对湿度，据以判断是否可降水。故选“粮温”。"}, {"id": 72, "type": "单选", "question": "包装粮通风垛不要打的( )，以免影响通风降水的效果。", "options": [{"key": "A", "text": "太大"}, {"key": "B", "text": "太小"}, {"key": "C", "text": "太低"}, {"key": "D", "text": "太短"}], "answer": "A", "analysis": "包装粮通风垛应留有通风道，垛不要堆得“太大”，否则内部通风不良、影响通风降水效果。故选“太大”。"}, {"id": 73, "type": "单选", "question": "掌握粮食水分与大气湿度之间的平衡关系，充分选择有利于通风降水、降温的环境条件，准确把握通风( )，保证降水、降温效果明显。", "options": [{"key": "A", "text": "风量"}, {"key": "B", "text": "风速"}, {"key": "C", "text": "时间"}, {"key": "D", "text": "时机"}], "answer": "D", "analysis": "应掌握粮食水分与大气湿度的平衡关系，选有利环境，准确把握通风“时机”，才能保证降水、降温效果明显。故选“时机”。"}, {"id": 74, "type": "单选", "question": "由于堆装储藏不利于采取有效的储藏技术和防范措施，所以应从粮食( )入手，为以后安全储藏打下良好基础。", "options": [{"key": "A", "text": "品种"}, {"key": "B", "text": "等级"}, {"key": "C", "text": "质量"}, {"key": "D", "text": "数量"}], "answer": "C", "analysis": "堆装储藏不利于采取有效储藏技术和防范措施，故应从粮食“质量”入手（严把入库质量关），为以后安全储藏打基础。故选“质量”。"}, {"id": 75, "type": "单选", "question": "在密闭储粮中，通常是一个低氧、高氮、高二氧化碳气体的储藏空间 ，这几种气体是非极性气体，应选用( )、尼龙、聚酯等极性塑料薄膜。", "options": [{"key": "A", "text": "聚乙烯"}, {"key": "B", "text": "聚丙烯"}, {"key": "C", "text": "聚氯乙烯"}, {"key": "D", "text": "塑料离子体"}], "answer": "C", "analysis": "密闭储粮空间为低氧、高氮、高二氧化碳的非极性气体环境，应选聚氯乙烯（PVC）等极性塑料薄膜以阻气；聚乙烯等非极性膜透气性大不宜。故选“聚氯乙烯”。"}, {"id": 76, "type": "单选", "question": "下列储粮防护剂中，商品名与其成分正确对应的是( )。", "options": [{"key": "A", "text": "杀虫松(甲基嘧啶硫磷)"}, {"key": "B", "text": "保粮安(马拉硫磷与增效醚合剂)"}, {"key": "C", "text": "凯安保(溴氰菊酯与增效醚合剂)"}, {"key": "D", "text": "谷虫净(溴氰菊酯与增效醚合剂)"}], "answer": "C", "analysis": "常见储粮防护剂对应：凯安保为溴氰菊酯与增效醚合剂；保粮安为马拉硫磷与增效醚；杀虫松（甲基嘧啶硫磷）、谷虫净成分不同。故C对应正确。"}, {"id": 77, "type": "单选", "question": "使用储粮防护剂，仓内施药时要敞开仓库的门窗，每人一次在仓内连续操作不宜超过( )。", "options": [{"key": "A", "text": "1h"}, {"key": "B", "text": "2h"}, {"key": "C", "text": "3h"}, {"key": "D", "text": "4h"}], "answer": "B", "analysis": "使用储粮防护剂时仓内应开窗通风，每人一次在仓内连续操作不宜超过2h，以防药剂吸入过量。故选“2h”。"}, {"id": 78, "type": "单选", "question": "储粮防护剂可以用于( )。", "options": [{"key": "A", "text": "短期储存的安全水分粮"}, {"key": "B", "text": "空仓、器材杀虫或打防虫线"}, {"key": "C", "text": "成品粮"}, {"key": "D", "text": "害虫大量发生的储粮"}], "answer": "B", "analysis": "储粮防护剂可用于空仓、器材杀虫或打防虫线；安全水分短期粮也可拌粮防护，但成品粮、害虫大量发生粮不宜单靠防护剂。故选B。"}, {"id": 79, "type": "单选", "question": "正压式空气呼吸器的气瓶背架上，一般固定有减压阀及接口、高压软管、压力表、中压软管、 ( )、报警哨、气瓶固定带、背架及背带等。", "options": [{"key": "A", "text": "流量阀"}, {"key": "B", "text": "压力阀"}, {"key": "C", "text": "供气阀"}, {"key": "D", "text": "出气阀"}], "answer": "C", "analysis": "正压式空气呼吸器组成包括减压阀及接口、高压软管、压力表、中压软管、供气阀、报警哨、气瓶固定带、背架背带等，供气阀向面罩供呼吸空气。"}, {"id": 80, "type": "单选", "question": "经常参加熏蒸的人员, 应( )定期进行健康检查。", "options": [{"key": "A", "text": "每年"}, {"key": "B", "text": "2年"}, {"key": "C", "text": "3年"}, {"key": "D", "text": "5年"}], "answer": "A", "analysis": "经常参加磷化氢等熏蒸作业的人员属接触有毒有害气体特殊工种，应每年定期进行健康检查，监护其身体健康。"}, {"id": 81, "type": "判断", "question": "道德对人们行为所干涉的范围要比法律广泛。", "options": ["√", "×"], "answer": "√", "analysis": "道德依靠内心信念和社会舆论调整几乎全部社会关系，而法律仅调整部分且靠国家强制力保障，因此道德对行为的干涉范围比法律更广泛。"}, {"id": 82, "type": "判断", "question": "淀粉在粮粒内以淀粉粒的形式存在。淀粉粒呈白色，有圆形、椭圆形和多角形等多种形状，表面有轮纹。各种不同粮种的淀粉粒，其形状和大小都基本相同。", "options": ["√", "×"], "answer": "×", "analysis": "不同粮种的淀粉粒在形状和大小上差异明显（如小麦、玉米、稻谷淀粉粒各异），并非“都基本相同”，故该陈述错误。"}, {"id": 83, "type": "判断", "question": "蛋白质在机体内的主要功能不是供给热量，但当机体内的糖和脂肪供应不足时，蛋白质也会分解产生热量以供机体所需。", "options": ["√", "×"], "answer": "√", "analysis": "蛋白质的主要功能是构成和修复机体组织，不是主要供能物质；但当糖和脂肪供应不足时，蛋白质可分解产生热量供机体所需，陈述正确。"}, {"id": 84, "type": "判断", "question": "不饱和脂肪酸性质稳定，不易被氧化而变质。", "options": ["√", "×"], "answer": "×", "analysis": "不饱和脂肪酸含有双键，化学性质活泼、易被氧化而酸败变质，正是植物油不如动物脂肪稳定的原因，故“性质稳定、不易氧化”错误。"}, {"id": 85, "type": "判断", "question": "灰分在粮食各部位的分布不平衡。谷类粮食，一般以颖壳、皮层、糊粉层所含的灰分最多，胚乳次之，胚部较少。", "options": ["√", "×"], "answer": "×", "analysis": "谷类粮食灰分以皮层、糊粉层、胚部含量最多，胚乳最少；题称“胚乳次之、胚部较少”颠倒了分布规律，故错误。"}, {"id": 86, "type": "判断", "question": "地方标准在必要时，可以与国家标准相抵触。", "options": ["√", "×"], "answer": "×", "analysis": "我国标准体系中地方标准不得低于国家标准，不得与国家标准相抵触，故“地方标准可与国标相抵触”错误。"}, {"id": 87, "type": "判断", "question": "实物标准是标准的补充形式，不具有法律效力。", "options": ["√", "×"], "answer": "×", "analysis": "实物标准（如粮食等级标准样品）是文字标准的补充和法定依据，具有法律效力，故“不具有法律效力”错误。"}, {"id": 88, "type": "判断", "question": "申请粮食收购资格应当提交书面申请，并提供资金、仓储设施、质量检验和保管能力等证明材料。", "options": ["√", "×"], "answer": "√", "analysis": "按《粮食流通管理条例》，申请粮食收购资格应提交书面申请，并提供资金、仓储设施、质量检验和保管能力等证明材料，陈述正确。"}, {"id": 89, "type": "判断", "question": "稻谷按出糙率和整精米率分等。", "options": ["√", "×"], "answer": "×", "analysis": "稻谷以出糙率作为分等定级的基础指标（结合整精米率、杂质、水分、黄粒米等），并非仅“按出糙率和整精米率”两项分等，表述不全面，故判错。"}, {"id": 90, "type": "判断", "question": "用手抓一把稻谷，摊平在手掌上，一方面掂其份量，一方面观察籽粒的成熟度、饱满度，然后综合判别稻谷的出糙率。", "options": ["√", "×"], "answer": "√", "analysis": "感官检验中可抓一把稻谷掂其分量、观察籽粒成熟度与饱满度，综合辅助判断出糙率高低，是常用的经验判别方法，陈述正确。"}, {"id": 91, "type": "判断", "question": "如果小麦中不完善粒比例较大，则容重较大。", "options": ["√", "×"], "answer": "×", "analysis": "不完善粒（虫蚀、破碎、霉变等）使籽粒不饱满、容重降低，故不完善粒比例大时容重应较小而非较大，陈述错误。"}, {"id": 92, "type": "判断", "question": "关闭计算机粮情检测系统时，应按顺序逐步关闭检测主机、计算机、工作电源。", "options": ["√", "×"], "answer": "√", "analysis": "关闭计算机粮情检测系统按与开机相反顺序：先关检测主机，再关计算机，最后断工作电源，以保护设备，陈述正确。"}, {"id": 93, "type": "判断", "question": "电阻式粮油水分检测仪是利用粮油含水量不同，其电阻率也不同的原理制成的，利用测量粮油的电阻率，间接表示出粮油的水分含量。", "options": ["√", "×"], "answer": "√", "analysis": "粮油含水量不同其电阻率也不同，电阻式水分检测仪通过测量电阻率间接表示水分含量，原理描述正确。"}, {"id": 94, "type": "判断", "question": "房式仓磷化氢气体检测取样点设置，要求每廒间内设置气体取样点应不少于5个，即在仓房的四角和中央各设置一个气体取样点，气体取样点深度一般在粮面下30cm-50cm。", "options": ["√", "×"], "answer": "√", "analysis": "房式仓每廒间磷化氢气体取样点应不少于5个（四角+中央），取样点深度一般在粮面下30–50cm，符合环流熏蒸检测规范，陈述正确。"}, {"id": 95, "type": "判断", "question": "密封储藏塑料薄膜外结露原因是：薄膜内温度低，薄膜外温度高，薄膜外空气达到露点时，将在薄膜外产生结露。", "options": ["√", "×"], "answer": "√", "analysis": "密闭储藏时膜内粮温低、膜外气温高，膜外湿热空气遇冷膜表面达到露点时便在薄膜外表面产生结露，描述正确。"}, {"id": 96, "type": "判断", "question": "磷化氢气体检测仪的测量范围为：0–1000 ml/m3。", "options": ["√", "×"], "answer": "√", "analysis": "磷化氢浓度检测仪（用于检测仓内熏蒸浓度）测量范围一般为0–1000 ml/m³，与报警仪（0–20 ml/m³）不同，陈述正确。"}, {"id": 97, "type": "判断", "question": "储粮害虫陷井诱捕器是根据储粮害虫的钻孔习性而设计的。", "options": ["√", "×"], "answer": "√", "analysis": "储粮害虫陷阱诱捕器利用害虫向上或向钻孔移动的习性设计，用于诱集监测虫害，陈述正确。"}, {"id": 98, "type": "判断", "question": "黑粉虫成虫身体呈长椭圆形，深黑褐色，无光泽；触角11节，近念珠状；前胸背板长宽接近相等，鞘翅末端略尖。", "options": ["√", "×"], "answer": "√", "analysis": "黑粉虫成虫呈长椭圆形、深黑褐色、无光泽，触角11节近念珠状，前胸背板长宽接近相等，鞘翅末端略尖，形态描述与标准相符，正确。"}, {"id": 99, "type": "判断", "question": "良好的隔热结构，不仅能保持仓温和粮温的稳定，同时给过夏粮食一个安全的储藏环境。", "options": ["√", "×"], "answer": "√", "analysis": "良好的仓房隔热结构可减少外界温度影响，保持仓温、粮温稳定，为过夏粮食提供安全的储藏环境，陈述正确。"}, {"id": 100, "type": "判断", "question": "磷化氢发生器的残液可以排入下水道、河流和沟渠中。", "options": ["√", "×"], "answer": "×", "analysis": "磷化氢发生器的残液仍含毒性（遇水可继续产生PH₃），严禁排入下水道、河流和沟渠，须专门收集无害化处理，故陈述错误。"}, {"id": 101, "type": "单选", "question": "道德对人们行为所干涉的范围( )。", "options": [{"key": "A", "text": "与法律一样"}, {"key": "B", "text": "要比法律狭窄"}, {"key": "C", "text": "要比法律广泛"}, {"key": "D", "text": "与法律不可比"}], "answer": "C", "analysis": "道德依靠社会舆论、传统习俗和内心信念起作用，其约束范围覆盖人们行为与思想活动的方方面面，包括法律未涉及的领域；而法律仅以国家强制力规范违法行为。因此道德对人们行为的干涉范围比法律更广泛，故选C。"}, {"id": 102, "type": "单选", "question": "当一意外事故发生时，岗位从业人员及时呼救，并积极抢救，直至以身殉职，该事例集中反映了企业职工的( )精神。", "options": [{"key": "A", "text": "忠于职守"}, {"key": "B", "text": "执行规范"}, {"key": "C", "text": "爱岗敬业"}, {"key": "D", "text": "遵纪守法"}], "answer": "A", "analysis": "从业人员在意外事故中及时呼救、积极抢救直至以身殉职，体现的是坚守岗位、尽职尽责、不惜牺牲的忠于职守精神。其他选项（执行规范、爱岗敬业、遵纪守法）均不如“忠于职守”精准概括这种临危履职、保全国家财产的行为，故选A。"}, {"id": 103, "type": "单选", "question": "粮食仓储某从业人员在库区内吸烟和用火，其行为违背了( )的职业守则。", "options": [{"key": "A", "text": "精益求精"}, {"key": "B", "text": "执行规范"}, {"key": "C", "text": "忠于职守"}, {"key": "D", "text": "文明生产"}], "answer": "B", "analysis": "粮食仓储有严格的消防安全规定，库区内严禁吸烟和动用明火，库区吸烟用火直接违反了安全生产操作规程和执行规范的职业守则。精益求精、忠于职守、文明生产均未被此行为直接违背，故选B。"}, {"id": 104, "type": "单选", "question": "( ) 昆虫具有卵、幼虫、蛹和成虫四个不同的虫期。", "options": [{"key": "A", "text": "表变态"}, {"key": "B", "text": "原变态"}, {"key": "C", "text": "不完全变态"}, {"key": "D", "text": "完全变态"}], "answer": "D", "analysis": "完全变态昆虫的生长发育经历卵、幼虫、蛹、成虫四个完全不同形态的阶段（如蛾类、甲虫）；不完全变态（渐变态）无蛹期，仅有卵、若虫、成虫。题干所述四个虫期正是完全变态的特征，故选D。"}, {"id": 105, "type": "单选", "question": "粮堆中的空气通常并非是静止不流通的，而是根据粮堆内的( )和季节的变化，总是有微气流存在的。", "options": [{"key": "A", "text": "湿度不同"}, {"key": "B", "text": "虫害情况"}, {"key": "C", "text": "杂质分布"}, {"key": "D", "text": "温度分布"}], "answer": "D", "analysis": "粮堆内各处温度分布不同，造成空气密度差和热压差，从而在粮堆内部形成总是存在的微气流；这种微气流随温度分布和季节变化而流动。湿度、虫害、杂质分布并非驱动微气流的根本原因，故选D。"}, {"id": 106, "type": "单选", "question": "影响粮食呼吸的外部因素主要是（ ）。", "options": [{"key": "A", "text": "水分"}, {"key": "B", "text": "温度"}, {"key": "C", "text": "环境气体成分"}, {"key": "D", "text": "水分、温度、环境气体成分"}], "answer": "D", "analysis": "粮食呼吸强度受多种外部因素共同影响：水分越高、温度越高呼吸越强，氧气充足促进有氧呼吸而高二氧化碳或低氧则抑制呼吸。三者（水分、温度、环境气体成分）均为关键外部因素，故选D。"}, {"id": 107, "type": "单选", "question": "粮食后熟期的长短，随粮种、品种以及储藏条件的不同而有很大的差异。有的后熟期较长，可达( )。", "options": [{"key": "A", "text": "1个月"}, {"key": "B", "text": "6个月"}, {"key": "C", "text": "3个月"}, {"key": "D", "text": "8个月"}], "answer": "C", "analysis": "粮食收获后需经过后熟期才能达到生理成熟，后熟期长短随粮种、品种和储藏条件差异很大，一般数天至数月，有的较长可达约3个月。1个月偏短、6或8个月过长不符合常见后熟期范围，故选C。"}, {"id": 108, "type": "单选", "question": "申请粮食收购资格应当提交书面申请，并提供( )、仓储设施、质量检验和保管能力等证明材料。", "options": [{"key": "A", "text": "资金"}, {"key": "B", "text": "诚信"}, {"key": "C", "text": "地方"}, {"key": "D", "text": "信用"}], "answer": "A", "analysis": "依据《粮食流通管理条例》，申请粮食收购资格须提交书面申请，并提供资金、仓储设施、质量检验和保管能力等证明材料，资金是经营能力的前提。诚信、信用、地方均不构成法定须提交的证明材料类别，故选A。"}, {"id": 109, "type": "单选", "question": "( )是专门储存中央储备粮的企业，同时规定中央储备粮也可以由具备条件的其他企业代储。", "options": [{"key": "A", "text": "中国储备粮管理总公司直属企业"}, {"key": "B", "text": "中国储备粮管理总公司"}, {"key": "C", "text": "国家粮食和物资储备局直属企业"}, {"key": "D", "text": "国务院国资委"}], "answer": "A", "analysis": "《中央储备粮管理条例》规定，中国储备粮管理总公司直属企业是专门储存中央储备粮的企业，同时中央储备粮也可由具备条件的其他企业代储。中储粮总公司是管理主体而非储存企业本身，故选A。"}, {"id": 110, "type": "单选", "question": "( )工作除了保护劳动者安全、健康外，还包括保障机器设备安全运行及财产安全。", "options": [{"key": "A", "text": "安全生产"}, {"key": "B", "text": "劳动保护"}, {"key": "C", "text": "日常"}, {"key": "D", "text": "人身保护"}], "answer": "A", "analysis": "安全生产是指在进行生产活动中，防止人身伤亡和设备事故、保障劳动者安全健康以及机器设备安全运行和财产安全的综合性工作，涵盖人身、设备、财产多方面。劳动保护侧重劳动者保护，故选A。"}, {"id": 111, "type": "单选", "question": "托盘天平称量前，应先调节天平的( )，即在托盘天平不载重的情况下，向左或向右调节天平托盘下的平衡螺丝，使指针恰好停在刻度盘中间的位置上。", "options": [{"key": "A", "text": "零点"}, {"key": "B", "text": "平衡点"}, {"key": "C", "text": "水平"}, {"key": "D", "text": "灵敏度"}], "answer": "A", "analysis": "托盘天平称量前必须先调“零点”，即在不载重时调节托盘下的平衡螺丝，使指针恰好停在刻度盘中央位置，以保证称量基准准确。平衡点、水平、灵敏度均非该调节步骤的名称，故选A。"}, {"id": 112, "type": "单选", "question": "储粮微生物可将粮食中的蛋白质首先分解为( )。", "options": [{"key": "A", "text": "脂肪酸"}, {"key": "B", "text": "葡萄糖"}, {"key": "C", "text": "氨基酸"}, {"key": "D", "text": "维生素"}], "answer": "C", "analysis": "储粮微生物分解粮食成分时，蛋白质在蛋白酶作用下首先水解为肽和氨基酸，然后再被进一步分解为氨和有机酸；脂肪酸来自脂肪分解，葡萄糖来自糖类分解。故蛋白质首先分解为氨基酸，选C。"}, {"id": 113, "type": "单选", "question": "具有触杀作用的空仓杀虫剂严禁用于（ ）杀虫。", "options": [{"key": "A", "text": "仓房"}, {"key": "B", "text": "实仓粮面上的空间"}, {"key": "C", "text": "器材"}, {"key": "D", "text": "设备"}], "answer": "B", "analysis": "具有触杀作用的空仓杀虫剂（如敌敌畏等）可用于空仓、器材、设备的杀虫，但严禁用于实仓粮面上方空间，以免药剂残留直接污染粮食、危害食用安全。仓房、器材、设备均属允许使用范围，故选B。"}, {"id": 114, "type": "单选", "question": "做好空仓和器材杀虫的安全防护很重要，以下说法不正确的是 ( )。", "options": [{"key": "A", "text": "应检查施药器械有无漏水、喷嘴是否通畅，连接是否牢固。"}, {"key": "B", "text": "配制和施药时，若不慎溅入眼中，应立即用肥皂水清洗干净。"}, {"key": "C", "text": "如出现乏力、头昏、恶心、呕吐、皮肤红肿等中毒现象，应立即离开现场。"}, {"key": "D", "text": "操作完毕后，要更换衣服，用肥皂水洗手洗脸，并注意休息。"}], "answer": "B", "analysis": "空仓和器材杀虫安全防护中，若药液不慎溅入眼中，应立即用大量清水（流动水）冲洗并及时就医，绝不可用肥皂水清洗（肥皂水有刺激性会加重损伤）。其他选项均为正确防护措施，故不正确的是B。"}, {"id": 115, "type": "单选", "question": "带式输送机输送带跑偏的原因，不包括以下( )", "options": [{"key": "A", "text": "传动滚筒或机尾滚筒两头直径大小不一"}, {"key": "B", "text": "机头传动滚筒与尾部滚筒不平行"}, {"key": "C", "text": "机头部或在输送带上有水，造成驱动滚输送输送筒和输送带间的摩擦系数降低"}, {"key": "D", "text": "托辊安装不正"}], "answer": "C", "analysis": "输送带跑偏主要由机械几何偏差引起：滚筒直径不一、头尾滚筒不平行、托辊安装不正等；机头或带面积水会降低摩擦系数导致打滑而非跑偏。因此“有水降低摩擦系数”不属于跑偏原因，选C。"}, {"id": 116, "type": "单选", "question": "预防与处理输送带打滑，以下( )的做法是错误的。", "options": [{"key": "A", "text": "经常检查输送带的张紧程度，适度拉紧输送带"}, {"key": "B", "text": "经常检查输送带接头情况"}, {"key": "C", "text": "装载量要控制，严禁超载运行"}, {"key": "D", "text": "停机时无需卸完输送带上的粮油，但不得再装载"}], "answer": "D", "analysis": "预防和处理输送带打滑要求停机前应将带上物料卸空，严禁带负荷停机，否则会加剧打滑、损伤胶带和接头。A、B、C均为正确做法，故错误的做法是D。"}, {"id": 117, "type": "单选", "question": "目前使用的油泵根据工作原理可分次齿轮泵、螺杆泵等。齿轮泵由泵体、齿轮、前后泵盖、 ( )、轴承及密封装置等部件组成。", "options": [{"key": "A", "text": "安全阀"}, {"key": "B", "text": "真空阀"}, {"key": "C", "text": "压力阀"}, {"key": "D", "text": "单向阀"}], "answer": "A", "analysis": "齿轮泵由泵体、齿轮、前后泵盖、安全阀、轴承及密封装置等部件组成，其中安全阀用于在压力过高时泄压、保护泵体。真空阀、压力阀、单向阀均非齿轮泵标准组成部件，故选A。"}, {"id": 118, "type": "单选", "question": "房式仓具有( )等储藏性能优势。", "options": [{"key": "A", "text": "较大的有效面积，便于清扫、翻倒粮堆"}, {"key": "B", "text": "机械化和自动化程度高"}, {"key": "C", "text": "仓隔热性能好"}, {"key": "D", "text": "进出仓作业效率高"}], "answer": "A", "analysis": "房式仓（平房仓）具有较大的有效使用面积，仓内空间开阔，便于人工和机械清扫、翻倒粮堆；其机械化自动化程度一般低于筒仓和浅圆仓。故其突出优势是便于清扫翻倒，选A。"}, {"id": 119, "type": "单选", "question": "下列( )不属于筒仓安全性能检查的内容", "options": [{"key": "A", "text": "检查流程皮带、气压阀等部件是否调整合适"}, {"key": "B", "text": "检查仓顶通风口、进出粮口是否保持紧闭"}, {"key": "C", "text": "检查仓内电线或其他通信线无老化、脱皮、龟裂、裸露等情况"}, {"key": "D", "text": "检查入粮质量和入粮环节的清理"}], "answer": "D", "analysis": "筒仓安全性能检查针对仓体及设备安全，如皮带流程、通风口紧闭、线路老化裸露等；而入粮质量和入粮环节清理属于仓储质量检验与管理范畴，不属于仓体安全性能检查内容，故选D。"}, {"id": 120, "type": "单选", "question": "关于浅圆仓储藏性能的说法，( ) 是不对的。", "options": [{"key": "A", "text": "进出粮机械化水平比平房仓的高，比筒仓的低"}, {"key": "B", "text": "粮堆比平房仓、筒仓的更大，故其湿热扩散更加突出"}, {"key": "C", "text": "浅圆仓入粮时，自动分级现象要比平房仓的严重"}, {"key": "D", "text": "吨粮单位造价远低于平房仓和筒仓"}], "answer": "D", "analysis": "浅圆仓吨粮单位造价实际介于平房仓与立筒仓之间（一般低于立筒仓、高于平房仓），并非“远低于”两者，该项表述错误。A、B、C对浅圆仓性能的描述均基本正确，故选D。"}, {"id": 121, "type": "单选", "question": "在加工和储存过程中，油脂中的水分、( )、糖类、蛋白质、饼屑以及泥土等杂质，沉淀到大罐底层形成油脚。", "options": [{"key": "A", "text": "磷脂"}, {"key": "B", "text": "脱磷脂"}, {"key": "C", "text": "白蜡"}, {"key": "D", "text": "蜂蜡"}], "answer": "A", "analysis": "油脂在加工储存过程中，水分、磷脂、糖类、蛋白质、饼屑及泥土等杂质因比重较大沉淀到大罐底层形成油脚，其中磷脂是主要胶质成分（水化脱胶即去除磷脂）。脱磷脂、白蜡、蜂蜡均不形成油脚，故选A。"}, {"id": 122, "type": "单选", "question": "稻谷的不完善粒是指未成熟或受到损伤但尚有使用价值的稻谷颗粒，不包括( )。", "options": [{"key": "A", "text": "未熟粒"}, {"key": "B", "text": "破碎粒"}, {"key": "C", "text": "虫蚀粒"}, {"key": "D", "text": "病斑粒"}], "answer": "B", "analysis": "稻谷不完善粒指未成熟或受损伤但尚有使用价值的颗粒，包括未熟粒、虫蚀粒、病斑粒、生芽粒、霉变粒等；破碎粒属于机械损伤粒，按破碎粒（或杂质相关）单独归类，不计入不完善粒，故选B。"}, {"id": 123, "type": "单选", "question": "小麦赤霉病粒最大允许含量为( )，单立赤霉病项目，按不完善粒归属。", "options": [{"key": "A", "text": "2.0%"}, {"key": "B", "text": "3.0%"}, {"key": "C", "text": "4.0%"}, {"key": "D", "text": "5.0%"}], "answer": "C", "analysis": "国家标准规定小麦赤霉病粒最大允许含量为4.0%，该指标单独列出并归入不完善粒计算，超过限量则小麦不能食用或降级。2.0%、3.0%、5.0%均非该限量值，故选C。"}, {"id": 124, "type": "单选", "question": "小麦的不完善粒，不包括( )。", "options": [{"key": "A", "text": "生芽粒"}, {"key": "B", "text": "未熟粒"}, {"key": "C", "text": "虫蚀粒"}, {"key": "D", "text": "病斑粒"}], "answer": "B", "analysis": "按教材划分，小麦不完善粒包括虫蚀粒、病斑粒、生芽粒、霉变粒等，未熟粒（瘪粒）不列入小麦不完善粒而归入其他项目。故小麦不完善粒不包括未熟粒，选B。"}, {"id": 125, "type": "单选", "question": "通过视觉观察小麦的( )等，可以初步判定容重的大小。", "options": [{"key": "A", "text": "色泽"}, {"key": "B", "text": "形态、质地"}, {"key": "C", "text": "不完善粒"}, {"key": "D", "text": "以上都是"}], "answer": "D", "analysis": "容重与籽粒的大小、形状、饱满度、整齐度及不完善粒含量密切相关，通过视觉观察小麦的色泽、形态质地和不完善粒情况，可初步判断其容重高低。以上因素均有参考价值，故选D。"}, {"id": 126, "type": "单选", "question": "玉米以三等为中等质量标准，其容重为( ) 克/升。", "options": [{"key": "A", "text": "≥740"}, {"key": "B", "text": "≥720且<740"}, {"key": "C", "text": "≥690且<720"}, {"key": "D", "text": "≥660且<690"}], "answer": "D", "analysis": "玉米以三等作为中等质量标准，其容重指标对应≥660且<690克/升（教材等级划分）；容重越低则等级越低。A、B、C对应更高等级或区间，中等（三等）对应D。"}, {"id": 127, "type": "单选", "question": "习惯上把在室温下呈液态的油脂称作( )。", "options": [{"key": "A", "text": "油"}, {"key": "B", "text": "油脚"}, {"key": "C", "text": "油蜡"}, {"key": "D", "text": "脂肪"}], "answer": "A", "analysis": "习惯上按常温下的物态区分：室温下呈液态的油脂称为“油”，呈固态或半固态的称为“脂肪”（脂）。油脚是沉淀物、油蜡是蜡质，均非此称谓，故选A。"}, {"id": 128, "type": "单选", "question": "油脂色泽是油脂的一项重要物理指标，不同品种、不同加工等级的油脂色泽不同。花生油一般呈( )", "options": [{"key": "A", "text": "淡黄色至橙黄色"}, {"key": "B", "text": "黄色至棕黄色"}, {"key": "C", "text": "黄色至棕色"}, {"key": "D", "text": "橙黄至棕色"}], "answer": "A", "analysis": "花生油因含胡萝卜素等色素，一般呈淡黄色至橙黄色，这是其典型色泽特征，也是品质分级的参考指标之一。黄至棕黄、黄至棕等多为其他油种色泽，故选A。"}, {"id": 129, "type": "单选", "question": "在室内判定油脂色泽、透明度时，判定场所要有足够的光线强度，室内色彩柔和，避免强对比色，附近不能有( )存在。", "options": [{"key": "A", "text": "黑、白、灰三种色调"}, {"key": "B", "text": "红、黄、绿三种色调"}, {"key": "C", "text": "灰色"}, {"key": "D", "text": "白色"}], "answer": "B", "analysis": "油脂色泽、透明度判定要求在光线柔和、无强对比色的场所进行，附近不能存在红、黄、绿三种色调，以免视觉对比干扰对色泽的准确判断。黑白色调影响较小，故选B。"}, {"id": 130, "type": "单选", "question": "下列 ( ) 物料不适合使用斗式提升机输送。", "options": [{"key": "A", "text": "粉状"}, {"key": "B", "text": "粒状"}, {"key": "C", "text": "袋装"}, {"key": "D", "text": "小块状"}], "answer": "C", "analysis": "斗式提升机依靠料斗连续挖取和提升，适用于粉状、粒状、小块状等散粒物料；袋装物料为成件包装，需采用皮带或叉车等设备输送，不适合斗提机。故选C。"}, {"id": 131, "type": "单选", "question": "下列( ) 是斗式提升机的缺点。", "options": [{"key": "A", "text": "结构简单、紧凑，占地面积小"}, {"key": "B", "text": "工作平稳可靠，提升高度高"}, {"key": "C", "text": "产量大，耗用动力少"}, {"key": "D", "text": "过载敏感"}], "answer": "D", "analysis": "斗式通风（斗式提升机）的优点是结构简单紧凑、占地小、工作平稳、提升高度大、产量大；其突出缺点是过载敏感，易因进料不均造成堵塞。A、B、C均为优点，故选D。"}, {"id": 132, "type": "单选", "question": "关于斗式提升机设置泄爆孔，下列( )的描述是不正确的。", "options": [{"key": "A", "text": "当压力增大时，能自动泄爆降压"}, {"key": "B", "text": "泄爆孔不可设置于机头"}, {"key": "C", "text": "泄爆孔是在机壳上开设若干个圆孔"}, {"key": "D", "text": "泄爆孔可设置于机座"}], "answer": "B", "analysis": "斗提机泄爆孔用于在粉尘爆炸压力骤升时自动泄压，应设在机头、机座等易超压部位（机头是爆炸常发处必须设），泄爆孔可设于机头也可设于机座。说“不可设置于机头”是错误的，故选B。"}, {"id": 133, "type": "单选", "question": "在使用斗式提升机时，不列做法 ( ) 是不对的。", "options": [{"key": "A", "text": "遵守“无载起动，空载停车”的原则"}, {"key": "B", "text": "进料应均匀，出料管应通畅，以免引起堵塞"}, {"key": "C", "text": "正常工作时，料斗带应在机筒中间位置"}, {"key": "D", "text": "发生突然停机，应先将料斗内积存的物料排出后再开机"}], "answer": "D", "analysis": "斗式提升机使用要求遵循“无载起动、空载停车”、进料均匀、料斗带居中；发生突然停机时，应先切断电源、查明原因并排除故障，不可盲目先排料再开机，否则易致堵塞或安全事故。故D的做法不对，选D。"}, {"id": 134, "type": "单选", "question": "下列做法( )，不符合刮板输送机的安全使用要求。", "options": [{"key": "A", "text": "必须了解刮板输送机的适用范围"}, {"key": "B", "text": "必须了解刮板输送机适宜输送的物料特性"}, {"key": "C", "text": "必须正确地选型"}, {"key": "D", "text": "开机后，操作人员就可以在运行过程中离机"}], "answer": "D", "analysis": "刮板输送机安全使用要求操作人员了解其适用范围、物料特性和正确选型；运行时必须有人监护，开机后操作人员不得离开机器。离机属于违规，故选D。"}, {"id": 135, "type": "单选", "question": "电子汽车衡和非连续累计料斗秤使用之前，将系统配置的打印机、屏幕显示器等( )联机。", "options": [{"key": "A", "text": "机带设备"}, {"key": "B", "text": "内部部件"}, {"key": "C", "text": "内部设备"}, {"key": "D", "text": "外部设备"}], "answer": "D", "analysis": "电子汽车衡和非连续累计料斗秤使用前，需将系统配置的打印机、屏幕显示器等外部设备与主机正确联机，方可正常计量和记录。机带设备、内部部件、内部设备均非规范称谓，故选D。"}, {"id": 136, "type": "单选", "question": "按电子汽车衡的安装方式，可分为地上衡和( )。", "options": [{"key": "A", "text": "模拟式电子汽车衡"}, {"key": "B", "text": "数字式电子汽车衡"}, {"key": "C", "text": "地中衡"}, {"key": "D", "text": "地下衡"}], "answer": "C", "analysis": "按安装方式，电子汽车衡分为地上衡（秤体与地面平齐或略高）和地中衡（秤体埋入地下）；模拟式/数字式是按信号方式划分。故选C。"}, {"id": 137, "type": "单选", "question": "由于包装储藏有利于粮油的装卸、运输、( )和保持纯度，所以在中转粮库、保管成品粮、种子粮时采用较多。", "options": [{"key": "A", "text": "取样"}, {"key": "B", "text": "测温"}, {"key": "C", "text": "通风降温"}, {"key": "D", "text": "害虫防治"}], "answer": "C", "analysis": "包装储藏因粮包分隔、堆码通风垛便于散热，有利于粮油的装卸、运输、通风降温和保持纯度，故在中转粮库、成品粮和种子粮储藏中采用较多。取样、测温、害虫防治并非其核心优势，故选C。"}, {"id": 138, "type": "单选", "question": "储存半年以上一年以内的原粮，其自然损耗按不超过( )定额处置，在定额以内的据实核销。", "options": [{"key": "A", "text": "0.1%"}, {"key": "B", "text": "0.15%"}, {"key": "C", "text": "0.2%"}, {"key": "D", "text": "0.25%"}], "answer": "B", "analysis": "粮油储存自然损耗实行定额管理：储存半年以内不超过0.10%，半年以上一年以内不超过0.15%，一年以上有更高定额；题干所指半年至一年区间对应0.15%。故选B。"}, {"id": 139, "type": "单选", "question": "关闭计算机粮情检测系统时，应按顺序逐步关闭( )、计算机、工作电源。", "options": [{"key": "A", "text": "检测主机"}, {"key": "B", "text": "检测分机"}, {"key": "C", "text": "分线器"}, {"key": "D", "text": "采集器"}], "answer": "A", "analysis": "计算机粮情检测系统关机应按逆序进行，先关闭检测主机，再关计算机，最后切断工作电源，以防数据丢失和设备损坏。检测分机、分线器、采集器均非关机首步，故选A。"}, {"id": 140, "type": "单选", "question": "利用计算机粮情检测系统检测湿度时，检测内容应包括气湿检测、( )检测。", "options": [{"key": "A", "text": "外湿"}, {"key": "B", "text": "墙湿"}, {"key": "C", "text": "仓湿"}, {"key": "D", "text": "粮湿"}], "answer": "C", "analysis": "利用计算机粮情检测系统检测湿度时，检测内容应包括气湿（大气湿度）检测和仓湿（仓内空气湿度）检测，以掌握仓内外湿度状况。外湿、墙湿、粮湿非标准分类，故选C。"}, {"id": 141, "type": "单选", "question": "粮情检测系统应由专人负责，操作人员须具备粮食保管知识和( )知识，经培训合格后方可上岗。", "options": [{"key": "A", "text": "粮食机械"}, {"key": "B", "text": "粮食检验"}, {"key": "C", "text": "电器设备"}, {"key": "D", "text": "自动化控制"}], "answer": "C", "analysis": "粮情检测系统涉及电气与自动控制，操作人员除具备粮食保管知识外，还须具备电器设备知识，经培训合格后方可上岗，以保障人身和设备安全。粮食机械、检验、自动化控制均不如电器设备知识直接必要，故选C。"}, {"id": 142, "type": "单选", "question": "粮情检测系统防病毒要求，操作人员要定期检测计算机病毒，发现系统感染病毒时，应立即消除病毒；还应定期对检测数据进行( )，确保检测数据的安全。", "options": [{"key": "A", "text": "计算"}, {"key": "B", "text": "压缩"}, {"key": "C", "text": "备份"}, {"key": "D", "text": "删除"}], "answer": "C", "analysis": "粮情检测系统防病毒要求定期查杀病毒，并定期对检测数据进行备份，防止病毒破坏或系统故障导致粮情数据丢失，确保数据安全。计算、压缩、删除均不能保障安全，故选C。"}, {"id": 143, "type": "单选", "question": "密封储藏塑料薄膜外结露原因是：薄膜外( )高于薄膜内，薄膜外空气达到露点时，将在薄膜外产生结露。", "options": [{"key": "A", "text": "温度"}, {"key": "B", "text": "湿度"}, {"key": "C", "text": "空气"}, {"key": "D", "text": "密度"}], "answer": "A", "analysis": "密封储藏时塑料薄膜外侧结露，是因为薄膜外温度高于薄膜内，当外侧空气接触较冷的膜面达到露点时，水蒸气在膜外凝结成露。湿度、空气、密度并非直接原因，故选A。"}, {"id": 144, "type": "单选", "question": "房式仓磷化氢气体检测取样点设置，要求每廒间内设置气体取样点应不少于5个，即在( )。", "options": [{"key": "A", "text": "仓房的四角和中央各设置一个气体取样点"}, {"key": "B", "text": "粮堆的上、中、下、粮面、仓底各设置一个气体取样点"}, {"key": "C", "text": "仓房空间、通风道内以及粮堆上、中、下各设置一个气体取样点"}, {"key": "D", "text": "粮堆四面和表面各设置一个气体取样点"}], "answer": "A", "analysis": "房式仓磷化氢气体检测取样点设置要求每廒间不少于5个，即在仓房的四角和中央各设1个，以代表仓内不同位置气体分布。上中下、空间通风道等是筒仓/浅圆仓的补充设置方式，故选A。"}, {"id": 145, "type": "单选", "question": "立筒仓和浅圆仓磷化氢气体检测取样点设置，要求在( )设置气体取样点，必要时可在仓内空间或粮堆中设置气体取样点。", "options": [{"key": "A", "text": "环流管道上"}, {"key": "B", "text": "仓房底部"}, {"key": "C", "text": "通风道内"}, {"key": "D", "text": "粮堆四面"}], "answer": "A", "analysis": "立筒仓和浅圆仓因粮堆深、密闭性好，磷化氢检测取样点主要设在环流管道上，利用环流系统采样，必要时再在仓内空间或粮堆中增设。底部、通风道、粮堆四面均非首选，故选A。"}, {"id": 146, "type": "单选", "question": "磷化氢气体检测仪配有吸气泵，通过( )将被检测气体自动吸送到检测仪器的传感器室，可以检测远距离的气体中的磷化氢浓度。", "options": [{"key": "A", "text": "充气泵"}, {"key": "B", "text": "环流管"}, {"key": "C", "text": "取样管"}, {"key": "D", "text": "压缩器"}], "answer": "C", "analysis": "磷化氢气体检测仪配有吸气泵，通过取样管将被测气体从远处自动吸送至传感器室进行检测，从而可测远距离气体浓度。充气泵、环流管、压缩器均非该采样部件，故选C。"}, {"id": 147, "type": "单选", "question": "磷化氢气体检测仪的测量范围为：( )。", "options": [{"key": "A", "text": "0-1000ml/m3"}, {"key": "B", "text": "0-500ml/m3"}, {"key": "C", "text": "0-400ml/m3"}, {"key": "D", "text": "0–600ml/m3"}], "answer": "A", "analysis": "磷化氢气体检测仪用于检测熏蒸浓度，其测量范围一般为0–1000 ml/m³（约0–1000 ppm），覆盖熏蒸所需的高浓度区间。500、400、600均过小，故选A。"}, {"id": 148, "type": "单选", "question": "磷化氢报警仪用于磷化氢熏蒸环境中的( )监测。", "options": [{"key": "A", "text": "安全"}, {"key": "B", "text": "健康"}, {"key": "C", "text": "身体"}, {"key": "D", "text": "气体"}], "answer": "A", "analysis": "磷化氢报警仪用于磷化氢熏蒸环境中对有毒气体浓度进行安全监测，当浓度超过安全阈值即报警，保障人员安全。健康、身体、气体均不如“安全监测”准确，故选A。"}, {"id": 149, "type": "单选", "question": "( )粮油水分检测仪是利用粮油含水量不同，其电阻率也不同的原理制成的，利用测量粮油的电阻率，间接表示出粮油的水分含量。", "options": [{"key": "A", "text": "电阻式"}, {"key": "B", "text": "电容式"}, {"key": "C", "text": "电导式"}, {"key": "D", "text": "电离式"}], "answer": "A", "analysis": "电阻式粮油水分检测仪利用粮油含水量不同则其电阻率（导电性）不同的原理，通过测量电阻率间接推算水分含量；水分越高电阻率越低。电容式测介电系数，故选A。"}, {"id": 150, "type": "单选", "question": "( )粮油水分检测仪是通过测量粮油介电系数的大小，间接表示出粮油的水分含量。", "options": [{"key": "A", "text": "电容式"}, {"key": "B", "text": "电阻式"}, {"key": "C", "text": "电导式"}, {"key": "D", "text": "电离式"}], "answer": "A", "analysis": "电容式粮油水分检测仪通过测量粮油的介电系数（电容）大小来间接表示水分含量，水分变化会引起介电常数改变。电阻式测电阻率，故选A。"}, {"id": 151, "type": "单选", "question": "储粮害虫陷井诱捕器是根据储粮害虫的( )习性而设计的。", "options": [{"key": "A", "text": "钻孔"}, {"key": "B", "text": "假死"}, {"key": "C", "text": "上爬"}, {"key": "D", "text": "趋光"}], "answer": "A", "analysis": "储粮害虫陷阱诱捕器是利用害虫喜欢钻入缝隙、孔洞的钻孔（钻蛀）习性设计的，害虫落入陷阱后难以逃出，从而用于监测和诱捕。假死、上爬、趋光是其他诱捕原理，故选A。"}, {"id": 152, "type": "单选", "question": "储粮害虫的检查期限规定：粮温在15℃～25℃时，检查期限为( )内至少检查一次。", "options": [{"key": "A", "text": "每天"}, {"key": "B", "text": "每周"}, {"key": "C", "text": "每15天"}, {"key": "D", "text": "每20天"}], "answer": "C", "analysis": "储粮害虫检查期限随粮温升高而缩短：粮温>25℃每7天一次，15℃～25℃每15天至少检查一次，<15℃可延长至30天。题干温度区间对应每15天，故选C。"}, {"id": 153, "type": "单选", "question": "锯谷盗身体呈( )，黑褐色；头部呈梯形，后颊与复眼大小接近，外角钝圆；前胸背板纵长方形，背面有三条明显纵脊，中脊直，两侧脊稍成弧形，两侧缘各有6个锯齿状突起。", "options": [{"key": "A", "text": "细长扁平"}, {"key": "B", "text": "短椭圆形"}, {"key": "C", "text": "圆球形"}, {"key": "D", "text": "扁圆形"}], "answer": "A", "analysis": "锯谷盗成虫身体细长扁平、黑褐色，头部梯形，前胸背板有三条纵脊、两侧缘各有6个锯齿状突起，是其典型形态特征。短椭圆、圆球、扁圆均不符，故选A。"}, {"id": 154, "type": "单选", "question": "黑粉虫成虫身体呈长椭圆形，( )色，无光泽；触角11节，近念珠状，第3节长约等于1.2两节之和，末节宽大于长；前胸背板长宽接近相等，鞘翅末端略尖。", "options": [{"key": "A", "text": "深黑褐"}, {"key": "B", "text": "赤褐"}, {"key": "C", "text": "淡黄褐"}, {"key": "D", "text": "黄褐"}], "answer": "A", "analysis": "黑粉虫成虫体呈长椭圆形、深黑褐色、无光泽，触角近念珠状，前胸背板长宽近相等，是与黄粉虫（暗赤褐有光泽）区别的关键。赤褐、淡黄褐、黄褐均不对，故选A。"}, {"id": 155, "type": "单选", "question": "黄粉虫体形、体大小与黑粉虫相似，主要区别是:体( )；触角第3节短于1、2两节之和，末节长大于宽；前胸背板宽大于长，横长方形，鞘翅末端圆钝。", "options": [{"key": "A", "text": "暗赤褐色，有光泽"}, {"key": "B", "text": "灰白色，有光泽"}, {"key": "C", "text": "黄白色，有光泽"}, {"key": "D", "text": "深黑色，有光泽"}], "answer": "A", "analysis": "黄粉虫形态与黑粉虫相似，主要区别是体呈暗赤褐色、有光泽（黑粉虫深黑褐无光泽）；且触角第3节短于1、2节之和，前胸背板宽大于长。灰白、黄白、深黑均不符，故选A。"}, {"id": 156, "type": "单选", "question": "( ) 不是离心式通风机的主要组成部件。", "options": [{"key": "A", "text": "叶轮"}, {"key": "B", "text": "风网"}, {"key": "C", "text": "进风口"}, {"key": "D", "text": "出风口"}], "answer": "B", "analysis": "离心式通风机的主要组成部件包括叶轮、进风口、出风口、机壳、传动部件等；风网是通风系统的管网总称，并非风机本身的组成部件。故选B。"}, {"id": 157, "type": "单选", "question": "轴流式通风机的工作原理：当电动机带动叶轮旋转后，空气由( )吸入，经过叶片，获得能量，再经扩散筒，这时部分动能转为静压，空气流出，送到风网。", "options": [{"key": "A", "text": "机壳"}, {"key": "B", "text": "进风口"}, {"key": "C", "text": "圆形风筒"}, {"key": "D", "text": "电机"}], "answer": "B", "analysis": "轴流式通风机工作时，电动机带动叶轮旋转，空气由进风口被吸入，经叶片获得能量后由扩散筒流出送入风网，部分动能转为静压。机壳、圆形风筒、电机均非吸气口，故选B。"}, {"id": 158, "type": "单选", "question": "通风机的性能参数主要包括( )、效率及转速等。", "options": [{"key": "A", "text": "风量"}, {"key": "B", "text": "风压"}, {"key": "C", "text": "功率"}, {"key": "D", "text": "以上都是"}], "answer": "D", "analysis": "通风机的性能参数主要包括风量、风压、功率、效率和转速等，这些参数共同描述风机的通风能力和能耗。以上各项均属于性能参数，故选D。"}, {"id": 159, "type": "单选", "question": "压入式通风---通风机正压送风，适用于( )和粮堆中、上层发热降温通风。", "options": [{"key": "A", "text": "降温通风"}, {"key": "B", "text": "降水通风"}, {"key": "C", "text": "局部通风"}, {"key": "D", "text": "全仓通风"}], "answer": "B", "analysis": "压入式通风由通风机正压送风，气流由下而上或自内向外，适用于降水通风以及粮堆中、上层发热时的降温通风。降温、局部、全仓通风并非其典型适用表述，故选B。"}, {"id": 160, "type": "单选", "question": "单管通风系统是指小型通风机与单个扦插式通风管配套，插入粮堆内进行通风的系统，适用于( )或应急通风。", "options": [{"key": "A", "text": "降温通风"}, {"key": "B", "text": "降水通风"}, {"key": "C", "text": "局部通风"}, {"key": "D", "text": "全仓通风"}], "answer": "C", "analysis": "单管通风系统由小型通风机与单个扦插式通风管组成，灵活机动，适用于局部发热点的通风处理或应急通风，不适合全仓大面积通风。故选C。"}, {"id": 161, "type": "单选", "question": "填好通风记录卡是为了在日常管理中( )通风系统运行是否正常。", "options": [{"key": "A", "text": "确定"}, {"key": "B", "text": "测量"}, {"key": "C", "text": "衡量"}, {"key": "D", "text": "判断"}], "answer": "D", "analysis": "日常管理中填写通风记录卡，是为了据此判断通风系统运行是否正常、通风效果是否达到预期，便于分析和追溯。确定、测量、衡量均不如“判断”准确，故选D。"}, {"id": 162, "type": "单选", "question": "隔热材料之所以具有较小的导热系数和它的( )结构是分不开的。", "options": [{"key": "A", "text": "分子"}, {"key": "B", "text": "密实"}, {"key": "C", "text": "多孔性"}, {"key": "D", "text": "形态"}], "answer": "C", "analysis": "隔热材料导热系数小，与其多孔性结构密切相关：孔隙中封闭着静止空气，空气导热系数极低，从而大大降低整体导热能力。密实结构反而导热快，故选C。"}, {"id": 163, "type": "单选", "question": "稻壳的干容重为( )，其导热系数随含水量不同而变化。", "options": [{"key": "A", "text": "100千克/米3"}, {"key": "B", "text": "150千克/米3"}, {"key": "C", "text": "200千克/米3"}, {"key": "D", "text": "250千克/米3"}], "answer": "B", "analysis": "稻壳是一种常用隔热压盖材料，其干容重约为150千克/米³，且导热系数随含水量增大而升高。100、200、250均非该常用值，故选B。"}, {"id": 164, "type": "单选", "question": "储粮温度在夏季能否维持在一个比较低的状态，不仅与仓型有关，同时与仓房维护结构的( )性能也有直接的关系。", "options": [{"key": "A", "text": "密封"}, {"key": "B", "text": "防潮"}, {"key": "C", "text": "导热"}, {"key": "D", "text": "隔热保冷"}], "answer": "D", "analysis": "夏季储粮温度能否维持较低水平，既与仓型有关，也与仓房维护结构的隔热保冷性能直接相关，隔热越好则外界热量传入越少。密封、防潮、导热均不如隔热保冷贴切，故选D。"}, {"id": 165, "type": "单选", "question": "选配空调机时首先要确保具有足够的制冷能力，无需考虑( )。", "options": [{"key": "A", "text": "厂家"}, {"key": "B", "text": "品牌"}, {"key": "C", "text": "型号"}, {"key": "D", "text": "产地"}], "answer": "D", "analysis": "选配空调机时首要确保制冷能力满足仓房降温需求，厂家、品牌、型号可在满足能力前提下选择，而产地对性能无实质影响、无需特别考虑。故选D。"}, {"id": 166, "type": "单选", "question": "采用单管通风降低储粮局部温度时，下列( )操作是不正确的。", "options": [{"key": "A", "text": "高压离心风机"}, {"key": "B", "text": "中压离心风机"}, {"key": "C", "text": "低压离心风机"}, {"key": "D", "text": "轴流风机"}], "answer": "B", "analysis": "单管通风降低局部粮温通常采用高压离心风机或轴流风机以获得足够风压；中压离心风机风压和风量匹配不佳、不是单管通风的适用设备，属不正确操作。故选B。"}, {"id": 167, "type": "单选", "question": "按照机械通风降水对通风参数的要求，通风系统的空气途径比宜在( )。", "options": [{"key": "A", "text": "1.0:1 ～1.2:1"}, {"key": "B", "text": "1.0:1 ～1.5:1"}, {"key": "C", "text": "1.2:1 ～1.5:1"}, {"key": "D", "text": "1.2:1 ～1.8:1"}], "answer": "C", "analysis": "机械通风降水对通风参数有要求，空气途径比（通风途径长度与粮层厚度之比）宜控制在1.2:1～1.5:1，以保证降水均匀、避免通风死角。其他区间不符合降水通风推荐值，故选C。"}, {"id": 168, "type": "单选", "question": "降水通风时为了避免出现因为粮温变化而发生( )逆转现象，直接将粮温等于气温作为查定粮油平衡绝对湿度的条件。", "options": [{"key": "A", "text": "通风效果"}, {"key": "B", "text": "降水效果"}, {"key": "C", "text": "降温效果"}, {"key": "D", "text": "降湿效果"}], "answer": "A", "analysis": "降水通风时若粮温变化会引起通风效果逆转（如表层返潮），为简化计算、避免粮温影响，直接将粮温等于气温作为查定粮油平衡绝对湿度的条件。逆转针对整体通风效果，故选A。"}, {"id": 169, "type": "单选", "question": "堆码包装粮通风垛，主风道应朝着当地主流风向，隔一段距离也应打横向风道，增加通风道( )。", "options": [{"key": "A", "text": "风速"}, {"key": "B", "text": "阻力"}, {"key": "C", "text": "面积"}, {"key": "D", "text": "强度"}], "answer": "C", "analysis": "堆码包装粮通风垛时，主风道应朝向当地主流风向，并间隔打横向风道，目的是增加通风道的总面积，改善通风均匀性和效果。风速、阻力、强度均非横向风道的主要作用，故选C。"}, {"id": 170, "type": "单选", "question": "通过堆码通风垛降低储存粮油水分，必要时能够通过外接( )进行强制通风，从而增加降水速度。", "options": [{"key": "A", "text": "电源"}, {"key": "B", "text": "风道"}, {"key": "C", "text": "罩棚"}, {"key": "D", "text": "风机"}], "answer": "D", "analysis": "通过堆码通风垛利用自然通风降低粮油水分，必要时可外接风机进行强制通风，以加快空气流动、提高降水速度。电源、风道、罩棚均非直接强制通风设备，故选D。"}, {"id": 171, "type": "单选", "question": "气温下降气节应适时( )，采取自然对流通风，防止湿热扩散引起通风垛的上部粮食水分升高。", "options": [{"key": "A", "text": "机械通风"}, {"key": "B", "text": "环流熏蒸"}, {"key": "C", "text": "粮堆密闭"}, {"key": "D", "text": "揭开苫布"}], "answer": "D", "analysis": "气温下降季节应适时揭开苫布，利用自然对流通风排出粮堆湿热，防止湿热扩散使通风垛上部粮食吸湿、水分升高而霉变。机械通风、密闭、熏蒸均不适用此情形，故选D。"}, {"id": 172, "type": "单选", "question": "在密闭储粮中，通常是一个低氧、高氮、高二氧化碳气体的储藏空间 ，这几种气体是( )，应选用极性塑料薄膜。", "options": [{"key": "A", "text": "极性气体"}, {"key": "B", "text": "非极性气体"}, {"key": "C", "text": "惰性气体"}, {"key": "D", "text": "非惰性气体"}], "answer": "B", "analysis": "密闭储粮形成低氧、高氮、高二氧化碳的环境，氮气和二氧化碳属于非极性气体；为有效保持这种气体环境，应选用对这类气体透过率低的极性塑料薄膜。故选B。"}, {"id": 173, "type": "单选", "question": "储粮防护剂是一类残效期比较长的杀虫剂。从药剂进入害虫体内的途径来说，主要是( )。", "options": [{"key": "A", "text": "取食作用"}, {"key": "B", "text": "触杀作用"}, {"key": "C", "text": "胃毒作用"}, {"key": "D", "text": "触杀作用和胃毒作用"}], "answer": "D", "analysis": "储粮防护剂残效期长，药剂主要通过害虫接触虫体（触杀）和取食沾药粮粒（胃毒）两种途径进入虫体发挥作用。单纯取食或单纯触杀均不全面，故选D。"}, {"id": 174, "type": "单选", "question": "储粮防护剂使用时，对于已经入仓储藏的粮食，以( )的粮食计算用药量，可将液体保护剂稀释后喷洒在粮面上，然后搅动粮面进行拌和。", "options": [{"key": "A", "text": "粮面表层30-50cm厚"}, {"key": "B", "text": "粮面表层50-60cm厚"}, {"key": "C", "text": "粮堆底层30-50cm厚"}, {"key": "D", "text": "粮堆底层50-60cm厚"}], "answer": "A", "analysis": "对已入仓储藏的粮食使用防护剂，按粮面表层30–50 cm厚的粮食计算用药量，将液体保护剂稀释后喷洒于粮面并拌和，形成防护层。底层或50–60 cm均不符合，故选A。"}, {"id": 175, "type": "单选", "question": "储粮防护剂适用于( )。", "options": [{"key": "A", "text": "成品粮"}, {"key": "B", "text": "短期储存的安全水分粮"}, {"key": "C", "text": "害虫大量发生的储粮"}, {"key": "D", "text": "不具备熏蒸条件的基本无虫粮"}], "answer": "D", "analysis": "储粮防护剂适用于基本无虫粮且不具备熏蒸条件时的预防性保护，不能替代熏蒸处理大量发生的虫害。成品粮、短期安全水分粮、虫害大量发生粮均非其主要适用对象，故选D。"}, {"id": 176, "type": "单选", "question": "正压式空气呼吸器的气瓶背架上，一般固定有( )、高压软管、压力表、中压软管、供气阀、报警哨、气瓶固定带、背架及背带等。", "options": [{"key": "A", "text": "压力阀及接口"}, {"key": "B", "text": "减压阀及接口"}, {"key": "C", "text": "流量阀及接口"}, {"key": "D", "text": "气门阀及接口"}], "answer": "B", "analysis": "正压式空气呼吸器背架上一般固定有减压阀及接口、高压软管、压力表、中压软管、供气阀、报警哨、气瓶固定带和背架背带等，减压阀将高压气瓶气体减至可用压力。故选B。"}, {"id": 177, "type": "单选", "question": "熏蒸工作必须经( )批准，由技术熟练、有组织能力的技术人员负责指挥。", "options": [{"key": "A", "text": "单位法人"}, {"key": "B", "text": "单位负责人"}, {"key": "C", "text": "部门负责人"}, {"key": "D", "text": "班组负责人"}], "answer": "B", "analysis": "熏蒸属高风险作业，必须经单位负责人批准，并由技术熟练、有组织能力的技术人员负责指挥，落实安全防护措施。法人、部门、班组负责人均非题干所指的审批主体，故选B。"}, {"id": 178, "type": "单选", "question": "磷化铝常规熏蒸从施药开始到处理完残渣为止,要在粮仓四周( )左右设警戒线,立明显标志、阻止行人和畜、禽靠近。", "options": [{"key": "A", "text": "2米"}, {"key": "B", "text": "4米"}, {"key": "C", "text": "8米"}, {"key": "D", "text": "10米"}], "answer": "D", "analysis": "磷化铝常规熏蒸从施药到处理残渣全过程，须在粮仓四周约10米范围设警戒线、立明显标志，阻止行人及畜禽靠近，防止磷化氢中毒。2、4、8米均不足安全距离，故选D。"}, {"id": 179, "type": "单选", "question": "磷化氢浓度检测仪、检测管用于检测粮堆中( )。", "options": [{"key": "A", "text": "磷化氢气体浓度"}, {"key": "B", "text": "磷化氢气体和氧气浓度"}, {"key": "C", "text": "磷化氢气体和二氧化碳浓度"}, {"key": "D", "text": "磷化氢气体、氧气和二氧化碳浓度"}], "answer": "A", "analysis": "磷化氢浓度检测仪和检测管用于检测粮堆中磷化氢气体浓度，以判断熏蒸效果和评估安全；氧气、二氧化碳需用其他仪器测定。故选A。"}, {"id": 180, "type": "单选", "question": "房式仓磷化氢气体检测取样点设置，要求每廒间内设置气体取样点应不少于5个，即在( )。", "options": [{"key": "A", "text": "仓房的四角和中央各设置一个气体取样点"}, {"key": "B", "text": "粮堆的上、中、下、粮面、仓底各设置一个气体取样点"}, {"key": "C", "text": "仓房空间、通风道内以及粮堆上、中、下各设置一个气体取样点"}, {"key": "D", "text": "粮堆四面和表面各设置一个气体取样点"}], "answer": "A", "analysis": "同144题，房式仓磷化氢气体检测取样点每廒间不少于5个，即在仓房四角和中央各设一个，代表性地反映仓内气体分布。故选A。"}, {"id": 181, "type": "判断", "question": "职业道德对员工在职业活动中规范自己的言行及调节行为习惯起着重要作用。", "options": ["√", "×"], "answer": "√", "analysis": "职业道德是从业人员在职业活动中应遵守的行为规范，对员工规范自身言行、调节职业行为习惯起着重要的引导和约束作用，该表述正确。"}, {"id": 182, "type": "判断", "question": "道德的特点是通过社会舆论、传统习俗和自觉自愿行为来起作用的。", "options": ["√", "×"], "answer": "√", "analysis": "道德的特点正是通过社会舆论、传统习俗和内心信念（自觉自愿）来发挥作用，不依赖国家强制力，该表述正确。"}, {"id": 183, "type": "判断", "question": "粮食、油料的主要营养成分包括糖类、脂类、蛋白质、维生素、矿物质和水分等6大类。", "options": ["√", "×"], "answer": "√", "analysis": "粮食、油料的主要营养成分包括糖类、脂类、蛋白质、维生素、矿物质和水分六大类，这是营养学的基本分类，该表述正确。"}, {"id": 184, "type": "判断", "question": "脂肪是由1分子甘油与3分子脂肪酸脱水缩合而成的三酰甘油。", "options": ["√", "×"], "answer": "√", "analysis": "脂肪（甘油三酯）由1分子甘油与3分子脂肪酸经脱水缩合形成三酰甘油（甘油三酯），这是脂肪的基本化学结构，该表述正确。"}, {"id": 185, "type": "判断", "question": "维生素是构成人体组织的原料，可提供热量，尽管每人每日的需要量很微小，但却不可或缺。", "options": ["√", "×"], "answer": "×", "analysis": "维生素既不参与构成人体组织的主要原料，也不能提供热量，仅作为辅酶或调节物质参与代谢；说其“构成组织、提供热量”是错误的，故该题为×。"}, {"id": 186, "type": "判断", "question": "标准是为在一定范围内获得最佳秩序，对活动或其结果规定共同的和重复使用的规则、导则或特性文件。", "options": ["√", "×"], "answer": "√", "analysis": "标准的定义即为在一定的范围内获得最佳秩序，对活动或其结果规定共同和重复使用的规则、导则或特性文件，该表述正确。"}, {"id": 187, "type": "判断", "question": "强制性国家标准的代号为“GB/T”，推荐性国家标准的代号为“GB”。", "options": ["√", "×"], "answer": "×", "analysis": "我国标准代号中强制性国家标准为“GB”，推荐性国家标准为“GB/T”；题干将二者颠倒，故该题为×。"}, {"id": 188, "type": "判断", "question": "劳动者应当履行的义务包括：完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。", "options": ["√", "×"], "answer": "√", "analysis": "《劳动法》规定劳动者义务包括完成劳动任务、提高职业技能、执行劳动安全卫生规程、遵守劳动纪律和职业道德，该表述正确。"}, {"id": 189, "type": "判断", "question": "出糙率是指净稻谷脱壳后的糙米（其中不完善粒折半计算）占试样质量的百分率。", "options": ["√", "×"], "answer": "√", "analysis": "出糙率是指净稻谷脱壳后的糙米（其中不完善粒按规定折半计算）占试样质量的百分率，是稻谷定等指标，该表述正确。"}, {"id": 190, "type": "判断", "question": "赤霉病粒比例高的小麦，容重小。", "options": ["√", "×"], "answer": "√", "analysis": "赤霉病粒多为瘪瘦、皱缩的病粒，比例高的小麦籽粒不饱满、容重降低，该表述正确。"}, {"id": 191, "type": "判断", "question": "如果玉米中不完善粒比例较小，则容重较小。", "options": ["√", "×"], "answer": "×", "analysis": "玉米不完善粒比例较小说明籽粒完整饱满，容重应较大而非较小；题干因果颠倒，故该题为×。"}, {"id": 192, "type": "判断", "question": "籽粒的成熟、饱满、完整的稻谷出糙率较高。", "options": ["√", "×"], "answer": "√", "analysis": "籽粒成熟、饱满、完整的稻谷出糙率高（完整粒脱壳损失小），未熟或受损粒出糙率低，该表述正确。"}, {"id": 193, "type": "判断", "question": "启动计算机粮情检测系统时，应按顺序启动工作电源、计算机、检测主机、系统软件。", "options": ["√", "×"], "answer": "√", "analysis": "计算机粮情检测系统开机应按顺序启动工作电源、计算机、检测主机、系统软件，逐级上电保证系统正常初始化，该表述正确。"}, {"id": 194, "type": "判断", "question": "校正粮情测控系统标准温度计的最小分度值为0.1℃。", "options": ["√", "×"], "answer": "√", "analysis": "校正粮情测控系统所用标准温度计的最小分度值一般为0.1℃，以满足粮温测控的精度要求，该表述正确（具体以检定规程为准）。"}, {"id": 195, "type": "判断", "question": "在秋冬季节转换时期，有时粮堆表层发生结露，原因是粮温高于气温，粮堆内部热空气上升，遇到冷的粮面，便发生结露。", "options": ["√", "×"], "answer": "√", "analysis": "秋冬季节气温下降快于粮温，粮温高于气温时粮堆内部湿热空气上升，遇冷的粮面达到露点便在表层结露，该表述正确。"}, {"id": 196, "type": "判断", "question": "磷化氢气体检测仪和报警仪的传感器通常采用定电压电解法原理。", "options": ["√", "×"], "answer": "√", "analysis": "磷化氢气体检测仪和报警仪的传感器通常采用定电压电解法原理，气体在电解池中发生电化学反应产生与浓度成正比的电流信号，该表述正确。"}, {"id": 197, "type": "判断", "question": "磷化氢气体报警仪的测量范围为：0–20ml/m3。", "options": ["√", "×"], "answer": "√", "analysis": "磷化氢报警仪用于人员安全监测，测量范围一般为0–20 ml/m³（约0–20 ppm），覆盖人员暴露安全限值，该表述正确。"}, {"id": 198, "type": "判断", "question": "取样管、取样阀、检测箱、抽气泵、检测仪、报警仪、检测管等组成了磷化氢浓度检测装置。", "options": ["√", "×"], "answer": "√", "analysis": "磷化氢浓度检测装置由取样管、取样阀、检测箱、抽气泵、检测仪、报警仪、检测管等组成，用于采集并测定仓内磷化氢浓度，该表述正确。"}, {"id": 199, "type": "判断", "question": "烟草甲身体呈椭圆形，暗赤褐色，有光泽；触角11节锯齿状；前胸背板半圆形，后缘与鞘翅基部等宽；鞘翅表面光滑，无纵刻点纹。", "options": ["√", "×"], "answer": "√", "analysis": "烟草甲成虫椭圆形、暗赤褐色有光泽，触角11节锯齿状，前胸背板半圆形、后缘与鞘翅基部等宽，鞘翅表面光滑无纵刻点纹，该形态描述正确。"}, {"id": 200, "type": "判断", "question": "机械通风操作开始之前应填写记录卡的内容是仓型、尺寸、粮食种类。", "options": ["√", "×"], "answer": "√", "analysis": "机械通风操作前填写记录卡，内容应包括仓型、尺寸、粮食种类等基础信息，以便对照分析和判断通风效果，该表述正确。"}, {"id": 201, "type": "单选", "question": "职业的属性包括社会性、规范性、功利性、群体性、技术性以及（ ）等。", "options": [{"key": "A", "text": "个体性"}, {"key": "B", "text": "公益性"}, {"key": "C", "text": "艺术性"}, {"key": "D", "text": "时代性"}], "answer": "D", "analysis": "职业的属性通常包括社会性、规范性、功利性、群体性、技术性和时代性等。时代性指职业随社会发展和科技进步不断演变，是职业属性的重要组成部分。因此选D。"}, {"id": 202, "type": "单选", "question": "职业能力分为核心技能、行业通用技能和职业（ ）三个部分。", "options": [{"key": "A", "text": "职业一般技能"}, {"key": "B", "text": "职业特定技能"}, {"key": "C", "text": "职业通用技能"}, {"key": "D", "text": "职业创新技能"}], "answer": "B", "analysis": "国家职业标准体系将职业技能分为核心技能、行业通用技能和职业特定技能三个层次。职业特定技能是指技术技能型人才从事特定职业、岗位和工种必须或应当具备的技能。因此选B。"}, {"id": 203, "type": "单选", "question": "粮食仓储业职业道德的核心是（ ）。", "options": [{"key": "A", "text": "遵纪守法"}, {"key": "B", "text": "听老板的话"}, {"key": "C", "text": "为人民服务"}, {"key": "D", "text": "为老板服务"}], "answer": "C", "analysis": "为人民服务是社会主义职业道德的集中体现，也是粮食仓储业职业道德的核心，最终落脚于确保储备粮油安全、保障国家粮食安全。选项A遵纪守法是职业守则内容而非核心。因此选C。"}, {"id": 204, "type": "单选", "question": "“道德” 是规则、规范、（ ）以及人们对善恶的评价等。", "options": [{"key": "A", "text": "习惯"}, {"key": "B", "text": "言谈举止"}, {"key": "C", "text": "事物认知"}, {"key": "D", "text": "行为品质"}], "answer": "D", "analysis": "道德是一定社会调整人与人之间以及个人与社会之间关系的行为规范总和，包含规则、规范、行为品质以及对善恶的评价等内容。因此选D。"}, {"id": 205, "type": "单选", "question": "职业道德是人们在从事职业的过程中形成的一种（ ）的约束机制。", "options": [{"key": "A", "text": "外在的、强制性"}, {"key": "B", "text": "内在的、非强制性"}, {"key": "C", "text": "内在的、强制性"}, {"key": "D", "text": "外在的、非强制性"}], "answer": "B", "analysis": "职业道德依靠社会舆论、传统习惯和内心信念起作用，不同于法律的外在强制性，是一种内在的、非强制性的自我约束机制。因此选B。"}, {"id": 206, "type": "单选", "question": "下列角色不属于职业的是（ ）。", "options": [{"key": "A", "text": "粮油仓储管理员"}, {"key": "B", "text": "防疫志愿者"}, {"key": "C", "text": "月嫂"}, {"key": "D", "text": "中国女排运动员"}], "answer": "B", "analysis": "职业是人们从事相对稳定的、有报酬的、专门类别的社会劳动；志愿者从事无偿服务、不取报酬，不具备职业的有报酬特征，故不属于职业。因此选B。"}, {"id": 207, "type": "单选", "question": "（ ）是人们在从事职业的过程中形成的一种内在的、非强制性的约束机制。", "options": [{"key": "A", "text": "道德修养"}, {"key": "B", "text": "职业道德"}, {"key": "C", "text": "文化素养"}, {"key": "D", "text": "自律性"}], "answer": "B", "analysis": "职业道德是人们在从事职业过程中形成的一种内在的、非强制性的约束机制，靠内心信念和社会舆论维持。因此选B。"}, {"id": 208, "type": "单选", "question": "职业是人们从事相对稳定的、（ ）的社会劳动。", "options": [{"key": "A", "text": "有报酬的、专门类别"}, {"key": "B", "text": "普遍性"}, {"key": "C", "text": "实现自我价值"}, {"key": "D", "text": "特殊性"}], "answer": "A", "analysis": "职业的本质特征包括相对稳定、有报酬、专门类别的社会劳动，这是职业与偶尔性、义务性活动的区别。因此选A。"}, {"id": 209, "type": "单选", "question": "道德是调整人与人以及个人与社会之间关系的（ ）的总和。", "options": [{"key": "A", "text": "行为规范"}, {"key": "B", "text": "经济利益"}, {"key": "C", "text": "生产关系"}, {"key": "D", "text": "社会活动"}], "answer": "A", "analysis": "道德是调整人与人以及个人与社会之间关系的行为规范的总和，行为规则和规范是道德的核心内容。因此选A。"}, {"id": 210, "type": "单选", "question": "（ ）是社会主义职业道德的集中体现。", "options": [{"key": "A", "text": "遵纪守法"}, {"key": "B", "text": "以经济建设为中心"}, {"key": "C", "text": "发展"}, {"key": "D", "text": "为人民服务"}], "answer": "D", "analysis": "为人民服务是社会主义职业道德的集中体现和核心，集体主义在职业道德中的具体落实就是为人民服务。因此选D。"}, {"id": 211, "type": "单选", "question": "对粮油仓储工作者的职业道德要求可总结为：“（ ）”", "options": [{"key": "A", "text": "遵纪守法，认真工作"}, {"key": "B", "text": "爱粮如命，爱库如家"}, {"key": "C", "text": "执行标准，严于律己"}, {"key": "D", "text": "保守秘密，忠于职守"}], "answer": "B", "analysis": "粮食仓储行业把对从业人员的职业道德要求概括为\"爱粮如命，爱库如家\"，强调珍惜粮食、爱护仓房设施。因此选B。"}, {"id": 212, "type": "单选", "question": "（ ）是指技术技能型人才从事特定的职业、岗位和工种必须或应当具备的技能。", "options": [{"key": "A", "text": "核心技能"}, {"key": "B", "text": "行业通用技能"}, {"key": "C", "text": "职业特定技能"}, {"key": "D", "text": "高级技能"}], "answer": "C", "analysis": "职业特定技能是指技术技能型人才从事特定职业、岗位和工种必须或应当具备的技能，区别于通用能力和核心能力。因此选C。"}, {"id": 213, "type": "判断", "question": "志愿者也是一种职业。", "options": ["√", "×"], "answer": "×", "analysis": "志愿者提供无偿服务，不具备职业\"相对稳定、有报酬、专门类别\"的特征，因此志愿者不是一种职业。该陈述为假。"}, {"id": 214, "type": "判断", "question": "“道德” 是规则、规范、行为品质以及人们对善恶的评价等。", "options": ["√", "×"], "answer": "√", "analysis": "道德定义为规则、规范、行为品质以及人们对善恶的评价等的总和，题干表述与定义一致。该陈述为真。"}, {"id": 215, "type": "判断", "question": "职业道德是人们在履行本职工作中所应遵守的行为规范和准则的总和。", "options": ["√", "×"], "answer": "√", "analysis": "职业道德是人们在履行本职工作中所应遵守的行为规范和准则的总和，这是职业道德的标准定义。该陈述为真。"}, {"id": 216, "type": "单选", "question": "爱岗敬业，忠于职守就是要（ ）。", "options": [{"key": "A", "text": "热爱从事的职业，履行岗位职责"}, {"key": "B", "text": "团结协作，廉洁公正"}, {"key": "C", "text": "执行规范，文明生产"}, {"key": "D", "text": "遵纪守法，保守秘密"}], "answer": "A", "analysis": "爱岗敬业、忠于职守的直接涵义就是热爱所从事的职业、认真履行岗位职责；其他选项属于其他职业守则条目。因此选A。"}, {"id": 217, "type": "单选", "question": "粮油仓储业从业人员的职业守则四项要求之一是（ ）。", "options": [{"key": "A", "text": "爱护设备，减少污染"}, {"key": "B", "text": "执行规范，文明生产"}, {"key": "C", "text": "文明生产，确保安全"}, {"key": "D", "text": "不违章操作"}], "answer": "B", "analysis": "粮油仓储业职业守则四项要求之一为\"执行规范，文明生产\"，强调按操作规程和科学方法组织生产，保证质量与安全。因此选B。"}, {"id": 218, "type": "单选", "question": "粮油仓储业从业人员的职业守则四项要求之一是（ ）。", "options": [{"key": "A", "text": "遵纪守法，保守秘密"}, {"key": "B", "text": "爱护设备，减少污染"}, {"key": "C", "text": "文明生产，确保安全"}, {"key": "D", "text": "不违章操作"}], "answer": "A", "analysis": "\"遵纪守法，保守秘密\"是职业守则四项要求之一，涉及遵守法规纪律及对国家储备机密的保密义务。因此选A。"}, {"id": 219, "type": "单选", "question": "粮油仓储业从业人员的职业守则四项要求之一是（ ）。", "options": [{"key": "A", "text": "爱岗敬业，忠于职守"}, {"key": "B", "text": "爱护设备，减少污染"}, {"key": "C", "text": "文明生产，确保安全"}, {"key": "D", "text": "不违章操作"}], "answer": "A", "analysis": "\"爱岗敬业，忠于职守\"是职业守则四项要求之首，要求从业人员热爱岗位、尽职尽责。因此选A。"}, {"id": 220, "type": "单选", "question": "粮油仓储业从业人员的职业守则四项要求之一是（ ）。", "options": [{"key": "A", "text": "文明生产，确保安全"}, {"key": "B", "text": "爱护设备，减少污染"}, {"key": "C", "text": "团结协作，廉洁公正"}, {"key": "D", "text": "不违章操作"}], "answer": "C", "analysis": "\"团结协作，廉洁公正\"是职业守则四项要求之一，强调同事间协作配合与廉洁公正的作风。因此选C。"}, {"id": 221, "type": "单选", "question": "粮食仓储业职业道德根本任务是提高从业人员的（ ）素质，使其养成奉献社会、爱岗敬业、纪律严明、开拓创新的道德情操，忠实履行自己岗位职责，确保储备粮油安全。", "options": [{"key": "A", "text": "文明"}, {"key": "B", "text": "文化"}, {"key": "C", "text": "心理"}, {"key": "D", "text": "职业道德"}], "answer": "D", "analysis": "粮食仓储业职业道德的根本任务就是提高从业人员的职业道德素质，使其养成奉献社会、爱岗敬业等情操，忠实履职确保安全。因此选D。"}, {"id": 222, "type": "单选", "question": "执行规范，文明生产是指严格按照岗位规范、（ ）要求，爱护设备，减少污染，文明生产，确保安全。", "options": [{"key": "A", "text": "职业道德"}, {"key": "B", "text": "劳动法"}, {"key": "C", "text": "劳动纪律"}, {"key": "D", "text": "操作规程"}], "answer": "D", "analysis": "执行规范、文明生产要求严格按照岗位规范、操作规程作业，操作规程是直接规范操作行为的技术依据，由此才能爱护设备、减少污染、确保安全。因此选D。"}, {"id": 223, "type": "单选", "question": "下列内容中，不属于涉及国家秘密的内容的是（ ）。", "options": [{"key": "A", "text": "储存品种"}, {"key": "B", "text": "存放布局"}, {"key": "C", "text": "吞吐时机"}, {"key": "D", "text": "库区地址"}], "answer": "D", "analysis": "储存品种、存放布局、吞吐时机都属于涉及国家粮食储备安全的机密内容；库区地址一般属可公开信息，不属于国家秘密。因此选D。"}, {"id": 224, "type": "单选", "question": "（ ）是指要求从业人员应明确自己的岗位职责，明确在社会分工中自己职业所担负的社会责任和义务。", "options": [{"key": "A", "text": "遵纪守法"}, {"key": "B", "text": "保守秘密"}, {"key": "C", "text": "忠于职守"}, {"key": "D", "text": "文明生产"}], "answer": "C", "analysis": "忠于职守是指从业人员明确自己岗位职责，明确在社会分工中本职业所担负的社会责任和义务，尽职尽责。因此选C。"}, {"id": 225, "type": "单选", "question": "（ ）是指每个从业人员都要遵守职业纪律，遵守国家制定的法律、法规，并对涉及国家机密的相关内容负有保密义务。", "options": [{"key": "A", "text": "文明生产，确保安全"}, {"key": "B", "text": "爱护设备，减少污染"}, {"key": "C", "text": "团结协作，廉洁公正"}, {"key": "D", "text": "遵纪守法，保守秘密"}], "answer": "D", "analysis": "遵纪守法、保守秘密是指遵守职业纪律和国家法律法规，并对涉及国家机密的内容负有保密义务，题干即其释义。因此选D。"}, {"id": 226, "type": "单选", "question": "（ ）是指按照法律、法规、规章等要求进行工作。", "options": [{"key": "A", "text": "团结协作"}, {"key": "B", "text": "执行规范"}, {"key": "C", "text": "文明生产"}, {"key": "D", "text": "爱岗敬业"}], "answer": "B", "analysis": "执行规范就是按照法律、法规、规章等要求进行工作，照章办事。因此选B。"}, {"id": 227, "type": "单选", "question": "（ ）是指生产的科学性，要创造一个保证质量的内部条件和外部条件。", "options": [{"key": "A", "text": "团结协作"}, {"key": "B", "text": "执行规范"}, {"key": "C", "text": "文明生产"}, {"key": "D", "text": "爱岗敬业"}], "answer": "C", "analysis": "文明生产是指生产的科学性，要创造一个保证产品质量的内部条件和外部条件，强调安全、清洁、有序的生产环境。因此选C。"}, {"id": 228, "type": "判断", "question": "粮食仓储业职业道德的核心是文明生产。", "options": ["√", "×"], "answer": "×", "analysis": "粮食仓储业职业道德的核心是为人民服务（确保储备粮油安全），文明生产只是职业守则四项要求之一，并非核心。该陈述为假。"}, {"id": 229, "type": "判断", "question": "粮油仓储从业人员应严格遵守保密制度，为维护国家安全、国家利益守口如瓶。", "options": ["√", "×"], "answer": "√", "analysis": "国家储备粮的品种、布局、吞吐时机均属敏感信息，粮油仓储从业人员必须严格遵守保密制度、维护国家安全利益、守口如瓶。该陈述为真。"}, {"id": 230, "type": "判断", "question": "粮油仓储从业人员必须切实做到“爱岗敬业、忠于职守”，才能在平凡的工作岗位上做出不平凡业绩。", "options": ["√", "×"], "answer": "√", "analysis": "爱岗敬业、忠于职守是粮油仓储从业人员的基本职业要求，是立足平凡岗位做出成绩的前提。该陈述为真。"}, {"id": 231, "type": "单选", "question": "在一定的温度和相对湿度条件下，粮食吸附和解吸达到动态平衡时的含水量，叫做（ ）。", "options": [{"key": "A", "text": "安全水分"}, {"key": "B", "text": "危险水分"}, {"key": "C", "text": "临界水分"}, {"key": "D", "text": "平衡水分"}], "answer": "D", "analysis": "平衡水分是指在一定的温度和相对湿度条件下，粮食吸附与解吸达到动态平衡时的含水量，是通风与密闭时机判定的依据。因此选D。"}, {"id": 232, "type": "单选", "question": "当粮食水分增高到（ ）时，粮油籽粒呼吸强度会急剧加强。", "options": [{"key": "A", "text": "安全水分值"}, {"key": "B", "text": "危险水分值"}, {"key": "C", "text": "临界水分值"}, {"key": "D", "text": "平衡水分值"}], "answer": "C", "analysis": "临界水分是粮食出现明显呼吸作用（自由水开始参与代谢）的转折点，当水分增高到临界水分值时呼吸强度会急剧加强。因此选C。"}, {"id": 233, "type": "单选", "question": "在一定范围内，粮食呼吸强度随温度的增加而（ ）。", "options": [{"key": "A", "text": "减小"}, {"key": "B", "text": "不变"}, {"key": "C", "text": "增大"}, {"key": "D", "text": "不确定"}], "answer": "C", "analysis": "在一定范围内，温度越高粮粒酶活性越强，呼吸作用越旺盛，呼吸强度随温度增加而增大，这是控温储藏的生理学依据。因此选C。"}, {"id": 234, "type": "单选", "question": "储粮发生霉变，最主要的原因是（ ）高所导致。", "options": [{"key": "A", "text": "粮食温度"}, {"key": "B", "text": "大气温度"}, {"key": "C", "text": "气体成分"}, {"key": "D", "text": "储粮水分"}], "answer": "D", "analysis": "储粮霉变主要由微生物（尤其是霉菌）引起，而霉菌生长繁殖的关键是自由水，故储粮水分高是霉变最主要的原因。因此选D。"}, {"id": 235, "type": "单选", "question": "四大粮种中，散落性最差的粮种是（ ）。", "options": [{"key": "A", "text": "稻谷"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "大豆"}], "answer": "A", "analysis": "稻谷粒形细长、带芒、表面粗糙且杂质相对较多，静止角大、散落性最差；玉米、小麦散落性较好。因此选A。"}, {"id": 236, "type": "单选", "question": "高温高湿环境对于粮食安全储藏（ ）。", "options": [{"key": "A", "text": "有利"}, {"key": "B", "text": "不利"}, {"key": "C", "text": "不影响"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "高温高湿会显著增强粮食呼吸作用、促进霉菌生长和害虫繁殖，对安全储藏明显不利，应低温干燥储藏。因此选B。"}, {"id": 237, "type": "单选", "question": "四大粮种中，不耐高温容易陈化赤变的是（ ）。", "options": [{"key": "A", "text": "玉米"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "大豆"}, {"key": "D", "text": "稻谷"}], "answer": "C", "analysis": "大豆含油量高、蛋白质丰富，不耐高温，在储藏中易因高温发生酸败、变色（赤变）和陈化。因此选C。"}, {"id": 238, "type": "单选", "question": "四大粮种中，抗温变能力强的是（ ）。", "options": [{"key": "A", "text": "玉米"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "大豆"}, {"key": "D", "text": "稻谷"}], "answer": "B", "analysis": "小麦耐储藏性较好、抗温变能力强，相对不易因温度波动而劣变；稻谷、大豆、玉米对温变更敏感。因此选B。"}, {"id": 239, "type": "单选", "question": "营养性糖类包括可溶性糖类和（ ）。", "options": [{"key": "A", "text": "半纤维素"}, {"key": "B", "text": "纤维素"}, {"key": "C", "text": "果胶"}, {"key": "D", "text": "淀粉"}], "answer": "D", "analysis": "营养性糖类包括可溶性糖类（葡萄糖、蔗糖等）和淀粉，淀粉是粮食主要的储能多糖且可被人体消化利用；纤维素等属结构性非营养多糖。因此选D。"}, {"id": 240, "type": "单选", "question": "一般情况下，随着玉米储藏时间的延长，玉米的容重会（ ）。", "options": [{"key": "A", "text": "升高"}, {"key": "B", "text": "降低"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "玉米在储藏过程中因呼吸消耗、后熟变化、籽粒破碎及水分重新分布等，一般容重会随储藏时间延长而降低。因此选B。"}, {"id": 241, "type": "单选", "question": "粮堆对粮仓产生侧压力的决定性因素是（ ）。", "options": [{"key": "A", "text": "自动分级"}, {"key": "B", "text": "孔隙度"}, {"key": "C", "text": "散落性"}, {"key": "D", "text": "水分含量"}], "answer": "C", "analysis": "粮堆对仓壁产生侧压力的大小由散落性（静止角）决定，散落性越好、静止角越小，对仓壁侧压力越大。因此选C。"}, {"id": 242, "type": "单选", "question": "仓内及粮堆孔隙中空气（ ）对粮食水分影响很大。", "options": [{"key": "A", "text": "温度"}, {"key": "B", "text": "速度"}, {"key": "C", "text": "成分"}, {"key": "D", "text": "湿度"}], "answer": "D", "analysis": "仓内及粮堆孔隙中空气的湿度决定粮食吸湿或解湿的方向，直接影响粮堆的平衡水分，故湿度对粮食水分影响很大。因此选D。"}, {"id": 243, "type": "单选", "question": "储藏过程中，粮油籽粒中淀粉的主要方面变化是（ ）。", "options": [{"key": "A", "text": "量变"}, {"key": "B", "text": "质变"}, {"key": "C", "text": "含量减少"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "储藏过程中淀粉总量变化不大，主要发生的是品质方面的质变（如糊化特性改变、老化等），而非单纯的量的减少。因此选B。"}, {"id": 244, "type": "单选", "question": "在相同等级、水分条件下，稻谷的孔隙度要比小麦的（ ）。", "options": [{"key": "A", "text": "小"}, {"key": "B", "text": "大"}, {"key": "C", "text": "相同"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "稻谷粒形不一致且带壳，堆内孔隙相对较多，在相同等级和水分条件下其孔隙度比小麦大。因此选B。"}, {"id": 245, "type": "单选", "question": "粮食的散落性良好，往往代表粮食的储藏稳定性（ ）。", "options": [{"key": "A", "text": "较好"}, {"key": "B", "text": "较差"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不确定"}], "answer": "A", "analysis": "散落性良好的粮食通常籽粒饱满、干燥、杂质少，这样的粮食储藏稳定性较好；散落性差往往伴随高水分、高杂质。因此选A。"}, {"id": 246, "type": "单选", "question": "高水分粮发热的最主要原因是（ ）积累热量。", "options": [{"key": "A", "text": "粮食呼吸"}, {"key": "B", "text": "害虫呼吸"}, {"key": "C", "text": "微生物呼吸"}, {"key": "D", "text": "气体成分变化"}], "answer": "C", "analysis": "高水分粮发热的主要原因是微生物（霉菌等）大量繁殖呼吸放热，其产热量远大于粮粒和害虫呼吸，是主要热源。因此选C。"}, {"id": 247, "type": "单选", "question": "下列微生物中对储粮危害最大的是（ ）。", "options": [{"key": "A", "text": "酵母菌"}, {"key": "B", "text": "霉菌"}, {"key": "C", "text": "细菌"}, {"key": "D", "text": "放线菌"}], "answer": "B", "analysis": "霉菌在较高水分和温度下大量生长，引起粮食发热、霉变并产生毒素，是对储粮危害最大的微生物类群。因此选B。"}, {"id": 248, "type": "单选", "question": "饱和湿度是指在一定温度下，每立方米空气中所能容纳的（ ）水气量。", "options": [{"key": "A", "text": "最小"}, {"key": "B", "text": "最大"}, {"key": "C", "text": "一般"}, {"key": "D", "text": "中等"}], "answer": "B", "analysis": "饱和湿度是指在一定温度下，单位体积空气中所能容纳的最大水汽量，超过此值即凝结。因此选B。"}, {"id": 249, "type": "单选", "question": "关于粮食的吸湿性，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "平衡水分规律是适时通风和密闭的依据"}, {"key": "B", "text": "判断降水通风时机及粮食水分变化趋势"}, {"key": "C", "text": "由于吸附滞后作用，避免干、湿粮混储"}, {"key": "D", "text": "平衡水分就是临界水分"}], "answer": "D", "analysis": "平衡水分是吸附—解吸达到平衡时的含水量，而临界水分是呼吸急剧增强的转折点，二者概念不同；A、B、C均为吸湿性的正确应用。因此选D。"}, {"id": 250, "type": "单选", "question": "粮食从高点自由下落至平面流散形成圆锥体的性质称为（ ）。", "options": [{"key": "A", "text": "散落性"}, {"key": "B", "text": "自动分级"}, {"key": "C", "text": "孔隙度"}, {"key": "D", "text": "湿热扩散"}], "answer": "A", "analysis": "散落性是指粮食从高点自由下落至平面后自然流散形成圆锥体的性质，其程度用静止角衡量。因此选A。"}, {"id": 251, "type": "单选", "question": "高温、高湿的储藏环境可（ ）粮食的陈化。", "options": [{"key": "A", "text": "延缓"}, {"key": "B", "text": "减轻"}, {"key": "C", "text": "加速"}, {"key": "D", "text": "防止"}], "answer": "C", "analysis": "高温、高湿会加速粮食的陈化劣变，储藏中应采取低温、干燥措施来延缓陈化。因此选C。"}, {"id": 252, "type": "单选", "question": "自然流散所形成的粮堆，重型杂质主要集中在（ ）位置。", "options": [{"key": "A", "text": "粮堆顶部"}, {"key": "B", "text": "底部四周"}, {"key": "C", "text": "底部中心"}, {"key": "D", "text": "粮堆侧面"}], "answer": "C", "analysis": "粮食自然流散（自动分级）时，颗粒大、比重大的重型杂质随主流落于粮堆底部中心，轻杂和破碎粒则分布于四周和表层。因此选C。"}, {"id": 253, "type": "单选", "question": "粮堆是热的（ ）。", "options": [{"key": "A", "text": "导体"}, {"key": "B", "text": "良好导体"}, {"key": "C", "text": "不良导体"}, {"key": "D", "text": "传递体"}], "answer": "C", "analysis": "粮堆含有大量孔隙和静止空气，导热系数小，是热的不良导体，热量不易散失易在粮堆内部积聚。因此选C。"}, {"id": 254, "type": "单选", "question": "粮食有很强的吸湿性不是因为（ ）。", "options": [{"key": "A", "text": "粮粒是多孔毛细管胶体物质"}, {"key": "B", "text": "粮食有很多亲水性基团"}, {"key": "C", "text": "具有很大的吸附内表面"}, {"key": "D", "text": "脂肪的存在"}], "answer": "D", "analysis": "粮食强吸湿性源于多孔毛细管胶体结构、丰富亲水基团和巨大的吸附内表面；脂肪是疏水的，不是吸湿原因。因此选D。"}, {"id": 255, "type": "单选", "question": "通过粮粒与粮粒直接接触的热能传递方式称为（ ）。", "options": [{"key": "A", "text": "辐射"}, {"key": "B", "text": "传导"}, {"key": "C", "text": "对流"}, {"key": "D", "text": "导热"}], "answer": "B", "analysis": "传导是指通过粮粒与粮粒直接接触传递热能的方式；对流由流体（气体）运动带动，辐射是非接触以电磁波传递。因此选B。"}, {"id": 256, "type": "单选", "question": "随着粮食含水量降低，粮食的导热性（ ）。", "options": [{"key": "A", "text": "增强"}, {"key": "B", "text": "降低"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "难以确定"}], "answer": "B", "analysis": "粮食含水量越低，堆内孔隙中空气比例越大，而空气导热性差，故整体导热性随含水量降低而降低，粮堆更趋于不良导体。因此选B。"}, {"id": 257, "type": "单选", "question": "生霉的粮食的处理方式应该是（ ）。", "options": [{"key": "A", "text": "做口粮"}, {"key": "B", "text": "做饲料"}, {"key": "C", "text": "工业用途"}, {"key": "D", "text": "掩埋处理"}], "answer": "C", "analysis": "生霉粮食往往带霉菌毒素，不能做口粮也不能做饲料，一般按相关规定作工业用途（如制酒精、工业发酵等）处理。因此选C。"}, {"id": 258, "type": "单选", "question": "储粮发生霉变，最主要的原因是（ ）增加导致。", "options": [{"key": "A", "text": "粮食温度"}, {"key": "B", "text": "大气温度"}, {"key": "C", "text": "气体成分"}, {"key": "D", "text": "储粮水分"}], "answer": "D", "analysis": "储粮霉变的根本诱因是储粮水分（自由水）增加，为霉菌繁殖提供了条件，与第234题原理一致。因此选D。"}, {"id": 259, "type": "单选", "question": "粮食的静止角越小，散落性越（ ）。", "options": [{"key": "A", "text": "差"}, {"key": "B", "text": "好"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "静止角与散落性呈负相关：静止角越小说明粮粒越易流散，散落性越好。因此选B。"}, {"id": 260, "type": "单选", "question": "呼吸作用对储粮的不利作用是（ ）。", "options": [{"key": "A", "text": "呼吸作用能促进小麦等粮食品种后熟作用；"}, {"key": "B", "text": "储粮呼吸会造成粮堆内的CO 积累，进行自然缺氧储藏；"}, {"key": "C", "text": "粮食的呼吸作用是气调储藏的理论基础。"}, {"key": "D", "text": "无氧呼吸使密封储藏的高水分粮食产生酒味"}], "answer": "D", "analysis": "无氧呼吸氧化不彻底、产生酒精，会使密封储藏的高水分粮食出现酒味和品质劣变，这是对储粮的不利作用；其余各项属于可利用的有利方面。因此选D。"}, {"id": 261, "type": "单选", "question": "根据粮油商品的性质、用途，通常将其分为粮食、油料与油脂、粮油副产品和（ ）4大类。", "options": [{"key": "A", "text": "谷类"}, {"key": "B", "text": "豆类"}, {"key": "C", "text": "粮油食品"}, {"key": "D", "text": "薯类"}], "answer": "C", "analysis": "按性质和用途，粮油商品通常分为粮食、油料与油脂、粮油副产品和粮油食品四大类，题干缺第四类。因此选C。"}, {"id": 262, "type": "单选", "question": "根据粮油商品的性质、用途，通常将其分为（ ）、油料与油脂、粮油副产品和粮油食品4大类。", "options": [{"key": "A", "text": "谷类"}, {"key": "B", "text": "豆类"}, {"key": "C", "text": "粮食"}, {"key": "D", "text": "薯类"}], "answer": "C", "analysis": "粮油商品四大类第一大类为粮食（含谷类、豆类、薯类等），其余三类为油料与油脂、副产品、粮油食品。因此选C。"}, {"id": 263, "type": "单选", "question": "根据粮油商品的性质、用途，通常将其分为粮食、（ ）、粮油副产品和粮油食品4大类。", "options": [{"key": "A", "text": "谷类"}, {"key": "B", "text": "豆类"}, {"key": "C", "text": "油料与油脂"}, {"key": "D", "text": "薯类"}], "answer": "C", "analysis": "四大类中第二类为油料与油脂（如大豆、油菜籽、植物油等）。因此选C。"}, {"id": 264, "type": "单选", "question": "根据粮油商品的性质、用途，通常将其分为粮食、油料与油脂、（ ）和粮油食品4大类。", "options": [{"key": "A", "text": "谷类"}, {"key": "B", "text": "豆类"}, {"key": "C", "text": "粮油副产品"}, {"key": "D", "text": "薯类"}], "answer": "C", "analysis": "四大类中第三类为粮油副产品（如糠麸、饼粕等加工副产物）。因此选C。"}, {"id": 265, "type": "单选", "question": "谷类粮食由胚、胚乳和皮层３部分构成，下列粮食中不属于谷类的是（ ）。", "options": [{"key": "A", "text": "稻谷"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "大豆"}], "answer": "D", "analysis": "谷类由胚、胚乳、皮层三部分构成，稻谷、小麦、玉米均属谷类；大豆属豆类，由胚和皮层两部分构成。因此选D。"}, {"id": 266, "type": "单选", "question": "豆类粮食由胚和皮层２部分构成，下列粮食中属于豆类的是（ ）。", "options": [{"key": "A", "text": "稻谷"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "花生"}], "answer": "D", "analysis": "豆类由胚和皮层两部分构成，花生属豆科油料作物；稻谷、小麦、玉米均为谷类。因此选D。"}, {"id": 267, "type": "单选", "question": "下列粮食中既属于粮食又属于油料的是（ ）", "options": [{"key": "A", "text": "稻谷"}, {"key": "B", "text": "小麦"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "大豆"}], "answer": "D", "analysis": "大豆既可作为粮食（食用豆），又是重要的油料作物（榨油），属于既属粮食又属油料的品种。因此选D。"}, {"id": 268, "type": "单选", "question": "糯性谷物的淀粉几乎全部为（ ）。", "options": [{"key": "A", "text": "直链淀粉"}, {"key": "B", "text": "支链淀粉"}, {"key": "C", "text": "老化淀粉"}, {"key": "D", "text": "改性淀粉"}], "answer": "B", "analysis": "糯性谷物（如糯米）的淀粉几乎全部为支链淀粉，支链淀粉分支多、糊化后黏性大，是糯性的物质基础。因此选B。"}, {"id": 269, "type": "单选", "question": "人体必需氨基酸共有8种，包括苯丙氨酸、蛋氨酸、赖氨酸、苏氨酸、色氨酸、亮氨酸、（ ）。", "options": [{"key": "A", "text": "谷氨酸、异亮氨酸"}, {"key": "B", "text": "谷氨酸、异亮氨酸"}, {"key": "C", "text": "异亮氨酸、缬氨酸"}, {"key": "D", "text": "谷氨酸、甘氨酸"}], "answer": "C", "analysis": "人体8种必需氨基酸为苯丙氨酸、蛋氨酸、赖氨酸、苏氨酸、色氨酸、亮氨酸、异亮氨酸、缬氨酸，题干所缺为异亮氨酸和缬氨酸。因此选C。"}, {"id": 270, "type": "单选", "question": "人体必需氨基酸共有8种，包括苯丙氨酸、（ ）、苏氨酸、色氨酸、亮氨酸、异亮氨酸、缬氨酸。", "options": [{"key": "A", "text": "谷氨酸、赖氨酸"}, {"key": "B", "text": "谷氨酸、蛋氨酸"}, {"key": "C", "text": "蛋氨酸、赖氨酸"}, {"key": "D", "text": "谷氨酸、甘氨酸"}], "answer": "C", "analysis": "8种必需氨基酸完整列表为苯丙氨酸、蛋氨酸、赖氨酸、苏氨酸、色氨酸、亮氨酸、异亮氨酸、缬氨酸，题干中间所缺为蛋氨酸和赖氨酸。因此选C。"}, {"id": 271, "type": "单选", "question": "应对粮食安全问题的措施之一是保住（ ）亿亩耕地底线。", "options": [{"key": "A", "text": "15"}, {"key": "B", "text": "16"}, {"key": "C", "text": "17"}, {"key": "D", "text": "18"}], "answer": "D", "analysis": "国家为保障粮食安全划定了18亿亩耕地红线，这是必须保住的底线。因此选D。"}, {"id": 272, "type": "单选", "question": "粮食安全指保证粮食供给，达到粮食（ ）安全。", "options": [{"key": "A", "text": "数量"}, {"key": "B", "text": "质量"}, {"key": "C", "text": "数量和来源"}, {"key": "D", "text": "数量、质量和来源"}], "answer": "D", "analysis": "粮食安全不仅要求数量充足，还要求质量安全和来源（可得性）安全，即数量、质量和来源三维安全。因此选D。"}, {"id": 273, "type": "单选", "question": "当粮温高于环境温度2~3℃时，称热核心粮，粮堆中央气流做（ ）运动。", "options": [{"key": "A", "text": "上升"}, {"key": "B", "text": "下沉"}, {"key": "C", "text": "水平"}, {"key": "D", "text": "垂直"}], "answer": "A", "analysis": "当粮温高于环境温度2~3℃称为热核心粮，粮堆中心温度高使空气受热上升，中央气流做上升运动（热芯效应）。因此选A。"}, {"id": 274, "type": "单选", "question": "当粮温低于环境温度2~3℃时，称冷核心粮，粮堆中央气流做（ ）运动。", "options": [{"key": "A", "text": "上升"}, {"key": "B", "text": "下沉"}, {"key": "C", "text": "水平"}, {"key": "D", "text": "垂直"}], "answer": "B", "analysis": "当粮温低于环境温度2~3℃称为冷核心粮，中心相对偏冷使气流下沉，粮堆中央气流做下沉运动。因此选B。"}, {"id": 275, "type": "单选", "question": "( )不属于房式仓。", "options": [{"key": "A", "text": "楼房仓"}, {"key": "B", "text": "圆筒仓"}, {"key": "C", "text": "拱板仓"}, {"key": "D", "text": "平房仓"}], "answer": "B", "analysis": "房式仓包括平房仓、楼房仓、拱板仓等；圆筒仓（立筒仓）属于筒式仓，不属于房式仓。因此选B。"}, {"id": 276, "type": "单选", "question": "关于粮食呼吸作用的描述，下列说法错误的是( )。", "options": [{"key": "A", "text": "无氧呼吸的特点是有机物的氧化比较彻底，同时释放出较多的能量"}, {"key": "B", "text": "呼吸强度是衡量呼吸强弱的指标"}, {"key": "C", "text": "呼吸系数表示呼吸作用的性质"}, {"key": "D", "text": "影响粮粒呼吸作用的外部因素主要是水分、温度及环境气体成分"}], "answer": "A", "analysis": "无氧呼吸的特点是有机物氧化不彻底（生成酒精），释放能量少，而非\"氧化彻底、释放较多能量\"，该项描述错误。因此选A。"}, {"id": 277, "type": "单选", "question": "我国目前建造最多，使用最普遍的仓型是( )。", "options": [{"key": "A", "text": "房式仓"}, {"key": "B", "text": "立筒仓"}, {"key": "C", "text": "浅圆仓"}, {"key": "D", "text": "钢板筒仓"}], "answer": "A", "analysis": "在我国粮油仓储中，房式仓（尤其是平房仓）建造数量最多、使用最普遍。因此选A。"}, {"id": 278, "type": "单选", "question": "下列描述中，不正确的是( )。", "options": [{"key": "A", "text": "立筒仓的机械化程度高于平房仓"}, {"key": "B", "text": "浅圆仓的机械化程度高于平房仓"}, {"key": "C", "text": "钢板立筒仓的隔热和抗震性能较好"}, {"key": "D", "text": "立筒仓的建造费用高于平房仓"}], "answer": "C", "analysis": "钢板立筒仓由薄钢板制作，导热快、隔热性能差，且抗震并非其突出优点，故\"隔热和抗震性能较好\"描述不正确。因此选C。"}, {"id": 279, "type": "单选", "question": "按仓内堆装形式，粮食仓房可分为( )。", "options": [{"key": "A", "text": "房式仓、圆筒仓和地下仓"}, {"key": "B", "text": "一般粮仓和简易粮仓"}, {"key": "C", "text": "低温仓、准低温仓和常温仓"}, {"key": "D", "text": "包装仓和散装仓"}], "answer": "D", "analysis": "按仓内堆装形式，粮仓可分为包装仓和散装仓；房式/圆筒/地下是按建筑形态分，低温/常温是按控温分。因此选D。"}, {"id": 280, "type": "单选", "question": "下列描述中，不正确的是( )。", "options": [{"key": "A", "text": "包装仓在设计时未考虑粮食的侧压力"}, {"key": "B", "text": "散装仓能承受一定的粮食侧压力"}, {"key": "C", "text": "包装仓可以直接堆放散装粮"}, {"key": "D", "text": "散装仓可以直接堆放包装粮"}], "answer": "C", "analysis": "包装仓设计未考虑粮食侧压力，不能直接堆放散装粮；散装仓墙体可承受侧压，可兼放包装粮。因此选C。"}, {"id": 281, "type": "单选", "question": "下列描述中，不正确的是( )。", "options": [{"key": "A", "text": "散装仓的空间利用率高于包装仓"}, {"key": "B", "text": "包装仓的空间利用率高于散装仓"}, {"key": "C", "text": "散装仓能承受一定的粮食侧压力"}, {"key": "D", "text": "包装仓在设计时未考虑粮食的侧压力"}], "answer": "B", "analysis": "散装仓无需麻袋等包装物占空间，空间利用率高于包装仓，故\"包装仓利用率高于散装仓\"不正确。因此选B。"}, {"id": 282, "type": "单选", "question": "下列关于散装仓的描述，不正确的是( )。", "options": [{"key": "A", "text": "散装仓墙体厚实坚固"}, {"key": "B", "text": "散装仓墙体能承受一定的粮食侧压力"}, {"key": "C", "text": "散装仓的空间利用率高于包装仓"}, {"key": "D", "text": "散装仓不能兼做包装仓"}], "answer": "D", "analysis": "散装仓墙体厚实坚固、可承受侧压力、空间利用率高，且通常可兼做包装仓，故\"不能兼做包装仓\"描述不正确。因此选D。"}, {"id": 283, "type": "单选", "question": "标准代号为LS/T的含义是( )。", "options": [{"key": "A", "text": "强制性粮食行业标准"}, {"key": "B", "text": "推荐性粮食行业标准"}, {"key": "C", "text": "推荐性团体标准"}, {"key": "D", "text": "推荐性地方标准"}], "answer": "B", "analysis": "标准代号中LS代表粮食行业、T代表推荐性，LS/T即推荐性粮食行业标准。因此选B。"}, {"id": 284, "type": "单选", "question": "粮食中存在的糖类主要是（ ）。", "options": [{"key": "A", "text": "淀粉"}, {"key": "B", "text": "纤维素"}, {"key": "C", "text": "核糖"}, {"key": "D", "text": "蔗糖"}], "answer": "A", "analysis": "粮食中存在的糖类主要以淀粉形式存在，淀粉是谷类籽粒的主要储藏性多糖。因此选A。"}, {"id": 285, "type": "单选", "question": "粮食微生物不包括（ ）。", "options": [{"key": "A", "text": "霉菌"}, {"key": "B", "text": "酵母菌"}, {"key": "C", "text": "细菌和放线菌"}, {"key": "D", "text": "藻类"}], "answer": "D", "analysis": "粮食微生物主要包括霉菌、酵母菌、细菌和放线菌；藻类不属储粮微生物范畴。因此选D。"}, {"id": 286, "type": "单选", "question": "（ ）是引起物质霉腐的丝状真菌的统称。", "options": [{"key": "A", "text": "霉菌"}, {"key": "B", "text": "酵母菌"}, {"key": "C", "text": "细菌"}, {"key": "D", "text": "放线菌"}], "answer": "A", "analysis": "霉菌是引起物质霉腐的丝状真菌的统称，通过菌丝体生长导致粮食发热霉变。因此选A。"}, {"id": 287, "type": "单选", "question": "（ ）菌体的基本形态为球状、杆状和螺旋状。", "options": [{"key": "A", "text": "霉菌"}, {"key": "B", "text": "酵母菌"}, {"key": "C", "text": "细菌"}, {"key": "D", "text": "放线菌"}], "answer": "C", "analysis": "细菌的基本形态为球状（球菌）、杆状（杆菌）和螺旋状（螺旋菌），这是细菌形态学特征。因此选C。"}, {"id": 288, "type": "单选", "question": "粮食中的水分有结合水与自由水。其中（ ）存在于粮粒细胞间隙或毛细管中，具有天然水的性质。", "options": [{"key": "A", "text": "结合水"}, {"key": "B", "text": "自由水"}, {"key": "C", "text": "平衡水"}, {"key": "D", "text": "临界水"}], "answer": "B", "analysis": "自由水存在于粮粒细胞间隙或毛细管中，具有天然水的性质、易流动并参与生化反应；结合水则与胶体结合。因此选B。"}, {"id": 289, "type": "单选", "question": "加工精度越高的粮食，各种维生素的( )越低。", "options": [{"key": "A", "text": "保存率"}, {"key": "B", "text": "损失率"}, {"key": "C", "text": "消化率"}, {"key": "D", "text": "功效"}], "answer": "A", "analysis": "加工精度越高，皮层和胚芽去除越彻底，而维生素主要集中在皮层和胚芽中，故各种维生素保存率越低。因此选A。"}, {"id": 290, "type": "单选", "question": "推荐性国家标准是（ ）的标准，任何生产单位有权决定是否采用。", "options": [{"key": "A", "text": "强制性"}, {"key": "B", "text": "非强制性"}, {"key": "C", "text": "可变更"}, {"key": "D", "text": "法定"}], "answer": "B", "analysis": "推荐性国家标准（GB/T）是非强制性的，任何单位和个人有权决定是否采用，不同于强制性标准。因此选B。"}, {"id": 291, "type": "单选", "question": "标准一经发布，就是技术法规，任何单位和个人都不得擅自（ ）标准。", "options": [{"key": "A", "text": "提高"}, {"key": "B", "text": "降低"}, {"key": "C", "text": "提高或降低"}, {"key": "D", "text": "补充"}], "answer": "C", "analysis": "标准一经发布即具技术法规性质，其指标不得擅自提高或降低，以保证标准的严肃性和统一性。因此选C。"}, {"id": 292, "type": "单选", "question": "控制储粮环境，保持粮堆的（ ）是储粮防霉的基本措施。", "options": [{"key": "A", "text": "干燥、低温、缺氧"}, {"key": "B", "text": "干燥"}, {"key": "C", "text": "低温"}, {"key": "D", "text": "缺氧"}], "answer": "A", "analysis": "控制储粮环境、保持粮堆干燥、低温、缺氧，能从水分、温度、气体三方面抑制微生物生长，是防霉的基本措施。因此选A。"}, {"id": 293, "type": "单选", "question": "对油罐的性能要求包括（ ）。", "options": [{"key": "A", "text": "通风性能"}, {"key": "B", "text": "隔热性能"}, {"key": "C", "text": "防潮性能"}, {"key": "D", "text": "防渗漏性能、耐腐蚀性能、隔热性能和防冻性能"}], "answer": "D", "analysis": "油罐储存液态油脂，必须具备防渗漏、耐腐蚀、隔热和防冻性能，以保障油品质量与储运安全。因此选D。"}, {"id": 294, "type": "单选", "question": "粮堆中杂质较多的部位，往往水分较高，（ ）容易滋生。", "options": [{"key": "A", "text": "霉菌"}, {"key": "B", "text": "酵母菌"}, {"key": "C", "text": "细菌和放线菌"}, {"key": "D", "text": "虫霉"}], "answer": "D", "analysis": "粮堆中杂质（尤其有机杂质）多的部位易积湿热、吸湿，水分偏高，害虫和霉菌（虫霉）容易滋生。因此选D。"}, {"id": 295, "type": "单选", "question": "完成后熟休眠的粮油籽粒，供给适宜的( )，就能发芽。", "options": [{"key": "A", "text": "水分、温度和氧气"}, {"key": "B", "text": "水分"}, {"key": "C", "text": "温度"}, {"key": "D", "text": "氧气"}], "answer": "A", "analysis": "完成后熟休眠的籽粒，只要供给适宜的水分、温度和氧气三要素，即可启动发芽，发芽会消耗养分损害品质。因此选A。"}, {"id": 296, "type": "单选", "question": "高温、（ ），是导致食用油氧化、酸败，产生醛酮等有害物质的元凶。", "options": [{"key": "A", "text": "氧气"}, {"key": "B", "text": "水分"}, {"key": "C", "text": "光照"}, {"key": "D", "text": "氧气、水分和光照"}], "answer": "D", "analysis": "食用油氧化酸败由高温、氧气、水分和光照共同促进，产生醛酮等有害物质，故应低温、避光、密封、充氮储藏。因此选D。"}, {"id": 297, "type": "单选", "question": "储藏期间不耐高温，容易变黄、爆腰、陈化的粮种是（ ）。", "options": [{"key": "A", "text": "小麦"}, {"key": "B", "text": "玉米"}, {"key": "C", "text": "稻谷"}, {"key": "D", "text": "大豆"}], "answer": "C", "analysis": "稻谷不耐高温，高温下易出现爆腰、变黄、陈化等品质劣变，对温变较为敏感。因此选C。"}, {"id": 298, "type": "单选", "question": "测定矿物质的方法是高温灼烧除去碳、氢、氧、氮有机物，留下的灰烬残渣作为矿物质的含量，所以矿物质又称（ ）。", "options": [{"key": "A", "text": "霉菌"}, {"key": "B", "text": "酵母菌"}, {"key": "C", "text": "细菌和放线菌"}, {"key": "D", "text": "灰分"}], "answer": "D", "analysis": "测定矿物质时高温灼烧除去碳氢氧氮等有机物，残留灰烬即为矿物质含量，故矿物质又称灰分。因此选D。"}, {"id": 299, "type": "单选", "question": "( )能直观反映出空气接近饱和的程度。", "options": [{"key": "A", "text": "平衡绝对湿度"}, {"key": "B", "text": "绝对湿度"}, {"key": "C", "text": "相对湿度"}, {"key": "D", "text": "饱和湿度"}], "answer": "C", "analysis": "相对湿度是实际绝对湿度与同温饱和湿度的比值，能直观反映空气接近饱和的程度。因此选C。"}, {"id": 300, "type": "单选", "question": "粮食在储藏期间发芽，会造成品质劣变，使（ ）。", "options": [{"key": "A", "text": "加工成品率大幅下降"}, {"key": "B", "text": "食用品质大幅下降"}, {"key": "C", "text": "食用品质和加工成品率大幅下降"}, {"key": "D", "text": "营养品质提高"}], "answer": "C", "analysis": "粮食在储藏期间发芽会消耗胚乳养分、损伤籽粒，导致食用品质和加工成品率同时大幅下降。因此选C。"}, {"id": 301, "type": "单选", "question": "完全变态的昆虫具有（ ）个不同的虫期。", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "answer": "C", "analysis": "完全变态昆虫一生经历卵、幼虫、蛹、成虫四个明显不同的虫期，故具有4个虫期（选C）。而不完全变态只有卵、若虫、成虫3个时期，缺少蛹期。"}, {"id": 302, "type": "单选", "question": "不完全变态的昆虫具有（ ）个不同的虫期。", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "answer": "B", "analysis": "不完全变态昆虫的发育只经过卵、若虫、成虫3个虫期，若虫与成虫形态、习性相近，不经历蛹期（选B）。完全变态才有4个虫期。"}, {"id": 303, "type": "单选", "question": "下列虫期中，不完全变态类昆虫不具有的虫期是（ ）。", "options": [{"key": "A", "text": "卵期"}, {"key": "B", "text": "若虫期"}, {"key": "C", "text": "蛹期"}, {"key": "D", "text": "成虫期"}], "answer": "C", "analysis": "不完全变态类昆虫（卵、若虫、成虫）没有蛹期，蛹是完全变态类昆虫特有的虫期（选C）。完全变态才经历卵、幼虫、蛹、成虫四阶段。"}, {"id": 304, "type": "单选", "question": "影响昆虫生命活动的温区的划分，致死高温区的温度一般为（ ）℃以上。", "options": [{"key": "A", "text": "20"}, {"key": "B", "text": "30"}, {"key": "C", "text": "40"}, {"key": "D", "text": "50"}], "answer": "D", "analysis": "昆虫温区划分中，致死高温区一般为50℃以上，此时虫体蛋白质凝固、酶失活而死亡（选D）。亚致死高温区在40～50℃，致死低温区在-15℃以下。"}, {"id": 305, "type": "单选", "question": "影响昆虫生命活动的温区的划分，亚致死高温区的温度范围一般为（ ）℃。", "options": [{"key": "A", "text": "20-30"}, {"key": "B", "text": "30-40"}, {"key": "C", "text": "40-50"}, {"key": "D", "text": "50-60"}], "answer": "C", "analysis": "昆虫温区划分里，亚致死高温区为40～50℃，此温度区间昆虫发育受抑或呈热麻痹但尚未立即致死（选C）。超过50℃才进入致死高温区。"}, {"id": 306, "type": "单选", "question": "影响昆虫生命活动的温区的划分，致死低温区的温度范围一般为（ ）℃以下。", "options": [{"key": "A", "text": "15"}, {"key": "B", "text": "0"}, {"key": "C", "text": "-5"}, {"key": "D", "text": "-15"}], "answer": "D", "analysis": "致死低温区一般为-15℃以下，低温使虫体结冰、原生质脱水而死亡（选D）。亚致死低温区约-15～8℃，最适温区约25～35℃。"}, {"id": 307, "type": "单选", "question": "储粮昆虫隶属于动物界的（ ）门。", "options": [{"key": "A", "text": "软体动物"}, {"key": "B", "text": "脊索动物"}, {"key": "C", "text": "节肢动物"}, {"key": "D", "text": "环节动物"}], "answer": "C", "analysis": "储粮昆虫在动物界中属于节肢动物门（选C）。节肢动物门还包括蛛形纲、甲壳纲等，昆虫属于其中的昆虫纲。"}, {"id": 308, "type": "单选", "question": "储粮螨类隶属于动物界的（ ）门。", "options": [{"key": "A", "text": "软体动物"}, {"key": "B", "text": "脊索动物"}, {"key": "C", "text": "节肢动物"}, {"key": "D", "text": "环节动物"}], "answer": "C", "analysis": "储粮螨类同样归属于节肢动物门（选C），与昆虫同门但不同纲，属于蛛形纲。"}, {"id": 309, "type": "单选", "question": "储粮螨类隶属于动物界、节肢动物门、（ ）纲。", "options": [{"key": "A", "text": "昆虫"}, {"key": "B", "text": "甲壳"}, {"key": "C", "text": "多足"}, {"key": "D", "text": "蛛形"}], "answer": "D", "analysis": "储粮螨类属于节肢动物门中的蛛形纲（选D），而非昆虫纲。蛛形纲特征为体躯分颚体和躯体，成螨有4对足。"}, {"id": 310, "type": "单选", "question": "昆虫头部的重要感觉器官，一对十分灵活、可转动的分节附肢是（ ）。", "options": [{"key": "A", "text": "前足"}, {"key": "B", "text": "翅"}, {"key": "C", "text": "触角"}, {"key": "D", "text": "口器"}], "answer": "C", "analysis": "触角着生于昆虫头部，是一对灵活、可转动的分节附肢，是重要的嗅觉和触觉感觉器官（选C）。前足、翅、口器均不具备该描述。"}, {"id": 311, "type": "单选", "question": "昆虫的三个体段不包括（ ）。", "options": [{"key": "A", "text": "头部"}, {"key": "B", "text": "胸部"}, {"key": "C", "text": "腹部"}, {"key": "D", "text": "尾部"}], "answer": "D", "analysis": "昆虫体躯由头部、胸部、腹部三个体段组成，没有独立的“尾部”（选D）。尾部并非昆虫的标准体段划分。"}, {"id": 312, "type": "单选", "question": "能够取食危害粮油的害虫的口器类型都是（ ）。", "options": [{"key": "A", "text": "咀嚼式口器"}, {"key": "B", "text": "虹吸式口器"}, {"key": "C", "text": "刺吸式口器"}, {"key": "D", "text": "吮吸式口器"}], "answer": "A", "analysis": "能直接取食、蛀食危害粮油的储粮害虫（甲虫类及蛾类幼虫）都具咀嚼式口器（选A），能咬碎粮粒。虹吸式、刺吸式口器一般不直接取食粮食。"}, {"id": 313, "type": "单选", "question": "储粮蛾类害虫成虫的口器类型是（ ）。", "options": [{"key": "A", "text": "咀嚼式口器"}, {"key": "B", "text": "虹吸式口器"}, {"key": "C", "text": "刺吸式口器"}, {"key": "D", "text": "吮吸式口器"}], "answer": "B", "analysis": "储粮蛾类（如麦蛾、印度谷蛾）成虫口器为虹吸式，仅能吸食花蜜或液体、不危害粮食（选B）。真正危害粮食的是其咀嚼式口器的幼虫。"}, {"id": 314, "type": "单选", "question": "鞘翅目储粮害虫的口器类型都是（ ）。", "options": [{"key": "A", "text": "咀嚼式口器"}, {"key": "B", "text": "虹吸式口器"}, {"key": "C", "text": "刺吸式口器"}, {"key": "D", "text": "吮吸式口器"}], "answer": "A", "analysis": "鞘翅目储粮害虫（如玉米象、谷蠹、赤拟谷盗）均为咀嚼式口器，靠啃食粮粒造成危害（选A）。"}, {"id": 315, "type": "单选", "question": "储粮蛾类害虫幼虫的口器类型是（ ）。", "options": [{"key": "A", "text": "咀嚼式口器"}, {"key": "B", "text": "虹吸式口器"}, {"key": "C", "text": "刺吸式口器"}, {"key": "D", "text": "吮吸式口器"}], "answer": "A", "analysis": "储粮蛾类害虫的幼虫阶段口器为咀嚼式，蛀食粮粒、造成重量与品质损失（选A）。成虫虹吸式口器才不危害粮食。"}, {"id": 316, "type": "单选", "question": "储粮害虫触角的结构不包括（ ）。", "options": [{"key": "A", "text": "柄节"}, {"key": "B", "text": "梗节"}, {"key": "C", "text": "股节"}, {"key": "D", "text": "鞭节"}], "answer": "C", "analysis": "昆虫触角由柄节、梗节、鞭节三部分组成（选C“股节”错误）。股节是胸足的组成部分，不属于触角结构。"}, {"id": 317, "type": "单选", "question": "绿豆象雄虫的触角形状是（ ）。", "options": [{"key": "A", "text": "梳齿状"}, {"key": "B", "text": "锯齿状"}, {"key": "C", "text": "丝状"}, {"key": "D", "text": "锤状"}], "answer": "A", "analysis": "绿豆象雄虫触角呈梳齿状（栉齿状），雌虫为锯齿状，这是鉴别雌雄的重要特征（选A）。"}, {"id": 318, "type": "单选", "question": "玉米象的触角形状是（ ）。", "options": [{"key": "A", "text": "梳齿状"}, {"key": "B", "text": "锯齿状"}, {"key": "C", "text": "丝状"}, {"key": "D", "text": "膝状"}], "answer": "D", "analysis": "玉米象（米象）的触角为膝状（肘状），各节弯曲如膝（选D）。这一特征是象甲科昆虫的典型形态。"}, {"id": 319, "type": "单选", "question": "储粮害虫胸足的结构不包括（ ）。", "options": [{"key": "A", "text": "股节"}, {"key": "B", "text": "胫节"}, {"key": "C", "text": "跗节"}, {"key": "D", "text": "鞭节"}], "answer": "D", "analysis": "储粮害虫胸足由基节、转节、股节、胫节、跗节等组成，鞭节是触角的结构而非足的结构（选D）。"}, {"id": 320, "type": "单选", "question": "甲虫类储粮害虫的前翅类型是（ ）。", "options": [{"key": "A", "text": "鳞翅"}, {"key": "B", "text": "膜翅"}, {"key": "C", "text": "鞘翅"}, {"key": "D", "text": "革翅"}], "answer": "C", "analysis": "甲虫类（鞘翅目）成虫的前翅特化为坚硬的角质鞘翅，起保护作用（选C）。后翅才是膜质用于飞行。"}, {"id": 321, "type": "单选", "question": "蛾类储粮害虫翅的类型是（ ）。", "options": [{"key": "A", "text": "鳞翅"}, {"key": "B", "text": "膜翅"}, {"key": "C", "text": "鞘翅"}, {"key": "D", "text": "革翅"}], "answer": "A", "analysis": "蛾类（鳞翅目）成虫翅面密被鳞片，属于鳞翅（选A）。鳞翅目因而得名。"}, {"id": 322, "type": "单选", "question": "甲虫类储粮害虫后翅的类型是（ ）。", "options": [{"key": "A", "text": "鳞翅"}, {"key": "B", "text": "膜翅"}, {"key": "C", "text": "鞘翅"}, {"key": "D", "text": "革翅"}], "answer": "B", "analysis": "甲虫类前翅为鞘翅，后翅为膜翅，膜质透明、用于飞行（选B）。"}, {"id": 323, "type": "单选", "question": "下列器官，生长在储粮害虫腹部的器官是（ ）。", "options": [{"key": "A", "text": "翅"}, {"key": "B", "text": "触角"}, {"key": "C", "text": "生殖器官"}, {"key": "D", "text": "口器"}], "answer": "C", "analysis": "昆虫腹部着生生殖器官（雌、雄外生殖器）及大部分内脏器官（选C）。翅生于胸部，触角、口器生于头部。"}, {"id": 324, "type": "单选", "question": "储粮害虫腹部是（ ）的中心。", "options": [{"key": "A", "text": "感觉"}, {"key": "B", "text": "取食"}, {"key": "C", "text": "生殖和代谢"}, {"key": "D", "text": "运动"}], "answer": "C", "analysis": "腹部是昆虫生殖和代谢的中心，容纳生殖系统和主要内脏器官（选C）。头部管感觉与取食，胸部管运动。"}, {"id": 325, "type": "单选", "question": "储粮害虫的头部是（ ）和取食的中心。", "options": [{"key": "A", "text": "感觉"}, {"key": "B", "text": "运动"}, {"key": "C", "text": "生殖"}, {"key": "D", "text": "代谢"}], "answer": "A", "analysis": "昆虫头部集中了触角、复眼、单眼等感觉器官和取食的口器，是感觉和取食的中心（选A）。"}, {"id": 326, "type": "单选", "question": "储粮害虫防治应遵循“以防为主，（ ）”的方针。", "options": [{"key": "A", "text": "防消结合"}, {"key": "B", "text": "防治并举"}, {"key": "C", "text": "安全卫生"}, {"key": "D", "text": "综合防治"}], "answer": "D", "analysis": "我国储粮害虫防治方针为“以防为主，综合防治”（选D），强调预防优先、多种手段相结合。"}, {"id": 327, "type": "单选", "question": "储粮害虫的防治原则是：（ ）、卫生、经济、有效。", "options": [{"key": "A", "text": "严格"}, {"key": "B", "text": "安全"}, {"key": "C", "text": "质量"}, {"key": "D", "text": "实用"}], "answer": "B", "analysis": "储粮害虫防治的四项原则为“安全、卫生、经济、有效”（选B）。其中安全是前提，有效是目的。"}, {"id": 328, "type": "单选", "question": "对于我国储粮害虫的防治原则，其中（ ）是前提。", "options": [{"key": "A", "text": "卫生"}, {"key": "B", "text": "安全"}, {"key": "C", "text": "经济"}, {"key": "D", "text": "有效"}], "answer": "B", "analysis": "在“安全、卫生、经济、有效”四原则中，安全是前提（选B），即一切防治措施必须把人、粮、环境安全放在首位。"}, {"id": 329, "type": "单选", "question": "利用害虫的天敌去防治害虫，其方法属于（ ）。", "options": [{"key": "A", "text": "仓储管理防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "法规防治"}, {"key": "D", "text": "气调防治"}], "answer": "B", "analysis": "利用害虫天敌（寄生蜂、捕食性昆虫等）控制害虫数量，属于生物防治（选B）。它不依赖化学药剂，安全环保。"}, {"id": 330, "type": "单选", "question": "储粮熏蒸剂是以（ ）状态经害虫的呼吸系统进入虫体发挥药效的杀虫剂。", "options": [{"key": "A", "text": "气体"}, {"key": "B", "text": "液体"}, {"key": "C", "text": "固体"}, {"key": "D", "text": "烟雾"}], "answer": "A", "analysis": "熏蒸剂在特定温压下以气体状态扩散，经害虫呼吸系统（气门）进入虫体发挥毒杀作用（选A）。这是熏蒸与胃毒、触杀剂的根本区别。"}, {"id": 331, "type": "单选", "question": "防治储粮害虫目前应用最广泛的防治方法是（ ）。", "options": [{"key": "A", "text": "化学防治"}, {"key": "B", "text": "天敌防治"}, {"key": "C", "text": "电离辐射防治"}, {"key": "D", "text": "微生物防治"}], "answer": "A", "analysis": "目前储粮害虫防治中应用最广泛的是化学防治（选A），如磷化氢熏蒸、防护剂拌粮等，因其高效、经济、易操作。"}, {"id": 332, "type": "单选", "question": "通过清洁卫生方式改善仓储环境，消除害虫藏匿空间的手段去防治害虫，其方法属于（ ）。", "options": [{"key": "A", "text": "仓储管理防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "法规防治"}, {"key": "D", "text": "气调防治"}], "answer": "A", "analysis": "通过清洁、消毒、隔离等仓储管理措施改善环境、消除害虫孳生与藏匿场所，属于仓储管理防治（选A），是“以防为主”的基础。"}, {"id": 333, "type": "单选", "question": "使用风车、风扬等设备产生气流将害虫和粮食分离的方法属于（ ）。", "options": [{"key": "A", "text": "机械防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "法规防治"}, {"key": "D", "text": "气调防治"}], "answer": "A", "analysis": "利用风车、风扬等设备产生气流，依害虫与粮粒比重、悬浮速度差异将二者分离，属于机械防治（选A）。"}, {"id": 334, "type": "单选", "question": "使用各种筛子将害虫和粮食分离的方法属于（ ）。", "options": [{"key": "A", "text": "法规防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "机械防治"}, {"key": "D", "text": "气调防治"}], "answer": "C", "analysis": "使用各种筛子按虫体与粮粒大小差异进行筛选分离，属于机械防治（选C）。机械防治还包括风选、筛选等物理除虫。"}, {"id": 335, "type": "单选", "question": "压盖防治主要用于防治储粮害虫中的（ ）害虫。", "options": [{"key": "A", "text": "甲虫类"}, {"key": "B", "text": "蛾类"}, {"key": "C", "text": "书虱"}, {"key": "D", "text": "螨类"}], "answer": "B", "analysis": "压盖防治（用异种粮或物料压盖粮面）主要阻止蛾类成虫在粮面产卵、羽化出土，适用于防治蛾类害虫（选B）。"}, {"id": 336, "type": "单选", "question": "使用压盖防治储粮害虫，压盖时间应在（ ）。", "options": [{"key": "A", "text": "第一代幼虫羽化前"}, {"key": "B", "text": "第一代卵孵化前"}, {"key": "C", "text": "第二代幼虫羽化前"}, {"key": "D", "text": "第二代卵孵化前"}], "answer": "A", "analysis": "压盖防治应在第一代幼虫羽化出土前完成，以阻断成虫钻出粮面交配产卵（选A）。错过时机则压盖效果大减。"}, {"id": 337, "type": "单选", "question": "通过改变正常大气中的氮气、二氧化碳和氧气的比例防治害虫的技术是（ ）。", "options": [{"key": "A", "text": "法规防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "机械防治"}, {"key": "D", "text": "气调防治"}], "answer": "D", "analysis": "气调防治通过改变粮堆中氮气、二氧化碳、氧气的比例（如降氧或充氮），使害虫缺氧死亡（选D）。属物理生态防治。"}, {"id": 338, "type": "单选", "question": "充氮气调使密封粮堆中的氧气含量低于（ ），暴露13-15天，便能有效控制储粮害虫。", "options": [{"key": "A", "text": "3%"}, {"key": "B", "text": "5%"}, {"key": "C", "text": "7%"}, {"key": "D", "text": "9%"}], "answer": "A", "analysis": "充氮气调通常将密封粮堆内氧气降至3%以下并维持13～15天，即可有效控制绝大多数储粮害虫（选A）。低氧使害虫窒息、代谢紊乱。"}, {"id": 339, "type": "单选", "question": "日晒热入仓密闭储藏杀虫的技术属于（ ）。", "options": [{"key": "A", "text": "法规防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "机械防治"}, {"key": "D", "text": "高温防治"}], "answer": "D", "analysis": "日晒热入仓密闭储藏是利用夏季高温暴晒使粮温升高后趁热密闭，以高温杀虫，属于高温防治（选D）。"}, {"id": 340, "type": "单选", "question": "下列粮种中，可以使用日晒热入仓密闭储藏杀虫技术的是（ ）。", "options": [{"key": "A", "text": "稻谷"}, {"key": "B", "text": "大豆"}, {"key": "C", "text": "小麦"}, {"key": "D", "text": "玉米"}], "answer": "C", "analysis": "小麦耐热性强，可采用日晒热入仓密闭杀虫；稻谷、玉米受热易“爆腰”或变色降等，不宜采用高温密闭法（选C）。"}, {"id": 341, "type": "单选", "question": "采用微波、X射线、γ射线和电子束来杀死储粮害虫的防治技术是（ ）。", "options": [{"key": "A", "text": "机械防治"}, {"key": "B", "text": "生物防治"}, {"key": "C", "text": "电离辐射防治"}, {"key": "D", "text": "高温防治"}], "answer": "C", "analysis": "利用微波、X射线、γ射线、电子束等电离辐射破坏害虫机体，属电离辐射防治（选C）。该法无化学残留但设备成本高。"}, {"id": 342, "type": "单选", "question": "下列储粮害虫天敌中，属于捕食性天敌的是（ ）。", "options": [{"key": "A", "text": "米象小蜂"}, {"key": "B", "text": "麦蛾茧蜂"}, {"key": "C", "text": "苏云金杆菌"}, {"key": "D", "text": "窗虻"}], "answer": "D", "analysis": "窗虻以捕食储粮害虫为生，属捕食性天敌（选D）。米象小蜂、麦蛾茧蜂是寄生性天敌，苏云金杆菌是微生物杀虫剂。"}, {"id": 343, "type": "单选", "question": "下列储粮害虫天敌中，属于寄生性天敌的是（ ）。", "options": [{"key": "A", "text": "米象小蜂"}, {"key": "B", "text": "拟蝎"}, {"key": "C", "text": "黄色食虫蝽"}, {"key": "D", "text": "窗虻"}], "answer": "A", "analysis": "米象小蜂将卵产于米象等害虫体内、幼虫寄生取食致死寄主，属寄生性天敌（选A）。窗虻、拟蝎等为捕食性。"}, {"id": 344, "type": "单选", "question": "下列药剂中，属于储粮保护剂的是（ ）。", "options": [{"key": "A", "text": "防虫磷"}, {"key": "B", "text": "敌敌畏"}, {"key": "C", "text": "敌百虫"}, {"key": "D", "text": "磷化铝"}], "answer": "A", "analysis": "防虫磷（杀螟硫磷等）是拌粮用的储粮保护剂，残效期长、直接保护粮食（选A）。敌敌畏、敌百虫为熏蒸/喷洒剂，磷化铝为熏蒸剂。"}, {"id": 345, "type": "单选", "question": "下列药剂中，不属于储粮保护剂的是（ ）。", "options": [{"key": "A", "text": "防虫磷"}, {"key": "B", "text": "敌敌畏"}, {"key": "C", "text": "杀虫松"}, {"key": "D", "text": "凯安保"}], "answer": "B", "analysis": "敌敌畏属熏蒸性、空仓消毒用杀虫剂，不属于长期拌粮的保护剂（选B）。防虫磷、杀虫松、凯安保均为储粮保护剂。"}, {"id": 346, "type": "单选", "question": "下列药剂中，对谷蠹有特效的储粮保护剂是（ ）。", "options": [{"key": "A", "text": "防虫磷"}, {"key": "B", "text": "保安定"}, {"key": "C", "text": "杀虫松"}, {"key": "D", "text": "凯安保"}], "answer": "D", "analysis": "凯安保（溴氰菊酯类）对钻蛀性强的谷蠹有特效，是常用的储粮保护剂之一（选D）。"}, {"id": 347, "type": "单选", "question": "储粮保护剂最后一次使用后至其在粮食中的残留量降至卫生标准要求的最大限量以下所经历的时间是（ ）。", "options": [{"key": "A", "text": "安全期"}, {"key": "B", "text": "挥发期"}, {"key": "C", "text": "药剂有效期"}, {"key": "D", "text": "安全间隔期"}], "answer": "D", "analysis": "安全间隔期指最后一次施药至粮食中药剂残留降至国家卫生标准限量以下所必须经过的时间（选D）。它是保障食用安全的关键指标。"}, {"id": 348, "type": "单选", "question": "储粮保护剂按表层施药法进行施药，按粮堆表面（ ）cm厚的粮层计算用药量。", "options": [{"key": "A", "text": "20"}, {"key": "B", "text": "30"}, {"key": "C", "text": "40"}, {"key": "D", "text": "50"}], "answer": "B", "analysis": "储粮保护剂采用表层施药法时，按粮堆表面30cm厚粮层计算用药量（选B），以在粮堆表层形成有效保护带。"}, {"id": 349, "type": "单选", "question": "在特定的温度和压力下，能够以足够的气态浓度致死有害生物的化学物质称为（ ）。", "options": [{"key": "A", "text": "触杀剂"}, {"key": "B", "text": "胃毒剂"}, {"key": "C", "text": "忌避剂"}, {"key": "D", "text": "熏蒸剂"}], "answer": "D", "analysis": "熏蒸剂是在特定温度和压力下能产生足够气态浓度致死有害生物的化学物质（选D），如磷化铝释出的磷化氢。"}, {"id": 350, "type": "单选", "question": "在储粮害虫防治中，使用（ ）产生磷化氢的方法，使用最为广泛。", "options": [{"key": "A", "text": "磷化锌"}, {"key": "B", "text": "磷化铝"}, {"key": "C", "text": "磷化钙"}, {"key": "D", "text": "磷化铜"}], "answer": "B", "analysis": "储粮中利用磷化铝（AlP）遇水潮分解产生磷化氢（PH₃）的方法使用最广泛（选B），因其便于储运、投药均匀。"}, {"id": 351, "type": "单选", "question": "磷化氢熏蒸杀虫，最常用的磷化铝剂型是（ ）。", "options": [{"key": "A", "text": "粉剂"}, {"key": "B", "text": "片剂"}, {"key": "C", "text": "丸剂"}, {"key": "D", "text": "烟剂"}], "answer": "B", "analysis": "磷化铝最常用的剂型是片剂（选B），每片约3g，便于整仓均匀布点投药、反应平稳可控。"}, {"id": 352, "type": "单选", "question": "磷化铝片剂每片完全反应可释放磷化氢约（ ）g。", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": "A", "analysis": "每片磷化铝（约3g）完全反应可释放磷化氢约1g（选A），据此可计算整仓所需投药片数以达到有效浓度。"}, {"id": 353, "type": "单选", "question": "在同一地区连续使用某种药剂，使害虫对该药剂抵抗能力明显增强的现象称为（ ）", "options": [{"key": "A", "text": "抗药性"}, {"key": "B", "text": "敏感性"}, {"key": "C", "text": "群集性"}, {"key": "D", "text": "失效性"}], "answer": "A", "analysis": "同一地区长期连续使用同种药剂，使害虫种群对该药抵抗力显著增强，称为抗药性（选A）。轮换用药可延缓抗药性产生。"}, {"id": 354, "type": "单选", "question": "磷化铝常规熏蒸时，房式仓每廒间应设不少于（ ）个气体取样点。", "options": [{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "7"}], "answer": "B", "analysis": "磷化铝常规熏蒸时，房式仓每廒间应设不少于5个气体取样点，以监测各部位磷化氢浓度是否达标（选B）。"}, {"id": 355, "type": "单选", "question": "磷化铝常规熏蒸时，使用器皿施药法，器皿间距为（ ）m左右。", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "1.3"}, {"key": "C", "text": "2"}, {"key": "D", "text": "2.3"}], "answer": "B", "analysis": "常规熏蒸采用器皿施药法时，器皿（施药盘）间距约为1.3m，保证气体均匀分布（选B）。"}, {"id": 356, "type": "单选", "question": "磷化氢熏蒸散气后通过监测粮仓内磷化氢浓度，浓度降到（ ）mL/m3以下人员方可进仓。", "options": [{"key": "A", "text": "0.1"}, {"key": "B", "text": "0.2"}, {"key": "C", "text": "0.5"}, {"key": "D", "text": "0.7"}], "answer": "B", "analysis": "磷化氢熏蒸散气后，须监测仓内磷化氢浓度降至0.2 mL/m³以下，人员方可进仓作业（选B），以防中毒。"}, {"id": 357, "type": "单选", "question": "利用环流风机，强制气流循环，促使磷化氢气体在粮堆内快速均匀分布，达到有效杀虫的技术称为（ ）。", "options": [{"key": "A", "text": "常规熏蒸"}, {"key": "B", "text": "缓释剂熏蒸"}, {"key": "C", "text": "探管熏蒸"}, {"key": "D", "text": "环流熏蒸"}], "answer": "D", "analysis": "环流熏蒸是利用环流风机强制气流循环，使磷化氢在粮堆内快速均匀分布、提高杀虫效果的技术（选D）。"}, {"id": 358, "type": "单选", "question": "检查熏蒸效果的取样培养检查法，在熏蒸前生虫部位随机取样1kg以上，在温度25℃、相对湿度75%和防止外来害虫感染的条件下放置（ ）天，检查是否出现活虫。", "options": [{"key": "A", "text": "15"}, {"key": "B", "text": "30"}, {"key": "C", "text": "60"}, {"key": "D", "text": "90"}], "answer": "B", "analysis": "熏蒸效果取样培养检查法：取样1kg以上，于25℃、相对湿度75%条件下放置30天，检查有无活虫（选B）。仍有活虫则需补充熏蒸。"}, {"id": 359, "type": "单选", "question": "磷化铝常规熏蒸时，使用器皿施药法，每个器皿中片剂、丸剂不超过（ ）g。", "options": [{"key": "A", "text": "100"}, {"key": "B", "text": "150"}, {"key": "C", "text": "200"}, {"key": "D", "text": "250"}], "answer": "B", "analysis": "常规熏蒸器皿施药时，每个器皿中放置的片剂或丸剂不超过150g，以防局部反应过剧、产热或起火（选B）。"}, {"id": 360, "type": "判断", "question": "谷类粮食皆是不完全蛋白质，所以倡导主食多样化，可取长补短。", "options": ["√", "×"], "answer": "√", "analysis": "谷类蛋白质普遍缺乏赖氨酸等必需氨基酸，属不完全蛋白质，故提倡米面杂粮混食、互补氨基酸（√）。"}, {"id": 361, "type": "判断", "question": "必需脂肪酸：必须由食物提供，且又是维持机体生命活动所必需的脂肪酸。", "options": ["√", "×"], "answer": "√", "analysis": "必需脂肪酸人体不能自身合成、必须由食物供给，且为维持生命活动所必需（如亚油酸、亚麻酸）（√）。"}, {"id": 362, "type": "判断", "question": "加工精度越高的粮食，维生素的保存率越低。", "options": ["√", "×"], "answer": "√", "analysis": "粮食维生素（尤其B族、维生素E）多集中在糊粉层和胚芽，加工精度越高去除越多，维生素保存率越低（√）。"}, {"id": 363, "type": "判断", "question": "粮油通常是粮食、油料的总称。", "options": ["√", "×"], "answer": "×", "analysis": "“粮油”通常指粮食和食用油脂的统称，并非“粮食、油料”的合称；油料是未加工的原料（×）。"}, {"id": 364, "type": "判断", "question": "原粮是指收获后尚未经过清理的粮食的统称。", "options": ["√", "×"], "answer": "×", "analysis": "原粮指收获后经过初步清理、脱粒但尚未碾磨加工的粮食，并非“尚未经过清理”（×）。"}, {"id": 365, "type": "判断", "question": "油脂是油料经过加工得到的符合一定质量标准的油脂成品。", "options": ["√", "×"], "answer": "√", "analysis": "油脂是油料经压榨或浸出等加工后符合质量标准的油脂成品（√）。"}, {"id": 366, "type": "判断", "question": "粮食中存在的糖类主要是葡萄糖。", "options": ["√", "×"], "answer": "×", "analysis": "粮食中糖类主要以淀粉（多糖）形式存在，葡萄糖等单糖含量极少（×）。"}, {"id": 367, "type": "判断", "question": "淀粉分子因结构不同而分为直链淀粉和支链淀粉。", "options": ["√", "×"], "answer": "√", "analysis": "淀粉因分子结构不同分为直链淀粉和支链淀粉，二者比例影响米饭黏性等食用品质（√）。"}, {"id": 368, "type": "判断", "question": "脂肪是粮食中最重要的储藏性多糖，是人体所需热能的主要来源。", "options": ["√", "×"], "answer": "×", "analysis": "粮食中最重要的储藏性多糖是淀粉，它是人体热能的主要来源；脂肪属储藏性物质但非多糖（×）。"}, {"id": 369, "type": "判断", "question": "蛋白质能够修补和更新机体组织。", "options": ["√", "×"], "answer": "√", "analysis": "蛋白质是构成机体组织的基本物质，并能修补、更新受损和衰老的组织（√）。"}, {"id": 370, "type": "判断", "question": "构成蛋白质的基本单位是葡萄糖。", "options": ["√", "×"], "answer": "×", "analysis": "构成蛋白质的基本单位是氨基酸，而非葡萄糖；葡萄糖是糖类的基本单位（×）。"}, {"id": 371, "type": "判断", "question": "人类必须氨基酸有赖氨酸等10种。", "options": ["√", "×"], "answer": "×", "analysis": "人体必需氨基酸成人为8种（婴儿9种），并非10种（×）。赖氨酸等是其中典型代表。"}, {"id": 372, "type": "判断", "question": "储粮霉变导致粮粒变色、变味、生霉、霉烂甚至带毒。", "options": ["√", "×"], "answer": "√", "analysis": "储粮霉变由霉菌活动引起，会造成粮粒变色、变味、生霉、霉烂，部分霉菌还产生毒素（如黄曲霉毒素）（√）。"}, {"id": 373, "type": "判断", "question": "粮食微生物旺盛的呼吸作用引起粮食发热的主要原因。", "options": ["√", "×"], "answer": "√", "analysis": "粮食微生物（尤霉菌）旺盛呼吸释放大量热量，是引起粮堆发热、霉变的主要原因（√）。"}, {"id": 374, "type": "判断", "question": "推荐性标准是指生产、交换、使用等方面，通过经济手段调节而自愿采用的一类标准。", "options": ["√", "×"], "answer": "√", "analysis": "推荐性标准由生产、交换、使用各方通过经济手段调节自愿采用，不具有强制力（√）。"}, {"id": 375, "type": "判断", "question": "政府主导制定的标准分4类，分别是强制性国家标准和推荐性国家标准、推荐性行业标准、推荐性地方标准。", "options": ["√", "×"], "answer": "√", "analysis": "政府主导制定的标准分4类：强制性国家标准、推荐性国家标准、推荐性行业标准、推荐性地方标准（√）。"}, {"id": 376, "type": "判断", "question": "内结露和外结露主要的区别是水分来源不同。", "options": ["√", "×"], "answer": "√", "analysis": "内结露是粮堆内部湿热向冷界面扩散凝结，外结露是外界湿热空气遇冷粮面凝结，主要区别确在水分来源（√）。"}, {"id": 377, "type": "判断", "question": "气湿的日变与气温日变相反，在一昼夜中日出之前气湿最低，午后2时前后达最高值。", "options": ["√", "×"], "answer": "×", "analysis": "气湿日变化与气温相反：午后2时气温最高、相对湿度最低，日出前气温最低、相对湿度最高，题干表述颠倒（×）。"}, {"id": 378, "type": "判断", "question": "立筒仓的机械化程度高于平房仓。", "options": ["√", "×"], "answer": "√", "analysis": "立筒仓（筒仓）配备提升、输送、出仓等机械化设备，机械化、自动化程度高于平房仓（√）。"}, {"id": 379, "type": "判断", "question": "浅圆仓的机械化水平低于平房仓。", "options": ["√", "×"], "answer": "×", "analysis": "浅圆仓配备中心卸粮、刮板出粮等机械，机械化水平高，高于而非低于平房仓（×）。"}, {"id": 380, "type": "判断", "question": "储粮昆虫的头式主要可分为前口式和下口式。", "options": ["√", "×"], "answer": "√", "analysis": "储粮昆虫头式主要可分为前口式（口器向前，如甲虫）和下口式（口器向下，如蛾类），为主要两类（√）。"}, {"id": 381, "type": "判断", "question": "储粮螨类的体躯一般可分为头部、胸部、腹部三部分。", "options": ["√", "×"], "answer": "×", "analysis": "储粮螨类体躯分节不明显，一般分为颚体（假头）和躯体两部分，并不像昆虫那样明显分头、胸、腹三段（×）。"}, {"id": 382, "type": "判断", "question": "储粮昆虫成虫的胸部都具有3对足。", "options": ["√", "×"], "answer": "√", "analysis": "昆虫成虫胸部均着生3对足，这是昆虫纲的重要分类特征（√）。"}, {"id": 383, "type": "判断", "question": "完全变态类昆虫具有3个不同的虫期。", "options": ["√", "×"], "answer": "×", "analysis": "完全变态类昆虫有卵、幼虫、蛹、成虫4个虫期，并非3个；3个虫期是不完全变态（×）。"}, {"id": 384, "type": "判断", "question": "鳞翅目昆虫幼虫的口器是咀嚼式口器。", "options": ["√", "×"], "answer": "√", "analysis": "鳞翅目（蛾类）幼虫口器为咀嚼式，蛀食粮粒造成危害，与成虫虹吸式口器不同（√）。"}, {"id": 385, "type": "判断", "question": "储粮昆虫中具有刺吸式口器的昆虫都是储粮害虫天敌。", "options": ["√", "×"], "answer": "√", "analysis": "储粮害虫中危害粮食者均为咀嚼式口器，具刺吸式口器的昆虫（如某些天敌）在粮仓中多属害虫天敌（√）。"}, {"id": 386, "type": "判断", "question": "储粮螨类属于节肢动物门昆虫纲。", "options": ["√", "×"], "answer": "×", "analysis": "储粮螨类属节肢动物门蛛形纲，而非昆虫纲；昆虫纲的特征是体分三段、3对足（×）。"}, {"id": 387, "type": "判断", "question": "对于防治储粮害虫，我国现行的保粮方针是“以防为主、综合防治”。", "options": ["√", "×"], "answer": "√", "analysis": "我国现行保粮方针是“以防为主，综合防治”，强调预防优先、多措并举（√）。"}, {"id": 388, "type": "判断", "question": "储粮害虫的人为传播缓慢、地域性、难以制止。", "options": ["√", "×"], "answer": "×", "analysis": "储粮害虫可随粮食调运、工具传播，人为传播快、范围广、难以制止，而非“缓慢、地域性”（×）。"}, {"id": 389, "type": "判断", "question": "稻谷可以采用日晒热入仓密闭储藏杀虫。", "options": ["√", "×"], "answer": "×", "analysis": "稻谷受热易裂腰、降低整精米率与品质，不宜采用日晒热入仓高温密闭杀虫法（×）。"}, {"id": 390, "type": "判断", "question": "敌敌畏属于常用储粮保护剂。", "options": ["√", "×"], "answer": "×", "analysis": "敌敌畏属熏蒸性、空仓与器材消毒用杀虫剂，不属于长期拌粮的储粮保护剂（×）。"}, {"id": 391, "type": "判断", "question": "使用惰性粉防治储粮害虫，没有安全间隔期的要求。", "options": ["√", "×"], "answer": "√", "analysis": "惰性粉（如硅藻土、矿物粉）靠物理磨损、吸收虫体蜡质层杀虫，无毒无化学残留，故无安全间隔期要求（√）。"}, {"id": 392, "type": "判断", "question": "用磷化铝产生磷化氢的方法，在储粮害虫防治中使用最为广泛。", "options": ["√", "×"], "answer": "√", "analysis": "用磷化铝遇潮产生磷化氢进行熏蒸，是储粮害虫防治中使用最广泛的方法（√）。"}, {"id": 393, "type": "单选", "question": "安全生产工作应当以人为本，坚持“安全第一、（ ）、综合治理”的方针。", "options": [{"key": "A", "text": "预防为主"}, {"key": "B", "text": "防治并举"}, {"key": "C", "text": "安全卫生"}, {"key": "D", "text": "防消结合"}], "answer": "A", "analysis": "《安全生产法》规定安全生产方针为“安全第一、预防为主、综合治理”（选A）。"}, {"id": 394, "type": "单选", "question": "劳动保护的任务。从总体上讲就是解决（ ）之间的矛盾。", "options": [{"key": "A", "text": "企业与员工"}, {"key": "B", "text": "领导与下属"}, {"key": "C", "text": "安全与生产"}, {"key": "D", "text": "生产与效益"}], "answer": "C", "analysis": "劳动保护的任务从总体上就是解决安全与生产之间的矛盾，做到安全生产（选C）。"}, {"id": 395, "type": "单选", "question": "企业安全防火应认真贯彻“预防为主、（ ）”方针。", "options": [{"key": "A", "text": "以消为辅"}, {"key": "B", "text": "防消并举"}, {"key": "C", "text": "安全卫生"}, {"key": "D", "text": "防消结合"}], "answer": "D", "analysis": "企业安全防火贯彻“预防为主，防消结合”的方针（选D），把预防火灾放在首位同时做好扑救准备。"}, {"id": 396, "type": "单选", "question": "密封粮仓空间温度≥（ ）℃时，应采取符合LS/T1202-2002《储粮机械通风技术规程》的通风措施，消除危险源后方能进入粮仓。", "options": [{"key": "A", "text": "26"}, {"key": "B", "text": "30"}, {"key": "C", "text": "36"}, {"key": "D", "text": "40"}], "answer": "C", "analysis": "按LS/T1202-2002，密封粮仓空间温度≥36℃时存在缺氧、有毒气体积聚等危险，须先通风消除危险源方可入仓（选C）。"}, {"id": 397, "type": "单选", "question": "密封粮仓人员入仓作业时，作业人员应至少（ ）人同行。", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "answer": "A", "analysis": "密封粮仓人员入仓作业须至少2人同行，以便相互监护、遇险及时施救（选A）。"}, {"id": 398, "type": "单选", "question": "实施粮食熏蒸，仓储部门负责人应安排不少于（ ）名作业人员同时作业。", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": "B", "analysis": "实施粮食熏蒸时，仓储部门负责人应安排不少于2名作业人员同时作业，落实监护与协作（选B）。"}, {"id": 399, "type": "单选", "question": "磷化氢熏蒸杀虫时，每人每次不应超过（ ）min。", "options": [{"key": "A", "text": "10"}, {"key": "B", "text": "20"}, {"key": "C", "text": "30"}, {"key": "D", "text": "40"}], "answer": "C", "analysis": "磷化氢剧毒，熏蒸作业每人每次接触不应超过30min，并需轮换、监护以防中毒（选C）。"}, {"id": 400, "type": "单选", "question": "在磷化氢熏蒸的分药、投药、熏蒸、散气和药渣处理过程中，作业人员必须佩戴（ ），穿工作服，戴橡胶手套。", "options": [{"key": "A", "text": "防尘口罩"}, {"key": "B", "text": "防毒口罩"}, {"key": "C", "text": "空气呼吸器"}, {"key": "D", "text": "防毒面具"}], "answer": "C", "analysis": "磷化氢熏蒸的分药、投药、散气、药渣处理全过程，作业人员必须佩戴空气呼吸器（自给式），普通防毒口罩不足以防毒（选C）。"}, {"id": 401, "type": "单选", "question": "使用磷化氢空仓杀虫、粮食熏蒸及散气期间，应在距离粮仓至少（ ）m处设置安全警示标识和警戒线。", "options": [{"key": "A", "text": "10"}, {"key": "B", "text": "20"}, {"key": "C", "text": "30"}, {"key": "D", "text": "40"}], "answer": "B", "analysis": "磷化氢（PH₃）为剧毒气体，熏蒸及散气期间须在粮仓外设置安全警示标识和警戒线，防止人员误入中毒。按照熏蒸作业安全要求，警戒区一般设在距离粮仓 20 m 以外，故应选 20 m。"}, {"id": 402, "type": "单选", "question": "粮油仓储管理过程中主要职业危害不包括（ ）。", "options": [{"key": "A", "text": "粉尘危害"}, {"key": "B", "text": "毒物危害"}, {"key": "C", "text": "噪声危害"}, {"key": "D", "text": "辐射危害"}], "answer": "D", "analysis": "粮油仓储中的主要职业危害来自粉尘（粮尘）、毒物（磷化氢等熏蒸剂）和噪声（机械设备）。辐射危害并非粮油仓储作业的典型职业危害，因此不属于其中。"}, {"id": 403, "type": "单选", "question": "（ ）是指围绕着人群的空间及其中可以影响人类生产、生活和发展的各种自然因素、社会因素的总体。", "options": [{"key": "A", "text": "自然"}, {"key": "B", "text": "社会"}, {"key": "C", "text": "环境"}, {"key": "D", "text": "职业"}], "answer": "C", "analysis": "环境是指围绕着人群的空间及其中可以影响人类生产、生活和发展的各种自然因素、社会因素的总体。这是《环境保护法》及环境科学中对‘环境’的基本定义。"}, {"id": 404, "type": "单选", "question": "不利于环境保护的“四废”是指（ ）。", "options": [{"key": "A", "text": "废气、废物、废水、废液"}, {"key": "B", "text": "废气、废渣、废物、废液"}, {"key": "C", "text": "废气、废渣、废水、废物"}, {"key": "D", "text": "废气、废渣、废水、废液"}], "answer": "D", "analysis": "环境保护中常说的‘四废’指废气、废渣、废水、废液，均为工农业生产中产生的主要污染物。选项中废气、废渣、废水、废液的组合最规范。"}, {"id": 405, "type": "单选", "question": "违反《环境保护法》规定，构成犯罪的，依法（ ）。", "options": [{"key": "A", "text": "追究刑事责任"}, {"key": "B", "text": "追究民事责任"}, {"key": "C", "text": "做出行政处罚"}, {"key": "D", "text": "进行党纪处罚"}], "answer": "A", "analysis": "《环境保护法》规定，违法行为造成环境污染、构成犯罪的，应依法追究刑事责任，体现了环境保护的强制性法律后果。行政处罚和民事责任不足以惩处犯罪行为。"}, {"id": 406, "type": "单选", "question": "安全生产就是保护劳动者在生产、经营活动中的（ ）。", "options": [{"key": "A", "text": "人身安全、健康和企业安全"}, {"key": "B", "text": "人身安全、健康和财产安全"}, {"key": "C", "text": "人身安全、健康和设备安全"}, {"key": "D", "text": "人身安全、健康和交通安全"}], "answer": "B", "analysis": "安全生产的核心是保护劳动者在生产、经营活动中的人身安全、健康和财产安全，既包括人，也包括与之相关的财产。‘财产安全’涵盖了企业物资与设备损失防护，表述最完整。"}, {"id": 407, "type": "单选", "question": "为消除不安全、不卫生因素所采取的组织措施、技术措施均属（ ）范畴。", "options": [{"key": "A", "text": "劳动保护"}, {"key": "B", "text": "综合治理"}, {"key": "C", "text": "环境保护"}, {"key": "D", "text": "应急救援"}], "answer": "A", "analysis": "劳动保护是指为消除不安全、不卫生因素而采取的组织措施和技术措施的总和，目的是保障劳动者安全健康。综合治理、环境保护、应急救援均不等同于这一概念。"}, {"id": 408, "type": "单选", "question": "安全生产责任中，（ ）是第一责任人，对本单位安全生产负全面责任。", "options": [{"key": "A", "text": "（粮油）仓储管理员"}, {"key": "B", "text": "仓储科长"}, {"key": "C", "text": "单位主要负责人"}, {"key": "D", "text": "中层领导"}], "answer": "C", "analysis": "安全生产责任制中，单位主要负责人是安全生产第一责任人，对本单位安全生产负全面责任。仓储管理员、科长、中层领导在各自职责范围内负责，但第一责任人是主要负责人。"}, {"id": 409, "type": "判断", "question": "安全生产的工作方针是“以防为主、防消结合”。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。我国安全生产方针是‘安全第一、预防为主、综合治理’；而‘预防为主、防消结合’是消防工作的方针。题目把消防方针张冠李戴到安全生产上，故判×。"}, {"id": 410, "type": "判断", "question": "清理平房仓时，作业人员应开启仓房门窗或排风扇。", "options": ["√", "×"], "answer": "√", "analysis": "清理平房仓时应开启仓房门窗或排风扇通风，以降低仓内粉尘和可能残留的磷化氢等有毒气体浓度，保障作业人员呼吸安全。故该说法正确。"}, {"id": 411, "type": "判断", "question": "入仓粮油要按照规定分仓存放，为了多装粮，堆粮高度可以适当超过安全存粮线。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。入仓粮油须按规定分仓、分品种存放，堆粮高度不得超过安全存粮线，否则会因粮油巨大侧压力损坏仓墙、甚至发生垮仓事故。‘多装粮’不能突破安全存粮线。"}, {"id": 412, "type": "判断", "question": "若出现粮油挂壁、结拱时宜站在离挂壁粮油足够远的安全位置用长竹竿清除粮油。清除时应从底部开始，自下而上。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。清除挂壁、结拱粮油时应站在安全距离外，用长竹竿从上部（自上而下）逐步清除，使物料顺势下落；若从底部自下而上掏挖，上部粮堆易突然坍塌伤人。"}, {"id": 413, "type": "单选", "question": "粮食经营行为是指从事粮油收购、销售、（ ）、运输、加工、进出口等活动的经营行为。", "options": [{"key": "A", "text": "储存"}, {"key": "B", "text": "生产"}, {"key": "C", "text": "种植"}, {"key": "D", "text": "收获"}], "answer": "A", "analysis": "《粮食流通管理条例》中粮食经营行为包括粮油收购、销售、储存、运输、加工、进出口等活动。储存是粮食流通的重要环节，故应选‘储存’。"}, {"id": 414, "type": "单选", "question": "下列活动中，不属于粮食经营行为的是（ ）。", "options": [{"key": "A", "text": "粮油储存"}, {"key": "B", "text": "粮油生产"}, {"key": "C", "text": "粮油加工"}, {"key": "D", "text": "粮油运输"}], "answer": "B", "analysis": "粮油生产（种植）属于农业生产环节，不属于《粮食流通管理条例》所指的粮食经营行为。储存、加工、运输均为典型的粮食经营行为。"}, {"id": 415, "type": "单选", "question": "《中央储备粮管理条例》规定，确保中央储备粮（ ），确保中央储备粮储得进、管得好、调得动、用得上。", "options": [{"key": "A", "text": "数量真实、质量良好和储存安全"}, {"key": "B", "text": "数量真实、储存安全和管理到位"}, {"key": "C", "text": "质量良好、储存安全和管理到位"}, {"key": "D", "text": "数量真实、管理到位和责任严格"}], "answer": "A", "analysis": "《中央储备粮管理条例》明确：确保中央储备粮数量真实、质量良好和储存安全，做到储得进、管得好、调得动、用得上。三者并列是条例对中央储备粮管理的核心要求。"}, {"id": 416, "type": "单选", "question": "《中央储备粮管理条例》规定，中央储备粮的管理应当（ ）。", "options": [{"key": "A", "text": "严格管理、严格责任、严格要求"}, {"key": "B", "text": "严格要求、严格管理、严格纪律"}, {"key": "C", "text": "严格制度、严格要求、严格责任"}, {"key": "D", "text": "严格制度、严格管理、严格责任"}], "answer": "D", "analysis": "《中央储备粮管理条例》规定，中央储备粮的管理应当‘严格制度、严格管理、严格责任’（简称‘三严格’）。这一表述是条例原文，区别于一般的‘严格要求’。"}, {"id": 417, "type": "单选", "question": "粮油仓储单位的所管仓廒（罐）粮油储存安全的直接责任人是（ ）。", "options": [{"key": "A", "text": "副主任"}, {"key": "B", "text": "仓储科长"}, {"key": "C", "text": "保管组组长"}, {"key": "D", "text": "粮油保管员"}], "answer": "D", "analysis": "粮油仓储单位对所管仓廒（罐）粮油储存安全，直接责任人是具体的粮油保管员，由其负责日常粮情检查与保管作业。副主任、科长等承担管理责任而非直接责任人。"}, {"id": 418, "type": "单选", "question": "（ ）明确规定了促进就业、劳动合同和集体合同、工作时间和休息休假、工资、劳动安全卫生、女职工和未成年工特殊保障、职业培训、社会保险和福利、劳动争议、监督检查、法律责任等方面内容。", "options": [{"key": "A", "text": "《劳动法》"}, {"key": "B", "text": "《合同法》"}, {"key": "C", "text": "《安全生产法》"}, {"key": "D", "text": "《食品安全法》"}], "answer": "A", "analysis": "《劳动法》系统规定了促进就业、劳动合同、工作时间与休息休假、工资、劳动安全卫生、社会保险等劳动关系各方面内容。合同法、安全生产法、食品安全法各有专门调整范围。"}, {"id": 419, "type": "判断", "question": "中央储备粮的管理费用补贴实行定额包干，由国务院财政部门拨付给中央储备粮各直属库。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。中央储备粮管理费用补贴实行定额包干，由国务院财政部门拨付给中国储备粮管理总公司，再由总公司逐级下拨，并非直接拨付给各直属库。"}, {"id": 420, "type": "判断", "question": "《劳动法》规定劳动者连续工作3个月以上的，享受带薪年休假。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。《劳动法》规定劳动者连续工作 1 年以上才享受带薪年休假，而非连续工作 3 个月。3 个月远未达到享受带薪年休假的工龄条件。"}, {"id": 421, "type": "单选", "question": "我国消防工作贯彻“预防为主、（ ）”的工作方针。", "options": [{"key": "A", "text": "综合防治"}, {"key": "B", "text": "综合治理"}, {"key": "C", "text": "以消为辅"}, {"key": "D", "text": "防消结合"}], "answer": "D", "analysis": "我国消防工作贯彻‘预防为主、防消结合’的方针，强调事先防范与发生火灾时及时扑救相结合。这是《消防法》明确的工作方针。"}, {"id": 422, "type": "单选", "question": "用于扑灭粮食、油脂、磷化氢、仓房、电气设备火灾均可使用的灭火器是（ ）。", "options": [{"key": "A", "text": "水型灭火器"}, {"key": "B", "text": "泡沫灭火器"}, {"key": "C", "text": "磷酸铵盐干粉灭火器"}, {"key": "D", "text": "二氧化碳灭火器"}], "answer": "C", "analysis": "磷酸铵盐干粉灭火器（ABC 干粉）适用范围广，可扑救 A 类固体、B 类液体、C 类气体及 E 类电气火灾，粮食、油脂、磷化氢、仓房、电气设备均可使用。水、泡沫不宜灭油电气，二氧化碳对 A 类固体效果差。"}, {"id": 423, "type": "单选", "question": "粮食着火属于（ ）火灾。", "options": [{"key": "A", "text": "A类"}, {"key": "B", "text": "B类"}, {"key": "C", "text": "C类"}, {"key": "D", "text": "D类"}], "answer": "A", "analysis": "火灾按燃烧物分为 A、B、C、D、E 类，其中 A 类指固体物质火灾。粮食属于固体物质，故粮食着火为 A 类火灾。"}, {"id": 424, "type": "单选", "question": "磷化氢起火属于（ ）火灾。", "options": [{"key": "A", "text": "A类"}, {"key": "B", "text": "B类"}, {"key": "C", "text": "C类"}, {"key": "D", "text": "D类"}], "answer": "C", "analysis": "C 类火灾指气体火灾。磷化氢（PH₃）为可燃气体，其燃烧属于 C 类气体火灾，扑救须选用干粉、二氧化碳等灭火器。"}, {"id": 425, "type": "单选", "question": "准备的简易货位应结合实际合理规划，确保粮油到来之时能放得下，下面叙述中关于粮油的合理堆放不正确的是（ ）", "options": [{"key": "A", "text": "粮油就近堆放"}, {"key": "B", "text": "能并装的不分散"}, {"key": "C", "text": "能散装的不包装"}, {"key": "D", "text": "尽可能堆大 、堆高"}], "answer": "A", "analysis": "合理堆放应坚持‘能并装的不分散、能散装的不包装、尽可能堆大堆高’以节约仓容并保证安全；而‘粮油就近堆放’并非科学堆放原则，易忽视安全间距与规范布点，故为不正确项。"}, {"id": 426, "type": "单选", "question": "粮油保管员根据（ ）计划简易货位的摆放面积及高度。", "options": [{"key": "A", "text": "粮油体积"}, {"key": "B", "text": "粮油数量"}, {"key": "C", "text": "粮油容重"}, {"key": "D", "text": "粮油等级"}], "answer": "A", "analysis": "简易货位的摆放面积与高度由粮油体积决定（体积=面积×堆高）。保管员根据到库粮油的体积来规划货位占地与堆高，容重、等级等是用于推算体积或质量的辅助参数。"}, {"id": 427, "type": "单选", "question": "粮油入库之前应申请专业技术人员校验计量及检测设备，确保其计量准确、运行良好，防止偏差，下列叙述不正确的是（ ）。", "options": [{"key": "A", "text": "校验电子容重器"}, {"key": "B", "text": "检测带式输送机"}, {"key": "C", "text": "校验快速水分测定仪"}, {"key": "D", "text": "校验电子汽车衡"}], "answer": "B", "analysis": "入库前须校验的是计量及检测设备，如电子容重器、快速水分测定仪、电子汽车衡等。带式输送机属输送作业设备，不属于计量检测设备，故‘检测带式输送机’不正确。"}, {"id": 428, "type": "单选", "question": "仓内设置隔热吊顶，吊顶与仓盖的间距应在（ ）以上。", "options": [{"key": "A", "text": "0.2m"}, {"key": "B", "text": "0.3m"}, {"key": "C", "text": "0.4m"}, {"key": "D", "text": "0.5m"}], "answer": "B", "analysis": "仓内设置隔热吊顶时，吊顶与仓盖之间应留不小于 0.3 m 的空气隔热层，以阻断仓顶传入的热量、降低粮温。故间距应在 0.3 m 以上。"}, {"id": 429, "type": "单选", "question": "下面关于油罐的呼吸阀静态储油时保持闭合状态叙述不正确的是（ ）。", "options": [{"key": "A", "text": "可以減少油品的蒸发损耗"}, {"key": "B", "text": "可以自动通气调节平衡油罐内外压力"}, {"key": "C", "text": "呼吸阀处于闭合状态对油罐能起到安全的作用"}, {"key": "D", "text": "容易产生负压吸瘪油罐"}], "answer": "D", "analysis": "呼吸阀在静态储油时闭合，可减少油品蒸发损耗、自动调节平衡罐内外压力并起安全作用。‘容易产生负压吸瘪油罐’是阀门失效或故障的后果，并非闭合状态的正常作用，故该项叙述不正确。"}, {"id": 430, "type": "单选", "question": "下列叙述中，哪项是粮油在出入库作业时，油罐的呼吸阀处于闭合状态对油罐产生的影响（ ）。", "options": [{"key": "A", "text": "可以減少油品的蒸发损耗"}, {"key": "B", "text": "可以自动通气调节平衡油罐内外压力"}, {"key": "C", "text": "呼吸阀处于闭合状态对油罐能起到安全的作用"}, {"key": "D", "text": "入油压力过大时可能撑爆油罐或者顶飞罐顶盖"}], "answer": "D", "analysis": "出入库作业时油罐呼吸阀若处于闭合状态，进油时罐内气体无法排出，当入油压力过大时可能撑爆油罐或顶飞罐顶盖，这是闭合状态在作业期间的主要危害。"}, {"id": 431, "type": "单选", "question": "下面不属于仓内通风系统安装要求是（ ）。", "options": [{"key": "A", "text": "无变形"}, {"key": "B", "text": "无移位"}, {"key": "C", "text": "无漏粮"}, {"key": "D", "text": "不返工"}], "answer": "D", "analysis": "仓内通风系统安装质量要求为无变形、无移位、无漏粮，保证通风均匀且不与粮堆串气。‘不返工’是施工管理要求，不属于通风系统安装质量的技术指标。"}, {"id": 432, "type": "单选", "question": "下面不属于A类火灾现场选用的灭火器（ ）。", "options": [{"key": "A", "text": "碳酸氢钠干粉灭火器"}, {"key": "B", "text": "磷酸铵盐干粉灭火器"}, {"key": "C", "text": "泡沫灭火器"}, {"key": "D", "text": "卤代烷灭火器"}], "answer": "A", "analysis": "A 类为固体物质火灾。碳酸氢钠干粉（BC 干粉）仅适用于 B、C、E 类，不能有效扑救 A 类固体火灾；磷酸铵盐干粉（ABC）、泡沫、卤代烷均可用于 A 类。故不属于 A 类选用的是碳酸氢钠干粉。"}, {"id": 433, "type": "单选", "question": "下面不属于B类火灾现场选用的灭火器（ ）。", "options": [{"key": "A", "text": "泡沫灭火器"}, {"key": "B", "text": "磷酸铵盐干粉灭火器"}, {"key": "C", "text": "二氧化碳灭火器"}, {"key": "D", "text": "碳酸氢钠干粉灭火器"}], "answer": "A", "analysis": "B 类火灾为液体或可熔化固体火灾，规范选用磷酸铵盐干粉、二氧化碳、碳酸氢钠干粉等灭火器。泡沫灭火器主要用于 A 类固体及部分非水溶性油类，在此题设定中不列为 B 类火灾的规范选用项。"}, {"id": 434, "type": "单选", "question": "下面不属于消防检查分类的是（ ）。", "options": [{"key": "A", "text": "一般检查"}, {"key": "B", "text": "夜间检查"}, {"key": "C", "text": "常规检查"}, {"key": "D", "text": "定期检查"}], "answer": "C", "analysis": "消防检查按组织形式分为一般检查、夜间检查、定期检查等。‘常规检查’并非消防检查的标准分类名称，故不属于。"}, {"id": 435, "type": "单选", "question": "关于干粉灭火器的使用，下面顺序正确的是（ ）。（1）将灭火器颠倒摇动几次，拔去保险插销（2）检查干粉灭火器保质期和罐内气压（3）站立上风方向，展开喷管（4）按下压把，喷嘴对准火焰根部，由近及远左右晃动扫喷（5）灭火后，松开压把，停止喷粉", "options": [{"key": "A", "text": "（3）（2）（1）（4）（5）"}, {"key": "B", "text": "（2）（1）（3）（4）（5）"}, {"key": "C", "text": "（2）（3）（4）（1）（5）"}, {"key": "D", "text": "（4）（5）（2）（1）（3）"}], "answer": "B", "analysis": "干粉灭火器正确使用顺序为：先检查保质期与罐内气压（2），再颠倒摇动、拔保险销（1），站上风展开喷管（3），按下压把对准火焰根部扫喷（4），火灭后松手停喷（5），即（2）（1）（3）（4）（5）。"}, {"id": 436, "type": "单选", "question": "手提式灭火器宜设置在灭火器箱内或挂钩、托架上，其顶部离地面高度不应（ ）1.50m。", "options": [{"key": "A", "text": "大于"}, {"key": "B", "text": "小于"}, {"key": "C", "text": "不大于"}, {"key": "D", "text": "不小于"}], "answer": "A", "analysis": "《建筑灭火器配置设计规范》规定，手提式灭火器宜设在灭火器箱内或挂钩、托架上，其顶部离地面高度不应大于 1.50 m，便于取用且避免高处坠落伤人。"}, {"id": 437, "type": "单选", "question": "手提式灭火器底部离地面高度不宜（ ）0.08m。", "options": [{"key": "A", "text": "不小于"}, {"key": "B", "text": "不大于"}, {"key": "C", "text": "大于"}, {"key": "D", "text": "小于"}], "answer": "D", "analysis": "同一规范要求，手提式灭火器底部离地面高度不宜小于 0.08 m，防止受潮、锈蚀并便于清扫，故应为‘小于’。"}, {"id": 438, "type": "单选", "question": "火警报警电话（ ）。", "options": [{"key": "A", "text": "110"}, {"key": "B", "text": "119"}, {"key": "C", "text": "120"}, {"key": "D", "text": "109"}], "answer": "B", "analysis": "我国火警报警电话为 119，110 为报警服务台、120 为急救、109 非火警。粮库发生火灾应立即拨打 119。"}, {"id": 439, "type": "单选", "question": "仓库建设选址应选在地势（ ）、干燥的地方。", "options": [{"key": "A", "text": "高"}, {"key": "B", "text": "平坦"}, {"key": "C", "text": "低"}, {"key": "D", "text": "缓平"}], "answer": "A", "analysis": "粮库（仓库）建设选址应选在地势高、干燥、排水良好的地方，以利防潮、防涝并减少粮食吸湿霉变风险。低洼地易积水返潮，不宜建库。"}, {"id": 440, "type": "单选", "question": "清理仓房、货场及作业区地坪遗撒粮粒、积尘积灰，达到“（ ）”。", "options": [{"key": "A", "text": "两不留"}, {"key": "B", "text": "三不留"}, {"key": "C", "text": "四不留"}, {"key": "D", "text": "五不留"}], "answer": "B", "analysis": "仓房、货场及作业区清理要求达到‘三不留’，即不留粮粒、不留积尘、不留积灰（或指不留粮、不留尘、不留杂物），防止虫霉滋生与火灾隐患。"}, {"id": 441, "type": "单选", "question": "在清理过程中出现的挂壁现象，主要是由于粮食的（ ），霉菌生长发育过程中产生的大量的菌丝形成的结块。", "options": [{"key": "A", "text": "杂质过多"}, {"key": "B", "text": "水分过高"}, {"key": "C", "text": "粉尘过大"}, {"key": "D", "text": "品质差"}], "answer": "B", "analysis": "仓壁挂壁结块多因粮食水分过高，霉菌在适宜温湿下大量生长、其菌丝将粮粒粘结成块并贴附仓壁。水分过高是挂壁现象的主要诱因，故应选‘水分过高’。"}, {"id": 442, "type": "单选", "question": "根据粮食品种、质量等情况，按粮食的（ ）估算待存粮食的体积。", "options": [{"key": "A", "text": "容重"}, {"key": "B", "text": "质量"}, {"key": "C", "text": "水分"}, {"key": "D", "text": "等级"}], "answer": "A", "analysis": "估算待存粮食体积需依据容重（单位体积重量，kg/m³）：体积≈质量÷容重。按粮食品种、质量结合容重即可算出所需货位体积，故应选‘容重’。"}, {"id": 443, "type": "单选", "question": "仓盖设置应有（ ）3%的坡度，仓盖如采用集中排水，檐槽的下水管应设置在仓墙外面。", "options": [{"key": "A", "text": "不大于"}, {"key": "B", "text": "不小于"}, {"key": "C", "text": "大于"}, {"key": "D", "text": "小于"}], "answer": "C", "analysis": "仓盖应设置不小于 3% 的排水坡度（题干‘大于 3%’），保证雨水分流顺畅、不积水渗漏；檐槽下水管设在仓墙外以避免水沿墙内渗。"}, {"id": 444, "type": "单选", "question": "仓房的仓墙外表面应为（ ）。", "options": [{"key": "A", "text": "浅色"}, {"key": "B", "text": "深色"}, {"key": "C", "text": "红色"}, {"key": "D", "text": "绿色"}], "answer": "A", "analysis": "仓墙外表面应为浅色，浅色对太阳辐射反射率高、吸收热量少，可降低仓温与粮温，利于储粮隔热保冷。深色会加剧吸热升温。"}, {"id": 445, "type": "判断", "question": "水型灭火器可以用于扑灭粮食、油脂、仓房的火灾。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。水型灭火器不能用于油脂（B 类）火灾，油比水轻会浮于水面继续燃烧并流淌扩大火势，也不适用于电气设备火灾。粮食可用水但油脂、仓房（含电）不宜，故笼统说‘可扑灭’是错误的。"}, {"id": 446, "type": "判断", "question": "对于清理过的仓房，在分期入粮时，下次装粮前无需再进行仓房清理。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。每次装粮前都应对仓房进行清理、消毒，即使前期已清理且分期入粮，间隔期间仍可能有虫、霉、尘沉积，下次装粮前必须重新清理。"}, {"id": 447, "type": "判断", "question": "对于高大平房仓的仓顶清理，可以在装粮后借助粮堆的高度进行清理。", "options": ["√", "×"], "answer": "√", "analysis": "该说法正确。高大平房仓装粮后粮堆顶面接近仓顶，可借助粮堆高度作为作业平台清理仓顶，既安全又便于操作，是实际常用的做法。"}, {"id": 448, "type": "判断", "question": "在灰尘和粉尘较多的环境中作业时，必须采取防护措施，避免灰尘和粉尘对呼吸系统造成危害。", "options": ["√", "×"], "answer": "√", "analysis": "该说法正确。粮尘（尤其含有机粉尘）长期吸入可致尘肺等呼吸系统疾病，粉尘多环境必须戴口罩等防护，符合劳动保护与职业健康要求。"}, {"id": 449, "type": "判断", "question": "由于清理立筒仓和浅圆仓的上下通廊沉积的粉尘时易引起粉尘爆炸，所以在清理过程中，必须保证无静电火花发生。", "options": ["√", "×"], "answer": "√", "analysis": "该说法正确。立筒仓、浅圆仓通廊沉积的粮食粉尘达到一定浓度遇点火源会爆炸，静电火花是重要引火源，清理时必须消除静电、防爆电器作业。"}, {"id": 450, "type": "判断", "question": "考虑到仓容的利用率，对质量好、储藏时间短、冬季入库的原粮，堆高越高越好。", "options": ["√", "×"], "answer": "×", "analysis": "该说法错误。堆高受仓房结构强度、安全存粮线和粮油侧压力限制，并非越高越好；超高会压坏仓底、仓墙或导致结拱、发热，须控制在安全堆高内。"}, {"id": 451, "type": "判断", "question": "在清理立筒仓内的残留粮食和灰尘时应注意安全，筒底有进人孔的应打开底部的孔盖后进入。", "options": ["√", "×"], "answer": "√", "analysis": "该说法正确。清理立筒仓残留粮与积尘时，应先打开筒底进人孔通风、检测气体合格并确认安全后再进入，防止缺氧、中毒或窒息，属有限空间作业基本安全要求。"}, {"id": 452, "type": "判断", "question": "油罐呼吸阀在出入库作业时检查是否处于开启状态，静态储油期间是否处于闭合状态。", "options": ["√", "×"], "answer": "√", "analysis": "该说法正确。油罐呼吸阀在出入库（动态）作业时须开启以平衡呼吸压力、防止憋罐或吸瘪；静态储油时保持闭合以减少蒸发损耗并起安全作用，符合油罐安全管理规定。"}, {"id": 453, "type": "单选", "question": "玉米胚中含有（ ），这点与其他谷类粮食明显不同。", "options": [{"key": "A", "text": "淀粉"}, {"key": "B", "text": "脂肪"}, {"key": "C", "text": "蛋白质"}, {"key": "D", "text": "矿物质"}], "answer": "A", "analysis": "玉米的胚在禾谷类粮食中体积最大，胚部贮藏物质以淀粉为主（同时富含脂肪），这也使其区别于小麦、稻谷等胚很小的粮食，故题干所指‘玉米胚中含有（淀粉）’为本题设定答案。需注意玉米胚脂肪含量高也是其重要特点，以官方教材为准。"}, {"id": 454, "type": "单选", "question": "下面不属于玉米类别判定结果的是（ ）。", "options": [{"key": "A", "text": "黄玉米"}, {"key": "B", "text": "白玉米"}, {"key": "C", "text": "红玉米"}, {"key": "D", "text": "混合玉米"}], "answer": "C", "analysis": "玉米按种皮颜色分为黄玉米、白玉米、混合玉米（及糯玉米等），‘红玉米’不是玉米类别的规范判定结果，故应选‘红玉米’。"}, {"id": 455, "type": "单选", "question": "平时食用的大米的成分是（ ）。", "options": [{"key": "A", "text": "胚乳"}, {"key": "B", "text": "皮层"}, {"key": "C", "text": "胚"}, {"key": "D", "text": "子叶"}], "answer": "A", "analysis": "稻谷加工除去皮层、胚后，食用的精米主要部分为胚乳。胚乳是籽粒贮藏淀粉等养分的主要组织，故大米成分是胚乳。"}, {"id": 456, "type": "单选", "question": "下列不属于大豆结构的是（ ）。", "options": [{"key": "A", "text": "种皮"}, {"key": "B", "text": "胚"}, {"key": "C", "text": "胚乳"}, {"key": "D", "text": "子叶"}], "answer": "C", "analysis": "大豆属双子叶无胚乳种子，由种皮和胚（子叶、胚芽、胚轴、胚根）组成，不具胚乳。胚乳是小麦、玉米等禾谷类（单子叶）种子的结构，故‘胚乳’不属于大豆结构。"}, {"id": 457, "type": "单选", "question": "下列谷类粮食中胚最大的是（ ）。", "options": [{"key": "A", "text": "小麦"}, {"key": "B", "text": "稻谷"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "大豆"}], "answer": "C", "analysis": "禾谷类粮食中玉米的胚最大（约占籽粒重 8%–15%），小麦、稻谷胚很小，大豆为双子叶植物胚虽大但属不同类。故胚最大的是玉米。"}, {"id": 458, "type": "单选", "question": "粮油籽粒由三部分组成，生理活动最强的部分是（ ）。", "options": [{"key": "A", "text": "皮层"}, {"key": "B", "text": "胚乳"}, {"key": "C", "text": "胚"}, {"key": "D", "text": "表层"}], "answer": "C", "analysis": "粮油籽粒由皮层、胚乳、胚三部分组成，其中胚是生命活动最旺盛的部分，进行呼吸、发芽等生理活动最强。皮层保护、胚乳贮藏养分，生理活性较低。"}, {"id": 459, "type": "单选", "question": "下列粮食作物中具有胚乳的是（ ）。", "options": [{"key": "A", "text": "花生"}, {"key": "B", "text": "玉米"}, {"key": "C", "text": "大豆"}, {"key": "D", "text": "油菜籽"}], "answer": "B", "analysis": "花生、大豆、油菜籽均为双子叶无胚乳种子；玉米是禾谷类单子叶种子，具有发达的胚乳。故具有胚乳的是玉米。"}, {"id": 460, "type": "单选", "question": "下面哪项不属于杂质含量的判定方法（ ）。", "options": [{"key": "A", "text": "视觉检验法"}, {"key": "B", "text": "选筛辅助检验法"}, {"key": "C", "text": "瓷盘辅助检验法"}, {"key": "D", "text": "触觉检验法"}], "answer": "D", "analysis": "杂质含量判定常用视觉检验法、选筛辅助检验法、瓷盘辅助检验法等。触觉检验法主要用于判断水分（手感潮干），不属于杂质含量判定方法，故应选触觉检验法。"}, {"id": 461, "type": "单选", "question": "下面关于小颗粒油料水分含量判定方法错误的是（ ）。", "options": [{"key": "A", "text": "手捏法"}, {"key": "B", "text": "耳听法"}, {"key": "C", "text": "擦压法"}, {"key": "D", "text": "视觉检验法"}], "answer": "D", "analysis": "小颗粒油料（如芝麻、油菜籽）水分判定常用手捏法、耳听法、擦压法等感官方法。视觉检验法对小颗粒油料水分判断不敏感，不属其常规判定方法，故应选视觉检验法。"}, {"id": 462, "type": "单选", "question": "选筛辅助法检验稻谷杂质所选用的筛层为（ ）。", "options": [{"key": "A", "text": "1.2mm"}, {"key": "B", "text": "1.5mm"}, {"key": "C", "text": "2.0mm"}, {"key": "D", "text": "2.5mm"}], "answer": "C", "analysis": "选筛辅助法检验稻谷杂质时，按标准采用 2.0 mm 圆孔筛（上层筛除大杂），筛下物再经小孔筛分离小杂。故所用筛层为 2.0 mm。"}, {"id": 463, "type": "单选", "question": "稻谷在手木砻内碾出糙米，吹去谷壳后，下面可以说明稻谷水分较低的是（ ）。", "options": [{"key": "A", "text": "出糙不匀"}, {"key": "B", "text": "糙米表面毛糙"}, {"key": "C", "text": "糙米饱满、完整"}, {"key": "D", "text": "碎粒多"}], "answer": "C", "analysis": "水分较低的稻谷结构紧实，手木砻碾出糙米后糙米饱满、完整；水分高则碾磨易碎、出糙不匀、表面毛糙。故‘糙米饱满、完整’说明水分较低。"}, {"id": 464, "type": "单选", "question": "影响杂质含量的主要因素（ ）。", "options": [{"key": "A", "text": "异种粮粒"}, {"key": "B", "text": "泥沙"}, {"key": "C", "text": "根、茎、叶的残体"}, {"key": "D", "text": "油料种子、杂草种子"}], "answer": "B", "analysis": "粮油杂质中泥沙等无机杂质来源最广、占比通常最大，是直接影响杂质含量判定的主要因素；异种粮粒、茎叶残体、杂草种子等也影响但非最主要。故应选泥沙。"}, {"id": 465, "type": "单选", "question": "下面哪项不属于水分含量的判定方法（ ）。", "options": [{"key": "A", "text": "触觉检验法"}, {"key": "B", "text": "视觉检验法"}, {"key": "C", "text": "瓷盘辅助检验法"}, {"key": "D", "text": "齿觉检验法"}], "answer": "C", "analysis": "水分含量判定常用触觉（手摸）、视觉、齿觉（牙咬听声）及手捏、耳听等感官方法。瓷盘辅助检验法主要用于杂质检验（摊样挑拣），不属于水分判定方法，故应选瓷盘辅助检验法。"}, {"id": 466, "type": "单选", "question": "选筛辅助法检验小麦杂质所选用的筛层为（ ）。", "options": [{"key": "A", "text": "1.2mm"}, {"key": "B", "text": "1.5mm"}, {"key": "C", "text": "2.0mm"}, {"key": "D", "text": "2.5mm"}], "answer": "B", "analysis": "选筛辅助法检验小麦杂质，按标准采用 1.5 mm 圆孔筛（上层筛除大杂），配合小孔筛分离小杂。故所用筛层为 1.5 mm。"}, {"id": 467, "type": "单选", "question": "对气味不易判定的样品，可将其放入广口瓶中，塞上瓶塞，在（ ）的条件下进行温水浴，开盖嗅辩其气味是否正常。", "options": [{"key": "A", "text": "60-70℃"}, {"key": "B", "text": "30-50℃"}, {"key": "C", "text": "40-50℃"}, {"key": "D", "text": "50-70℃"}], "answer": "A", "analysis": "对气味不易判定的样品，放入广口瓶塞紧后于 60–70 ℃ 温水浴中加热，使被测气味充分挥发，开盖嗅辨是否正常。此温度区间既能激发气味又不致破坏样品，故应选 60–70 ℃。"}, {"id": 468, "type": "单选", "question": "从一批受检粮油中均匀地、有代表性地扦取点样、集合样的过程，叫（ ）。", "options": [{"key": "A", "text": "扦样"}, {"key": "B", "text": "混样"}, {"key": "C", "text": "取样"}, {"key": "D", "text": "抽样"}], "answer": "A", "analysis": "从一批受检粮油中均匀、有代表性地扦取点样并集合成原始样品的过程称为‘扦样’。扦样是粮食检验保证代表性的首要环节，混样、取样、抽样为相关但不同的概念。"}, {"id": 469, "type": "单选", "question": "对圆仓(囤)扦样分区设点的要求是，直径在8m以下的,每层按内、中、外分别设（ ）。", "options": [{"key": "A", "text": "内1点、中2点、外4点"}, {"key": "B", "text": "内1点、中4点、外2点"}, {"key": "C", "text": "内1点、中4点、外8点"}, {"key": "D", "text": "内1点、中8点、外4点"}], "answer": "A", "analysis": "圆仓（囤）分区设点规定：直径 8 m 以下的，每层按内、中、外分别设内 1 点、中 2 点、外 4 点，以保证代表性。故应选内 1 点、中 2 点、外 4 点。"}, {"id": 470, "type": "单选", "question": "长50米、宽20米的高大平房仓装满稻谷，扦样时至少设3个区（ ）扦样点。", "options": [{"key": "A", "text": "15个"}, {"key": "B", "text": "9个"}, {"key": "C", "text": "11个"}, {"key": "D", "text": "14个"}], "answer": "C", "analysis": "高大平房仓按粮面 200–350 ㎡/区划分，50 m×20 m=1000 ㎡约划 3 个区；按规范布点（各区中心及四周组合），3 区共布 11 个扦样点符合代表性要求，故应选 11 个。"}, {"id": 471, "type": "单选", "question": "原始样品原则上不少于（ ）kg。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "5"}], "answer": "C", "analysis": "扦样规范规定，原始样品（集合样）原则上不少于 2 kg，以保证后续分样、检验用量充足并具有代表性。故应选 2 kg。"}, {"id": 472, "type": "单选", "question": "扦样时，筒仓粮堆边缘的点设在距边缘约（ ）m处。", "options": [{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.5"}, {"key": "C", "text": "1.0"}, {"key": "D", "text": "1.5"}], "answer": "A", "analysis": "筒仓粮堆边缘扦样点应设在距仓壁边缘约 0.3 m 处，既避免边缘效应又不贴近仓壁。故应选 0.3 m。"}, {"id": 473, "type": "单选", "question": "对堆高在5m以上的平房仓，扦样层数设（ ）层。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "answer": "C", "analysis": "堆高 5 m 以上的平房仓，为掌握各层粮温与品质，扦样层数设 5 层（上、中上、中、中下、下），以反映垂直方向变化。故应选 5 层。"}, {"id": 474, "type": "单选", "question": "按照《中央储备粮油质量检查扦样检验管理办法(国粮发〔2010〕190号)》,对于粮面面积较大的仓房，扦样按（ ）㎡面积分区。", "options": [{"key": "A", "text": "50-100"}, {"key": "B", "text": "100-200"}, {"key": "C", "text": "200-350"}, {"key": "D", "text": "350-500"}], "answer": "C", "analysis": "《中央储备粮油质量检查扦样检验管理办法》（国粮发〔2010〕190 号）规定，粮面面积较大的仓房按 200–350 ㎡ 面积分区设点扦样。故应选 200–350 ㎡。"}, {"id": 475, "type": "单选", "question": "扦样时以同（ ）、同批次、同等级、同货位、同车船（舱）为一个检验单位。", "options": [{"key": "A", "text": "种类"}, {"key": "B", "text": "质量"}, {"key": "C", "text": "容重"}, {"key": "D", "text": "年份"}], "answer": "A", "analysis": "扦样以同种类、同批次、同等级、同货位、同车船（舱）为一个检验单位，确保样品的同质性与代表性。‘种类’是划分检验单位的第一要素，故应选种类。"}, {"id": 476, "type": "单选", "question": "作为核查、复检及应对意外情况的备份的样品是（ ）。", "options": [{"key": "A", "text": "集合样"}, {"key": "B", "text": "送检样品"}, {"key": "C", "text": "试样"}, {"key": "D", "text": "保留样品"}], "answer": "D", "analysis": "保留样品是扦样后留存、用于核查、复检及应对意外情况的备份样品，须单独妥善保存至规定期限。集合样、送检样、试样分别为混合、送检、检验用样品，不具备份核查职能。"}, {"id": 477, "type": "单选", "question": "对圆仓(囤)扦样分区设点的要求是,直径在8m以上的,每层按内、中、外分别设（ ）。", "options": [{"key": "A", "text": "内1点、中2点、外4点"}, {"key": "B", "text": "内1点、中4点、外2点"}, {"key": "C", "text": "内1点、中4点、外8点"}, {"key": "D", "text": "内1点、中8点、外4点"}], "answer": "C", "analysis": "圆仓（囤）分区设点规定：直径 8 m 以上的，每层按内、中、外分别设内 1 点、中 4 点、外 8 点，因面积大需增加布点密度。故应选内 1 点、中 4 点、外 8 点。"}, {"id": 478, "type": "单选", "question": "扦样时,房式仓粮堆边缘的点设在距边缘约（ ）m处（如受仓房条件限制,按此距离布点扦样难于实施时，粮堆边缘扦样点的布置距离可适当调整）。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1.0"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "2.0"}], "answer": "A", "analysis": "房式仓粮堆边缘扦样点一般设在距粮堆边缘约 0.5 m 处（受条件限制可适当调整），以避开边缘压实与取样死角。故应选 0.5 m。"}, {"id": 479, "type": "单选", "question": "粮库门检对汽车运输的散装粮食扦样，使用以下（ ）扦样工具工作效率最高且样品的随机性和保密性较好。", "options": [{"key": "A", "text": "自动扦样器"}, {"key": "B", "text": "套管扦样器"}, {"key": "C", "text": "包装扦样器（手探子）"}, {"key": "D", "text": "取样勺"}], "answer": "A", "analysis": "汽车运输散装粮食门检，使用自动扦样器可实现多点、深层自动取样，工作效率最高，且样品随机性与保密性好、避免人为干扰。故应选自动扦样器。"}, {"id": 480, "type": "单选", "question": "大型仓房和圆仓均以不超过（ ）吨为一个检验单位。", "options": [{"key": "A", "text": "500"}, {"key": "B", "text": "1000"}, {"key": "C", "text": "2000"}, {"key": "D", "text": "5000"}], "answer": "C", "analysis": "《中央储备粮油质量检查扦样检验管理办法》规定，大型仓房和圆仓均以不超过 2000 吨为一个检验单位（房式仓等另有对应规定）。故应选 2000 吨。"}, {"id": 481, "type": "单选", "question": "对高大平房仓散装粮堆实施扦样时，应（ ）、先下后上逐层扦样。", "options": [{"key": "A", "text": "按区、按层、按点"}, {"key": "B", "text": "按水分大小"}, {"key": "C", "text": "按质量大小"}, {"key": "D", "text": "按高密度分层分点"}], "answer": "A", "analysis": "高大平房仓散装粮堆扦样应‘按区、按层、按点’先下后上逐层扦取，保证样品覆盖全仓各部位、具代表性。按水分或质量大小扦样会破坏代表性，故应选按区按层按点。"}, {"id": 482, "type": "单选", "question": "收购入库的储备粮必须是达到国家标准（ ）等以上的新粮。", "options": [{"key": "A", "text": "一等"}, {"key": "B", "text": "二等"}, {"key": "C", "text": "三等"}, {"key": "D", "text": "四等"}], "answer": "C", "analysis": "收购入库的储备粮必须是达到国家标准三等及以上的新粮，低于三等的不符合储备粮质量要求。故应选三等。"}, {"id": 483, "type": "单选", "question": "下列哪项不是出（入）库都有的凭证（ ）。", "options": [{"key": "A", "text": "出（入）库通知单"}, {"key": "B", "text": "出（入）库质量检验单"}, {"key": "C", "text": "出（入）库业务联系单"}, {"key": "D", "text": "发货明细表"}], "answer": "D", "analysis": "出入库共有的凭证包括出（入）库通知单、质量检验单、业务联系单等。发货明细表是出库时随货发出的凭证，入库时无此单，故不属于出入库‘都有’的凭证。"}, {"id": 484, "type": "单选", "question": "下列哪项是粮油入库质量检验单不包括的内容（ ）。", "options": [{"key": "A", "text": "水分"}, {"key": "B", "text": "杂质"}, {"key": "C", "text": "扣量"}, {"key": "D", "text": "净重"}], "answer": "D", "analysis": "入库质量检验单记录水分、杂质、不完善粒、扣量等质量与扣量指标。净重属于检斤/计量单内容，不列入质量检验单，故应选净重。"}, {"id": 485, "type": "单选", "question": "下面关于“三专”说法错误的是（ ）。", "options": [{"key": "A", "text": "专人检验"}, {"key": "B", "text": "专仓（罐）储存"}, {"key": "C", "text": "专人保管"}, {"key": "D", "text": "专账记载"}], "answer": "A", "analysis": "储备粮管理‘三专’指专仓（罐）储存、专人保管、专账记载。‘专人检验’不在‘三专’之列（检验另有扦样检验制度），故说法错误项为专人检验。"}, {"id": 486, "type": "单选", "question": "关于适用围仓散装堆放的特点，叙述错误的是（ ）。", "options": [{"key": "A", "text": "避免因粮油侧压力而发生仓墙倾斜或崩裂"}, {"key": "B", "text": "避免粮油受墙壁渗水返潮等的影响"}, {"key": "C", "text": "对堆装操作要求较高，如操作不好，有时会倒桩，造成事故"}, {"key": "D", "text": "可充分利用仓容"}], "answer": "D", "analysis": "围仓（围包）散装是在仓内用围包抵御粮油侧压力，其缺点是占用仓容、不能充分利用仓房空间，并非‘可充分利用仓容’。故叙述错误的是 D。"}, {"id": 487, "type": "单选", "question": "黑龙江某粮库需要存储2000吨的红小豆，保管员采用的堆放形式（ ）。", "options": [{"key": "A", "text": "全仓散装"}, {"key": "B", "text": "包装堆放"}, {"key": "C", "text": "围囤散装"}, {"key": "D", "text": "围包散装"}], "answer": "C", "analysis": "红小豆等豆类颗粒圆、散落性差、易结拱，黑龙江该库采用围囤散装（用席、竹围等围成圆囤散装存放），既利用散装省包又借助围囤控制侧压。故应选围囤散装。"}, {"id": 488, "type": "单选", "question": "粮油入库时，粮库需保留的仓容占总仓容的（ ）以上作为备用仓使用。", "options": [{"key": "A", "text": "10%"}, {"key": "B", "text": "8%"}, {"key": "C", "text": "6%"}, {"key": "D", "text": "4%"}], "answer": "A", "analysis": "粮油入库时，粮库须保留占总仓容 10% 以上的仓容作为备用仓，以应对临时收储、特殊品种专存等需要。故应选 10% 以上。"}, {"id": 489, "type": "单选", "question": "（ ）是用一根闭合环形输送带作牵引及承载构件的连续运输物料的机械。", "options": [{"key": "A", "text": "刮板输送机"}, {"key": "B", "text": "吸粮机"}, {"key": "C", "text": "带式输送机"}, {"key": "D", "text": "斗式提升机"}], "answer": "C", "analysis": "带式输送机以一根闭合环形输送带同时作牵引与承载构件，连续运送散粮，是粮库最常用的水平/倾角输送设备。刮板、斗提、吸粮机原理均不同。"}, {"id": 490, "type": "单选", "question": "双筒圆筒初清筛，外筛筒的筛下物是（ ）。", "options": [{"key": "A", "text": "大杂"}, {"key": "B", "text": "粗杂"}, {"key": "C", "text": "粮食"}, {"key": "D", "text": "小杂"}], "answer": "D", "analysis": "双筒圆筒初清筛中，内筛筒孔径较大，筛上为大杂、筛下为粮食；外筛筒孔径较小，筛下物为穿过的小杂（细杂），筛上为净粮。故外筛筒筛下物是小杂。"}, {"id": 491, "type": "单选", "question": "小麦按其种皮颜色分为，下面说法错误的是（ ）。", "options": [{"key": "A", "text": "黄小麦"}, {"key": "B", "text": "白小麦"}, {"key": "C", "text": "红小麦"}, {"key": "D", "text": "混合小麦"}], "answer": "A", "analysis": "小麦按种皮颜色分为白小麦、红小麦、混合小麦，并无‘黄小麦’（黄/白/混合是玉米的分类）。故说法错误项为黄小麦。"}, {"id": 492, "type": "单选", "question": "输送机在运转过程中需保持（ ）进料。", "options": [{"key": "A", "text": "均匀"}, {"key": "B", "text": "大量"}, {"key": "C", "text": "少量"}, {"key": "D", "text": "微量"}], "answer": "A", "analysis": "输送机运转中应保持均匀进料，避免忽多忽少造成堵塞、过载、皮带跑偏或物料洒落，保证设备平稳运行。故应选均匀。"}, {"id": 493, "type": "单选", "question": "关于圆筒初清筛，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "根据圆筒数量可分为单筒和双筒"}, {"key": "B", "text": "双筒圆筒初清筛内筛筒的孔径比外筛筒大"}, {"key": "C", "text": "双筒圆筒初清筛内筛筒的筛上物是小杂"}, {"key": "D", "text": "使用圆筒初清筛要根据粮油状况和所需生产率调整好圆筒倾斜角度"}], "answer": "C", "analysis": "圆筒初清筛中，双筒的内筛筒孔径比外筛筒大，内筛筒筛上物是大杂而非小杂，小杂经外筛筒筛下分出。故‘内筛筒筛上物是小杂’说法错误。"}, {"id": 494, "type": "单选", "question": "选筛辅助法检验玉米杂质所选用的筛层为（ ）。", "options": [{"key": "A", "text": "1.2mm"}, {"key": "B", "text": "1.5mm"}, {"key": "C", "text": "2.0mm"}, {"key": "D", "text": "3.0mm"}], "answer": "D", "analysis": "选筛辅助法检验玉米杂质，按标准采用 3.0 mm 圆孔筛（上层筛除大杂），配合较小筛孔分出小杂。玉米粒大，故筛层为 3.0 mm。"}, {"id": 495, "type": "单选", "question": "选筛辅助法检验大豆杂质所选用的筛层为（ ）。", "options": [{"key": "A", "text": "1.2mm"}, {"key": "B", "text": "1.5mm"}, {"key": "C", "text": "2.0mm"}, {"key": "D", "text": "3.0mm"}], "answer": "D", "analysis": "选筛辅助法检验大豆杂质，因大豆粒大采用 3.0 mm 圆孔筛（上层筛除大杂）。故筛层为 3.0 mm。"}, {"id": 496, "type": "单选", "question": "下面不属于无机杂质的是（ ）。", "options": [{"key": "A", "text": "异种粮粒"}, {"key": "B", "text": "泥土"}, {"key": "C", "text": "砂石"}, {"key": "D", "text": "砖瓦块"}], "answer": "A", "analysis": "无机杂质指泥土、砂石、砖瓦块、煤渣等矿物性杂质；异种粮粒属有机杂质。故‘不属于无机杂质’的是异种粮粒。"}, {"id": 497, "type": "单选", "question": "下面不属于有机杂质的是（ ）。", "options": [{"key": "A", "text": "异种粮粒"}, {"key": "B", "text": "异种油料种子"}, {"key": "C", "text": "砂石"}, {"key": "D", "text": "杂草种子"}], "answer": "C", "analysis": "有机杂质包括异种粮粒、异种油料种子、杂草种子、茎叶残体等；砂石为无机杂质。故‘不属于有机杂质’的是砂石。"}, {"id": 498, "type": "单选", "question": "在粮油加工中，（ ）将影响出品率，根据（ ）含量大小指导加工工艺。", "options": [{"key": "A", "text": "水分含量低；水分"}, {"key": "B", "text": "水分含量高；水分"}, {"key": "C", "text": "杂质含量高；杂质"}, {"key": "D", "text": "杂质含量低；杂质"}], "answer": "C", "analysis": "粮油中杂质含量高会降低加工出品率（杂质不产成品且增加损耗），加工中依据杂质含量大小来调整清理工艺与设备。故应选‘杂质含量高；杂质’。"}, {"id": 499, "type": "单选", "question": "粮油中混有杂质不但降低食用价值，而且往往由于杂质含水量高，存在着大量（ ），容易引起储粮发热、霉变，影响储粮安全。", "options": [{"key": "A", "text": "细菌"}, {"key": "B", "text": "霉菌"}, {"key": "C", "text": "微生物"}, {"key": "D", "text": "乳酸菌"}], "answer": "C", "analysis": "杂质尤其是泥沙、茎叶等往往含水量高并携带大量微生物（细菌、霉菌等），混入粮堆后易在杂质聚集处发热、霉变，威胁储粮安全。故应选微生物。"}, {"id": 500, "type": "单选", "question": "检验玉米水分含量，主要看玉米的（ ），（ ）紧缩起皱，蒂松脆易断，则水分较低。", "options": [{"key": "A", "text": "胚乳；胚乳"}, {"key": "B", "text": "子叶；子叶"}, {"key": "C", "text": "胚部；胚"}, {"key": "D", "text": "种皮；种皮"}], "answer": "C", "analysis": "检验玉米水分主要看胚部：水分低时玉米胚紧缩、起皱，胚蒂松脆易折断；水分高则胚部饱满、湿润、柔韧。故应选‘胚部；胚’。"}, {"id": 501, "type": "单选", "question": "下面关于触觉检验粮油水分含量，表述正确的是（ ）。", "options": [{"key": "A", "text": "手掌感觉硬且刺手，水分含量较高"}, {"key": "B", "text": "手插入粮堆较为容易，水分含量较高"}, {"key": "C", "text": "脆滑、松爽水分含量高"}, {"key": "D", "text": "用牙咬，咬断时发软疏松，水分含量较高"}], "answer": "D", "analysis": "粮食水分越高，籽粒组织结构越松软，牙咬时阻力小、发软疏松；反之水分低则硬、脆、响声清脆。故用牙咬断时发软疏松说明水分较高。A、B、C三项描述的硬刺手、易插入、脆滑松爽均为水分较低的表现，只有D正确。"}, {"id": 502, "type": "单选", "question": "下面关于齿觉检验粮油水分含量，表述错误的是（ ）。", "options": [{"key": "A", "text": "咬断时发软疏松，水分含量较高"}, {"key": "B", "text": "咬断时响声轻、浊水分含量较高"}, {"key": "C", "text": "咬断时粮粒呈粉状水分含量较低"}, {"key": "D", "text": "咬断时，响声清脆，一咬两段水分含量较低"}], "answer": "C", "analysis": "齿觉检验中，水分高的粮咬断发软疏松、声响轻浊（A、B正确），水分低的粮咬断清脆、一咬两段（D正确）。C项称'咬断呈粉状水分较低'不够严谨，因粉质胚乳品种（如软质小麦）即使水分正常也易咬断成粉状，不能单凭'粉状'判定水分低，正确低水分判定应以清脆响声加一咬两段综合判断，故C为错误表述。"}, {"id": 503, "type": "单选", "question": "下面关于小颗粒油料水分含量的判定，表述错误的是（ ）。", "options": [{"key": "A", "text": "用手将油料在粮堆上抛、撒，响声清脆松爽的水分较低"}, {"key": "B", "text": "擦压时响声不脆，壳仁分离度不高，则水分较含量低"}, {"key": "C", "text": "擦压时无响声，籽粒压成扁平状且壳仁不分离，则水分高"}, {"key": "D", "text": "用手抓一把，紧紧捏住将手张开时，手上剩余的籽粒自然散开，不成团，水分较低"}], "answer": "B", "analysis": "小颗粒油料干燥时擦压响声清脆、壳仁易分离，水分低（A、D正确）；受潮时擦压无响声、压成扁平壳仁不分离，水分高（C正确）。B项称'擦压响声不脆、壳仁分离度不高则水分较低'正好说反，受潮才会出现响声不脆、分离度低，故B错误。"}, {"id": 504, "type": "单选", "question": "下面关于带壳油料水分含量的判定，表述错误的是（ ）。", "options": [{"key": "A", "text": "用手抓一小把带壳油料，加以摇动，听其响声，如响声清脆则水分较高"}, {"key": "B", "text": "拣出其中幼果，剥去外壳看籽仁的干湿程度"}, {"key": "C", "text": "选取中等饱满的带壳油料数颗，剥去果皮，看去皮的难易度、去皮时的响声和果仁的表面状况，判别水分含量"}, {"key": "D", "text": "用手插入带壳油料堆内，用力一推，如容易推动，并哗哗作响，则水分低"}], "answer": "A", "analysis": "带壳油料摇动时响声清脆说明干燥、水分低，响声沉闷才表示水分高。A项称'清脆则水分较高'说反，故错误；B、C、D的检查方法（看幼果、看去皮难易、推动哗响）均正确反映水分低。"}, {"id": 505, "type": "单选", "question": "带式输送机较长时间不使用，应（ ）胶带，入库保存。", "options": [{"key": "A", "text": "拆下"}, {"key": "B", "text": "更换"}, {"key": "C", "text": "调松"}, {"key": "D", "text": "调紧"}], "answer": "C", "analysis": "输送带长期闲置若保持紧绷会加速老化并产生永久伸长变形，因此较长时间不使用时应当调松胶带后再入库保存，以减小胶带受力、延长使用寿命。"}, {"id": 506, "type": "单选", "question": "下面关于带式输送机装卸粮油操作步骤正确的是（ ）。（1）按照顺序停机，完成装卸输送任务（2）空载启动，检查并确定各机械设备可正常运行（3）均匀输送粮油，观察粮油质量及安全运行情况（4）检查输送堆装设备的构件完好性、输送带的松紧", "options": [{"key": "A", "text": "（3）（1）（4）（2）"}, {"key": "B", "text": "（4）（3）（1）（2）"}, {"key": "C", "text": "（4）（2）（3）（1）"}, {"key": "D", "text": "（3）（2）（4）（1）"}], "answer": "C", "analysis": "安全操作规程要求先检查设备构件完好性与输送带松紧（4），再空载启动试车确认正常（2），然后均匀输送并观察质量与安全（3），最后按顺序停机（1）。故正确顺序为(4)(2)(3)(1)。"}, {"id": 507, "type": "单选", "question": "下面关于滚筒筛，说法错误的是（ ）。", "options": [{"key": "A", "text": "维修方便"}, {"key": "B", "text": "能耗低、处理量大"}, {"key": "C", "text": "筛身短，传动平稳"}, {"key": "D", "text": "清杂效果好"}], "answer": "C", "analysis": "滚筒筛具有维修方便、能耗低、处理量大、清杂效果好等优点，但其筛筒为圆筒形且有一定长度以保证筛理时间，并非'筛身短'。故C项'筛身短，传动平稳'说法错误。"}, {"id": 508, "type": "单选", "question": "下面关于提高溜筛清理效率改进方法，说法错误的是（ ）。", "options": [{"key": "A", "text": "控制流量，使物料均匀地流过整个筛面，粮层厚度不可太小"}, {"key": "B", "text": "根据杂质的性状，选择大小合适的筛孔"}, {"key": "C", "text": "筛面要平直，不得下凹，宽度要适当"}, {"key": "D", "text": "要经常清理筛面上被堵的筛孔"}], "answer": "A", "analysis": "提高溜筛清理效率应使物料均匀流过筛面、粮层厚度适中（通常不可太厚，应偏薄以保证筛选），B、C、D均正确。A项称'粮层厚度不可太小'表述错误，实际应为粮层不可太厚，故A是错误说法。"}, {"id": 509, "type": "单选", "question": "下面关于溜筛清理粮油，顺序正确的是（ ）。（1）根据清理的生产量确定使用溜筛的规格型号（2）均匀进粮，清理杂质（3）检查溜筛筛网筛孔尺寸、筛面长度、完好性等，调整好筛面倾斜角度（4）检查筛下物出口处有无堵塞或正常粮油混入", "options": [{"key": "A", "text": "（3）（1）（2）（4）"}, {"key": "B", "text": "（1）（3）（2）（4）"}, {"key": "C", "text": "（2）（1）（3）（4）"}, {"key": "D", "text": "（1）（2）（4）（3）"}], "answer": "B", "analysis": "溜筛清理应先按生产量选定规格型号（1），再检查筛网筛孔、调整倾斜角度（3），然后均匀进粮清理（2），最后检查筛下物出口是否堵塞或混入好粮（4）。正确顺序为(1)(3)(2)(4)。"}, {"id": 510, "type": "单选", "question": "用染色法鉴别阴糯稻谷，呈（ ）的为糯性米粒。", "options": [{"key": "A", "text": "黄色"}, {"key": "B", "text": "蓝色"}, {"key": "C", "text": "红棕色"}, {"key": "D", "text": "橙色"}], "answer": "C", "analysis": "碘-碘化钾染色法利用淀粉与碘的显色反应：糯性稻米几乎全为支链淀粉，遇碘呈红棕色（棕红色）；非糯性含直链淀粉呈蓝色。故呈红棕色的为糯性米粒。"}, {"id": 511, "type": "单选", "question": "用染色法鉴别阴糯稻谷，呈（ ）的为非糯性米粒。", "options": [{"key": "A", "text": "黄色"}, {"key": "B", "text": "蓝色"}, {"key": "C", "text": "红棕色"}, {"key": "D", "text": "橙色"}], "answer": "B", "analysis": "非糯性米粒含有直链淀粉，与碘-碘化钾溶液反应呈蓝色；糯性米粒（支链淀粉为主）呈红棕色。故呈蓝色的为非糯性米粒。"}, {"id": 512, "type": "单选", "question": "用染色法鉴别阴糯稻谷，用（ ）浓度的碘-碘化钾溶液浸泡1min左右，洗净观察米粒的染色情况。", "options": [{"key": "A", "text": "0.1%"}, {"key": "B", "text": "0.2%"}, {"key": "C", "text": "0.3%"}, {"key": "D", "text": "0.4%"}], "answer": "A", "analysis": "阴糯稻谷染色鉴别通常取0.1%浓度的碘-碘化钾溶液，浸泡约1分钟后洗净观察米粒染色情况来区分糯性与非糯性。常见标准浓度约为0.1%，以官方教材为准。"}, {"id": 513, "type": "单选", "question": "下面不属于稻谷籽粒结构是（ ）。", "options": [{"key": "A", "text": "胚"}, {"key": "B", "text": "沟纹"}, {"key": "C", "text": "腹沟"}, {"key": "D", "text": "颖尖"}], "answer": "C", "analysis": "稻谷籽粒结构包括颖（颖壳，有颖尖、护颖、钩纹等）、胚、胚乳；腹沟是小麦籽粒表面的典型特征，并非稻谷的结构组成。故C不属于稻谷籽粒结构。"}, {"id": 514, "type": "单选", "question": "包装粮油扦样时，采取倒包和拆包相结合的方法，倒包与拆包比例是（ ）。", "options": [{"key": "A", "text": "1：2"}, {"key": "B", "text": "1：3"}, {"key": "C", "text": "2：3"}, {"key": "D", "text": "1：4"}], "answer": "D", "analysis": "包装粮油扦样采用倒包与拆包相结合的方法，按规定倒包与拆包的比例为1:4（即每5包中倒包1包、拆包4包），以保证样品代表性。"}, {"id": 515, "type": "单选", "question": "下面不能用电动吸式扦样器是（ ）。", "options": [{"key": "A", "text": "深层粮食的扦样"}, {"key": "B", "text": "油料的扦样和流动粮食的扦样"}, {"key": "C", "text": "油料的取样或倒、拆包取样"}, {"key": "D", "text": "杂质检验项目的取样"}], "answer": "D", "analysis": "电动吸式扦样器适用于深层粮、油料及流动粮的扦样和倒拆包取样，但由于吸力会造成籽粒破碎和粒度偏析，不适用于对籽粒完整性要求高的杂质检验项目取样。故D不能用。"}, {"id": 516, "type": "单选", "question": "下面不属于粮油样品分类的是（ ）。", "options": [{"key": "A", "text": "试验样品"}, {"key": "B", "text": "复核样品"}, {"key": "C", "text": "平均样品"}, {"key": "D", "text": "原始样品"}], "answer": "B", "analysis": "粮油样品按用途与处理阶段分为原始样品、平均样品、试验样品（及保留样品等），'复核样品'并非标准分类名称。故B不属于粮油样品分类。"}, {"id": 517, "type": "单选", "question": "下面不属于包装粮油扦样器的是（ ）。", "options": [{"key": "A", "text": "大粒粮扦样器"}, {"key": "B", "text": "中小粮扦样器"}, {"key": "C", "text": "粉状粮扦样器"}, {"key": "D", "text": "小粮扦样器"}], "answer": "D", "analysis": "包装粮扦样器规范类型有大粒粮扦样器、中小粒粮扦样器、粉状粮扦样器，'小粮扦样器'不是规范名称（对应应为中小粒粮扦样器）。故D不属于。"}, {"id": 518, "type": "单选", "question": "下面关于“四落实”，说法错误的是（ ）。", "options": [{"key": "A", "text": "账目落实"}, {"key": "B", "text": "质量落实"}, {"key": "C", "text": "数量落实"}, {"key": "D", "text": "品种落实"}], "answer": "A", "analysis": "粮油库存管理'四落实'指数量落实、质量落实、品种落实、地点落实（账实相符），'账目落实'不是'四落实'的标准表述内容。故A说法错误。"}, {"id": 519, "type": "单选", "question": "稻谷表现有（ ）条脉迹。", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "answer": "D", "analysis": "稻谷稃壳表面具有纵行脉纹（脉迹），据教材稻谷表现有5条脉迹，是鉴别稻谷形态的特征之一。常见标准值约为5条，以官方教材为准。"}, {"id": 520, "type": "单选", "question": "下面不属于胚的组成部分的是（ ）。", "options": [{"key": "A", "text": "胚乳"}, {"key": "B", "text": "盾片"}, {"key": "C", "text": "胚芽"}, {"key": "D", "text": "胚根"}], "answer": "A", "analysis": "胚由胚芽、胚根、盾片（子叶）、胚轴等组成，是种子的生活部分；胚乳是独立的贮藏组织，为种子发芽提供养分，不属于胚的组成部分。故A正确。"}, {"id": 521, "type": "单选", "question": "关于籼稻谷籽粒按其粒质和收获季节分类，下面说法错误的是（ ）。", "options": [{"key": "A", "text": "籼型非糯稻谷"}, {"key": "B", "text": "籼糯稻谷"}, {"key": "C", "text": "早籼稻谷"}, {"key": "D", "text": "晚籼稻谷"}], "answer": "A", "analysis": "籼稻谷按粒质和收获季节具体分为早籼稻谷、晚籼稻谷和籼糯稻谷，'籼型非糯稻谷'是按粒质划分的大类总称，并非按收获季节细分的具体类别。故A作为此类细分项的表述错误。"}, {"id": 522, "type": "单选", "question": "下面不属于小麦组织结构的是（ ）。", "options": [{"key": "A", "text": "皮层"}, {"key": "B", "text": "沟纹"}, {"key": "C", "text": "胚"}, {"key": "D", "text": "胚乳"}], "answer": "B", "analysis": "小麦籽粒由皮层、胚乳、胚三部分组织结构组成，腹沟（沟纹）只是籽粒表面的形态特征，并非组织结构。故B不属于小麦组织结构。"}, {"id": 523, "type": "单选", "question": "硬质部分达到小麦颗粒切面的（ ）以上为硬质粒。", "options": [{"key": "A", "text": "1/2"}, {"key": "B", "text": "1/3"}, {"key": "C", "text": "1/4"}, {"key": "D", "text": "1/5"}], "answer": "A", "analysis": "小麦硬质粒（角质粒）判定以横切面中透明硬质部分所占比例为准，硬质部分达到颗粒切面的1/2及以上即为硬质粒。故A正确。"}, {"id": 524, "type": "单选", "question": "硬质粒达到总量（ ）以上的，为硬质小麦。", "options": [{"key": "A", "text": "60%"}, {"key": "B", "text": "70%"}, {"key": "C", "text": "80%"}, {"key": "D", "text": "90%"}], "answer": "B", "analysis": "硬质小麦的定义为硬质粒（角质粒）含量占总量的70%及以上，低于此比例则为混合硬质或软质小麦。故B（70%）正确。"}, {"id": 525, "type": "单选", "question": "根据种皮颜色混合玉米是指混入本类以外玉米超过（ ）的玉米。", "options": [{"key": "A", "text": "4.0%"}, {"key": "B", "text": "5.0%"}, {"key": "C", "text": "8.0%"}, {"key": "D", "text": "10.0%"}], "answer": "B", "analysis": "玉米按种皮颜色分为黄玉米、白玉米和混合玉米，其中混入本类以外颜色玉米超过5.0%的即归为混合玉米。常见标准值约为5.0%，以官方教材为准。"}, {"id": 526, "type": "单选", "question": "中、小粒包装粮食和油料扦样包数不少于总数（ ）。", "options": [{"key": "A", "text": "4.0%"}, {"key": "B", "text": "5.0%"}, {"key": "C", "text": "8.0%"}, {"key": "D", "text": "10.0%"}], "answer": "B", "analysis": "包装粮油扦样规定：中、小粒包装粮食和油料的扦样包数不少于总包数的5.0%，以保证样品代表性。故B正确。"}, {"id": 527, "type": "单选", "question": "特大粒包装粮食和油料200包以下的取样（ ）10包。", "options": [{"key": "A", "text": "不少于"}, {"key": "B", "text": "不大于"}, {"key": "C", "text": "小于"}, {"key": "D", "text": "大于"}], "answer": "A", "analysis": "特大粒包装粮食和油料在200包以下时，取样包数不少于10包（设定最低取样量），以保证代表性。故A正确。"}, {"id": 528, "type": "单选", "question": "小麦粉和其它粉类扦样包数不少于总包数的（ ）。", "options": [{"key": "A", "text": "3%"}, {"key": "B", "text": "4%"}, {"key": "C", "text": "5%"}, {"key": "D", "text": "6%"}], "answer": "A", "analysis": "粉类粮油（小麦粉及其他粉类）扦样规定扦样包数不少于总包数的3%，低于粮粒类扦样比例。故A正确。"}, {"id": 529, "type": "单选", "question": "关于机械台秤，下面说法错误的是（ ）。", "options": [{"key": "A", "text": "调零时，秤板上不能放置任何物体"}, {"key": "B", "text": "定量称量时，每次固定游码，只允许转动最下面的小螺丝"}, {"key": "C", "text": "远距离移动台秤时，要双手捧住底座搬移，严禁抓住连杆移动"}, {"key": "D", "text": "不可称量潮湿的样品"}], "answer": "D", "analysis": "机械台秤调零时秤板不得放物（A对）、定量称量固定游码只调小螺丝（B对）、移动时双手捧底座（C对）；潮湿样品并非绝对不可称量，称量后及时清洁即可，故D'不可称量潮湿的样品'说法错误。"}, {"id": 530, "type": "单选", "question": "关于电子台秤，下面说法错误的是（ ）。", "options": [{"key": "A", "text": "不可称量具有吸湿性、挥发性、腐蚀性的物品"}, {"key": "B", "text": "不可称量过热或过冷的物品"}, {"key": "C", "text": "称量完毕，及时做好清洁卫生"}, {"key": "D", "text": "按电子秤开关和其他键时，要缓缓进行"}], "answer": "A", "analysis": "电子台秤不能称量腐蚀性物品（会损传感器/面板）和过热过冷物品（B对），称量后清洁（C对）、按键缓缓（D对）；但具有吸湿性、挥发性的物品可快速称量（用密闭容器），并非不可称，故A将可称的也列入'不可称'说法错误。"}, {"id": 531, "type": "单选", "question": "下列属于自动秤的是（ ）。", "options": [{"key": "A", "text": "案秤"}, {"key": "B", "text": "电子皮带秤"}, {"key": "C", "text": "电子台秤"}, {"key": "D", "text": "弹簧秤"}], "answer": "B", "analysis": "自动秤能连续自动完成称量，如电子皮带秤、定量包装秤、斗式衡器等；案秤、电子台秤、弹簧秤均为人工操作的非自动秤。故B正确。"}, {"id": 532, "type": "单选", "question": "秤板上不能施加（ ）最大称量范围的重物或外力，否则会损伤刀口，影响台秤的灵敏度", "options": [{"key": "A", "text": "小于"}, {"key": "B", "text": "大于"}, {"key": "C", "text": "不小大"}, {"key": "D", "text": "不大于"}], "answer": "B", "analysis": "秤板上施加超过最大称量范围的重物或外力会压伤刀口、降低灵敏度甚至损坏台秤，故不能施加大于最大称量的力。故B正确。"}, {"id": 533, "type": "单选", "question": "下列不属于粮油入库凭证的是（ ）。", "options": [{"key": "A", "text": "入库通知单"}, {"key": "B", "text": "发货明细表"}, {"key": "C", "text": "入库质量检验单"}, {"key": "D", "text": "入库检斤单"}], "answer": "B", "analysis": "粮油入库凭证包括入库通知单、入库质量检验单、入库检斤单等；发货明细表是发货方随货发出的发运单据，属出库/发运凭证，不作为入库凭证。故B不属于。"}, {"id": 534, "type": "单选", "question": "滚筒筛适用于（ ）的清理。", "options": [{"key": "A", "text": "原粮"}, {"key": "B", "text": "成品粮"}, {"key": "C", "text": "大粒粮"}, {"key": "D", "text": "中、小粒粮"}], "answer": "A", "analysis": "滚筒筛处理量大、能耗低，适合对未加工的原粮进行初步清理除杂；成品粮清理多使用其他精选设备。故A原粮正确。"}, {"id": 535, "type": "单选", "question": "灭火器放置环境温度低于55℃，且不能接近火源的是（ ）。", "options": [{"key": "A", "text": "酸碱灭火器"}, {"key": "B", "text": "卤代烷灭火器"}, {"key": "C", "text": "二氧化碳灭火器"}, {"key": "D", "text": "泡沫灭火器"}], "answer": "C", "analysis": "二氧化碳灭火器贮瓶对温度敏感，存放环境温度应低于55℃且不能接近火源，以防液态CO₂压力过高发生危险。故C正确。"}, {"id": 536, "type": "判断", "question": "小麦表皮紧缩、色泽淡黄或淡红且均匀一致时，水分较低。", "options": ["√", "×"], "answer": "√", "analysis": "低水分小麦表皮紧缩、有光泽、色泽淡黄或淡红且均匀一致；高水分麦皮松软、色泽发暗。该陈述符合感官判定规律，正确。"}, {"id": 537, "type": "判断", "question": "感官判定粮油色泽，判定场所要有足够的光线强度，室内色彩柔和，避免强对比色，附近不能有红、黄、绿三种色调存在。", "options": ["√", "×"], "answer": "√", "analysis": "感官检验色泽需在标准散射光源下进行，光线充足、色彩柔和、避免强对比色，且周围不得有红、黄、绿等色调干扰，以免影响对粮油真实色泽的判断。故正确。"}, {"id": 538, "type": "判断", "question": "用牙咬玉米籽粒，感觉坚硬，响声清脆，一咬两段，说明水分较高。", "options": ["√", "×"], "answer": "×", "analysis": "牙咬玉米籽粒坚硬、响声清脆、一咬两段是低水分粮的典型特征；高水分粮咬断发软、湿润、粘牙。该陈述说'水分较高'错误，应为水分较低。"}, {"id": 539, "type": "判断", "question": "中央储备粮一旦入库，所有权、使用权在国务院，未经国家有关部门批准，任何单位和个人都不得擅自动用。", "options": ["√", "×"], "answer": "√", "analysis": "中央储备粮属中央事权粮食，其所有权、使用权、动用权在国务院，未经国家有关部门批准任何单位和个人不得擅自动用（《中央储备粮管理条例》）。故正确。"}, {"id": 540, "type": "判断", "question": "电动吸式扦样器操作简便，可以减少劳动强度，适用于任何检验项目的样品扞样。", "options": ["√", "×"], "answer": "×", "analysis": "电动吸式扦样器虽操作简便、减轻劳动强度，但吸力会造成籽粒破碎和粒度偏析，并不适用于所有检验项目（如杂质、出糙率等需保持籽粒完整的项目）。故'适用于任何项目'错误。"}, {"id": 541, "type": "判断", "question": "原始样品的扦取必须按国家标准操作规程规定的方法，才能保证样品的代表。", "options": ["√", "×"], "answer": "√", "analysis": "原始样品的扦取必须按国家标准操作规程（如GB 5491）规定的方法进行，才能避免偏差、保证样品对整批粮油的代表性。故正确。"}, {"id": 542, "type": "判断", "question": "从一批受检粮油中按规定扦取的具有代表性的部分称为样品。", "options": ["√", "×"], "answer": "√", "analysis": "样品的定义即：从一批受检粮油中按规定方法扦取的、能够代表该批粮油质量的部分。该陈述符合样品定义，正确。"}, {"id": 543, "type": "判断", "question": "溜筛是一种静止而倾斜的筛子。", "options": ["√", "×"], "answer": "√", "analysis": "溜筛依靠物料自身重力在静止、倾斜的筛面上滑动完成筛分，无动力振动装置，故属于静止而倾斜的筛子。正确。"}, {"id": 544, "type": "判断", "question": "粳糯稻谷糙米籽粒一般呈椭圆形，米粒呈半透明状，米质粘性较大，胀性较小。", "options": ["√", "×"], "answer": "×", "analysis": "粳糯稻谷糙米虽多呈椭圆形、粘性大、胀性小，但糯性米粒因几乎全为支链淀粉而呈不透明（乳白/浑浊）状，并非'半透明'。该陈述'半透明状'错误。"}, {"id": 545, "type": "判断", "question": "保持油罐的密闭性，在一定程度上是减少油品的蒸发损耗。", "options": ["√", "×"], "answer": "√", "analysis": "油脂的蒸发损耗主要由油面与空气接触引起，保持油罐密闭可减少挥发组分的散失，从而在一定程度上降低蒸发损耗。正确。"}, {"id": 546, "type": "判断", "question": "扦样时务必做到保护样品，所有扦样操作应在较短时间内完成，以避免样品组分发生变化。", "options": ["√", "×"], "answer": "√", "analysis": "扦样后样品应尽快处理、缩短在空气中暴露的时间，防止水分蒸发、吸湿或成分发生变化，以保护样品原有组分和代表性。正确。"}, {"id": 547, "type": "判断", "question": "非均相油脂和均相油脂扦样是一样的。", "options": ["√", "×"], "answer": "×", "analysis": "非均相油脂（含水分、悬浮物，如毛油）与均相油脂（精炼澄清油）物理性质不同、易分层，扦样方法不同（非均相需混匀或分层取样）。故两者扦样不一样，该陈述错误。"}, {"id": 548, "type": "判断", "question": "储备油必须是国家标准四级以上的新油。", "options": ["√", "×"], "answer": "√", "analysis": "储备油质量要求严格，必须为国家规定等级（如国标四级）以上的新油，质量合格方可入库储存。该陈述符合储备油质量要求，正确。"}, {"id": 549, "type": "判断", "question": "一般认为粉质胚乳多的，蛋白质含量高，出粉率高。", "options": ["√", "×"], "answer": "√", "analysis": "粉质（软质）胚乳结构疏松、研磨时易粉碎且皮层与胚乳易分离，出粉率较高；此类麦粒面粉的面筋蛋白质品质相对较好。故该说法正确。"}, {"id": 550, "type": "单选", "question": "粮油入库结尾工作主要包括核准数字、（ ）、全面检查、平整粮面等。", "options": [{"key": "A", "text": "严格检验"}, {"key": "B", "text": "建立账卡"}, {"key": "C", "text": "准确检斤"}, {"key": "D", "text": "空仓杀虫"}], "answer": "B", "analysis": "粮油入库收尾工作包括核准数字、建立账卡（货位卡与保管账）、全面检查、平整粮面等环节，建立账卡是收尾关键步骤。故B正确。"}, {"id": 551, "type": "单选", "question": "库存粮油货位卡（仓囤卡）要在形成货位或货位变化后立即填写。存档不少于（ ）。年。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "answer": "C", "analysis": "库存粮油货位卡（仓囤卡）应在形成货位或货位变化后立即填写，并按档案管理要求存档不少于5年，以备查考。故C（5年）正确。"}, {"id": 552, "type": "单选", "question": "库存粮油货位卡（仓囤卡）“实际数量”要保留（ ）位小数。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "answer": "A", "analysis": "货位卡中'实际数量'指成货位时的实际计量数量，单位为吨，按规范小数点后保留3位小数。故A正确。"}, {"id": 553, "type": "单选", "question": "粮油保管总账按年度装订成册，存档期不少于（ ）年。", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "7"}, {"key": "C", "text": "8"}, {"key": "D", "text": "10"}], "answer": "D", "analysis": "粮油保管总账按年度装订成册，属重要账务档案，存档期不少于10年。故D正确。"}, {"id": 554, "type": "单选", "question": "粮油保管明细账按年度装订成册，存档期不少于（ ）年。", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "7"}, {"key": "C", "text": "8"}, {"key": "D", "text": "10"}], "answer": "D", "analysis": "粮油保管明细账同样按年度装订成册，存档期不少于10年，与总账保存期限一致。故D正确。"}, {"id": 555, "type": "单选", "question": "粮油保管记账凭证与相关计量码单等原始单据用胶水粘在一起，按（ ）汇总装订，存档期不少于10年。", "options": [{"key": "A", "text": "周"}, {"key": "B", "text": "月"}, {"key": "C", "text": "季度"}, {"key": "D", "text": "年度"}], "answer": "B", "analysis": "粮油保管记账凭证与相关计量码单等原始单据用胶水粘在一起，按规定按月汇总装订，存档期不少于10年。故B（月）正确。"}, {"id": 556, "type": "单选", "question": "粮油保管明细账按（ ）装订成册，存档期不少于10年。", "options": [{"key": "A", "text": "周"}, {"key": "B", "text": "月"}, {"key": "C", "text": "季度"}, {"key": "D", "text": "年度"}], "answer": "D", "analysis": "粮油保管明细账以年度为周期装订成册，存档期不少于10年。故D（年度）正确。"}, {"id": 557, "type": "单选", "question": "走道板铺设距离墙边（ ）m。", "options": [{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.5"}, {"key": "C", "text": "0.8"}, {"key": "D", "text": "1.0"}], "answer": "B", "analysis": "粮面走道板铺设时应距墙边约0.5m，既便于保管员行走检查粮情，又避免紧贴仓墙受潮生霉。常见标准值约为0.5m，以官方教材为准。"}, {"id": 558, "type": "单选", "question": "关于设备、器材建保管账，下列说法不正确的是（ ）。", "options": [{"key": "A", "text": "收入数量日期同设备、器材入库单日期一致"}, {"key": "B", "text": "支出数量日期同设备器材出库单日期一致。"}, {"key": "C", "text": "同一类别、同一规格"}, {"key": "D", "text": "记账人为主管负责人"}], "answer": "D", "analysis": "设备器材保管账要求收入/支出数量日期与出入库单一致、同类同规格建账，记账人应为保管员或指定记账人员，并非必须为主管负责人。故D不正确。"}, {"id": 559, "type": "单选", "question": "粮食出入库设备、器材归还时，如管理员发现损坏、故障可（ ）入库。", "options": [{"key": "A", "text": "如实记录"}, {"key": "B", "text": "协商"}, {"key": "C", "text": "拒绝"}, {"key": "D", "text": "由主管领导决定"}], "answer": "C", "analysis": "设备器材归还时管理员发现损坏、故障的可拒绝入库，要求领用人修复后再归还，以保证账物完好、责任清晰。故C正确。"}, {"id": 560, "type": "单选", "question": "大型清理设备需厂家维修、不能及时归还，不正确的做法是（ ）。", "options": [{"key": "A", "text": "先将机械设备清理干净转入待修区或入库暂存"}, {"key": "B", "text": "状态填写如“损坏/故障”"}, {"key": "C", "text": "在备注中详细记录故障情况及预计修理时间"}, {"key": "D", "text": "直接建账入库存放"}], "answer": "D", "analysis": "大型清理设备需厂家维修不能及时归还时，应先清理转入待修区、状态填'损坏/故障'并备注故障情况，不得直接作为正常设备建账入库。故D（直接建账入库存放）不正确。"}, {"id": 561, "type": "单选", "question": "下列选项错误的是：折标水杂数量是指根据本货位粮油库存数量、当期的平均水分和杂质，折算成（ ）规定的水分杂质含量的粮食数量。", "options": [{"key": "A", "text": "国家标准"}, {"key": "B", "text": "行业标准"}, {"key": "C", "text": "地方标准"}, {"key": "D", "text": "企业标准"}], "answer": "D", "analysis": "折标水杂数量是根据库存数量及当期平均水分、杂质，折算成国家标准（或规定的标准水分、杂质）含量的粮食数量，而非企业标准。故D（企业标准）错误。"}, {"id": 562, "type": "单选", "question": "平整粮面前，作业人员应先开启（ ）。", "options": [{"key": "A", "text": "照明设备"}, {"key": "B", "text": "仓门"}, {"key": "C", "text": "电源"}, {"key": "D", "text": "仓房排风扇或窗户"}], "answer": "D", "analysis": "平整粮面前应先开启仓房排风扇或窗户进行通风，排出仓内粉尘、防止缺氧和粉尘积聚，保障作业人员安全。故D正确。"}, {"id": 563, "type": "单选", "question": "平整粮面时，应安排至少（ ）人同时作业", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": "B", "analysis": "平整粮面属于有限空间作业，应安排至少2人同时作业并互相监护，防止人员被粮埋、窒息等事故。故B（2人）正确。"}, {"id": 564, "type": "单选", "question": "以下情形属于粮油储存事故造成的粮油损失的是（ ）。", "options": [{"key": "A", "text": "水分减量"}, {"key": "B", "text": "粮食被虫蚀、变质"}, {"key": "C", "text": "杂质减量"}, {"key": "D", "text": "自然损耗"}], "answer": "B", "analysis": "粮油储存事故损失指因保管不善造成的虫蚀、霉变、变质等；水分减量、杂质减量、自然损耗属正常损耗，不计入事故损失。故B正确。"}, {"id": 565, "type": "单选", "question": "以下情形不属于粮油损耗的是（ ）。", "options": [{"key": "A", "text": "水分减量"}, {"key": "B", "text": "粮食被虫蚀、变质"}, {"key": "C", "text": "杂质减量"}, {"key": "D", "text": "自然损耗"}], "answer": "B", "analysis": "粮油正常损耗包括水分减量、杂质减量和自然损耗；粮食被虫蚀、变质属储存事故造成的损失，不属于正常损耗范畴。故B正确。"}, {"id": 566, "type": "单选", "question": "粮油保管账明细账以仓为单位填写，详细反映分性质、品种、等级、货位的粮油（ ）情况。", "options": [{"key": "A", "text": "出入库和库存"}, {"key": "B", "text": "出库"}, {"key": "C", "text": "入库"}, {"key": "D", "text": "库存"}], "answer": "A", "analysis": "粮油保管明细账以仓为单位，逐笔、详细地反映分性质、品种、等级、货位的粮油出入库动态和库存结存情况。故A正确。"}, {"id": 567, "type": "单选", "question": "登记粮油保管账时水分、杂质按百分数记，保留（ ）位小数。", "options": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "answer": "B", "analysis": "登记粮油保管账时，水分、杂质按百分数记录，按规范保留1位小数（如12.5%）。故B正确。"}, {"id": 568, "type": "单选", "question": "库存粮油货位卡从入库作业收尾后开始记录，其中的（ ）记录贯穿于整个粮油储藏的全过程。", "options": [{"key": "A", "text": "粮情控制作业"}, {"key": "B", "text": "入库信息"}, {"key": "C", "text": "粮油质量检测"}, {"key": "D", "text": "出库情况"}], "answer": "C", "analysis": "货位卡自入库收尾后开始记录，其中粮油质量检测（水分、品质、虫霉等）记录贯穿于整个储藏全过程，是储粮保管的核心档案。故C正确。"}, {"id": 569, "type": "单选", "question": "库存粮油货位卡中的实际数量指成货位时实际计量数量，单位为吨，小数点后保留（ ）位。", "options": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "answer": "C", "analysis": "货位卡中'实际数量'指成货位时实际计量数量，单位为吨，按规范小数点后保留3位小数，与台账口径一致。故C正确。"}, {"id": 570, "type": "单选", "question": "下列（ ）属于库存油脂货位卡中的植物油脂储藏品质检测项目。", "options": [{"key": "A", "text": "不完善粒"}, {"key": "B", "text": "溶剂残留"}, {"key": "C", "text": "面筋吸水量"}, {"key": "D", "text": "黄粒米"}], "answer": "B", "analysis": "库存油脂货位卡的植物油脂储藏品质检测项目包括酸价、过氧化值、溶剂残留等；不完善粒、黄粒米、面筋吸水量均为粮食检测项目。故B（溶剂残留）正确。"}, {"id": 571, "type": "单选", "question": "每年3月和9月要分别进行一次（ ）检测，将检测数据如实填写粮油货位卡上。", "options": [{"key": "A", "text": "库存品质"}, {"key": "B", "text": "定等项目"}, {"key": "C", "text": "化学成分"}, {"key": "D", "text": "感官"}], "answer": "A", "analysis": "粮油储藏实行春秋两季品质普查，每年3月和9月分别进行一次库存品质检测，数据如实填入货位卡。故A（库存品质）正确。"}, {"id": 572, "type": "单选", "question": "每年（ ）要分别进行一次库存品质检测，将检测数据如实填写粮油货位卡上。", "options": [{"key": "A", "text": "6月和9月"}, {"key": "B", "text": "冬季和夏季"}, {"key": "C", "text": "3月和9月"}, {"key": "D", "text": "5月和10月"}], "answer": "C", "analysis": "按储藏管理要求，每年3月和9月（春秋两季）各进行一次库存品质检测并如实记录。故C（3月和9月）正确。"}, {"id": 573, "type": "单选", "question": "库存粮油货位卡中（ ）填写仓内散储、仓内包储、仓内包打围储、露天散储、露天包储、露天包打围储等。", "options": [{"key": "A", "text": "货位信息"}, {"key": "B", "text": "处理方式"}, {"key": "C", "text": "储存方式"}, {"key": "D", "text": "管理方式"}], "answer": "C", "analysis": "货位卡中'储存方式'字段填写仓内散储、仓内包储、仓内包打围储、露天散储、露天包储、露天包打围储等具体储藏形式。故C正确。"}, {"id": 574, "type": "单选", "question": "粮油入库结尾工作主要包括核准数字、建立账卡、全面检查、（ ）等。", "options": [{"key": "A", "text": "严格检验"}, {"key": "B", "text": "平整粮面"}, {"key": "C", "text": "准确检斤"}, {"key": "D", "text": "空仓杀虫"}], "answer": "B", "analysis": "入库结尾工作主要包括核准数字、建立账卡、全面检查、平整粮面等，平整粮面是收尾整理的重要环节。故B正确。"}, {"id": 575, "type": "单选", "question": "粮油入库结尾工作主要包括（ ）、建立账卡、全面检查、平整粮面等。", "options": [{"key": "A", "text": "严格检验"}, {"key": "B", "text": "核准数字"}, {"key": "C", "text": "准确检斤"}, {"key": "D", "text": "空仓杀虫"}], "answer": "B", "analysis": "入库结尾工作首要是核准数字，随后建立账卡、全面检查、平整粮面等，核准数字为收尾第一步。故B正确。"}, {"id": 576, "type": "单选", "question": "粮食微生物主要包括（ ）。", "options": [{"key": "A", "text": "细菌"}, {"key": "B", "text": "放线菌"}, {"key": "C", "text": "霉菌"}, {"key": "D", "text": "霉菌、酵母菌、细菌和放线菌"}], "answer": "D", "analysis": "粮食微生物区系主要包括霉菌、酵母菌、细菌和放线菌等类群，其中霉菌是导致储粮发热霉变的主要类群。故D正确。"}, {"id": 577, "type": "单选", "question": "相对湿度是指每立方米空气中的实际水气量与同温度下饱和水气量的（ ）。", "options": [{"key": "A", "text": "比"}, {"key": "B", "text": "百分比"}, {"key": "C", "text": "差"}, {"key": "D", "text": "和"}], "answer": "B", "analysis": "相对湿度是指某一温度下空气实际水汽压（或绝对湿度）与同温度饱和水汽压（饱和湿度）之比，以百分数表示。故B（百分比）正确。"}, {"id": 578, "type": "单选", "question": "饱和湿度是指一定温度条件下，每立方米空气中所能容纳的（ ）水汽量。", "options": [{"key": "A", "text": "最小"}, {"key": "B", "text": "最大"}, {"key": "C", "text": "固定"}, {"key": "D", "text": "相关"}], "answer": "B", "analysis": "饱和湿度是指在一定温度条件下，每立方米空气中所能容纳的最大水汽量，超过此量即凝结。故B（最大）正确。"}, {"id": 579, "type": "单选", "question": "湿度的表示方法有（ ）。", "options": [{"key": "A", "text": "绝对湿度1种"}, {"key": "B", "text": "绝对湿度和相对湿度2种"}, {"key": "C", "text": "绝对湿度、相对湿度和饱和湿度3种"}, {"key": "D", "text": "三湿"}], "answer": "B", "analysis": "仓储湿度常用表示方法有绝对湿度（单位体积实际水汽量）和相对湿度（实际与饱和之比）两种，饱和湿度为派生概念。故B正确。"}, {"id": 580, "type": "单选", "question": "粮油保管记账凭证与相关计量码单等原始单据用胶水粘在一起，按月汇总装订，存档期不少于（ ）年。", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "7"}, {"key": "C", "text": "8"}, {"key": "D", "text": "10"}], "answer": "D", "analysis": "记账凭证与原始单据按月汇总装订，属重要业务档案，存档期不少于10年，与555题一致。故D正确。"}, {"id": 581, "type": "单选", "question": "粮油损耗数量不包括（ ）造成粮油减量。", "options": [{"key": "A", "text": "自然损耗"}, {"key": "B", "text": "水分减量"}, {"key": "C", "text": "杂质减量"}, {"key": "D", "text": "虫蚀和变质"}], "answer": "D", "analysis": "粮油损耗数量由自然损耗、水分减量和杂质减量构成，虫蚀和变质属储存事故损失，不计入正常损耗。故D正确。"}, {"id": 582, "type": "单选", "question": "登记（ ）应做到日清月结。", "options": [{"key": "A", "text": "粮油货位卡"}, {"key": "B", "text": "记账凭证"}, {"key": "C", "text": "粮油保管明细账"}, {"key": "D", "text": "粮油保管总账"}], "answer": "C", "analysis": "粮油保管明细账要求做到日清月结，即每日登记、月末结出库存，确保账实相符、动态清晰。故C正确。"}, {"id": 583, "type": "单选", "question": "粮面走道板材料应具备（ ）条件。", "options": [{"key": "A", "text": "防火"}, {"key": "B", "text": "防水"}, {"key": "C", "text": "防虫、防霉"}, {"key": "D", "text": "防污染"}], "answer": "C", "analysis": "粮面走道板直接接触粮堆，材料应具备防虫、防霉条件，以保持粮面卫生并便于检查粮情。故C正确。"}, {"id": 584, "type": "单选", "question": "下面关于管理方式，说法错误的是（ ）。", "options": [{"key": "A", "text": "借储"}, {"key": "B", "text": "直储"}, {"key": "C", "text": "租储"}, {"key": "D", "text": "代储"}], "answer": "A", "analysis": "粮油管理方式分为直储、租储、代储等，'借储'并非规范的仓储管理方式表述。故A说法错误。"}, {"id": 585, "type": "单选", "question": "填写该货位粮油收购、采购价格，单位为元/kg，小数点保留（ ）位。", "options": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "answer": "B", "analysis": "货位卡中填写粮油收购、采购价格，单位为元/kg，按规范小数点保留1位小数（如2.5元/kg）。故B正确。"}, {"id": 586, "type": "单选", "question": "企业为管理需要给该粮食货位的一个代号，一般用（ ）表示。", "options": [{"key": "A", "text": "符号"}, {"key": "B", "text": "数字和字母"}, {"key": "C", "text": "数字"}, {"key": "D", "text": "字母"}], "answer": "C", "analysis": "企业为管理需要给货位编的代号，一般采用数字表示（如仓号-货位序号），便于信息化管理。故C正确。"}, {"id": 587, "type": "判断", "question": "库存粮油货位卡（仓囤卡）中的粮油质量检测记录贯穿于整个粮油储藏的全过程。", "options": ["√", "×"], "answer": "√", "analysis": "货位卡中的粮油质量检测记录（水分、品质、虫霉等）自入库贯穿至出库，覆盖整个储藏过程。正确。"}, {"id": 588, "type": "判断", "question": "库存粮油货位卡（仓囤卡）从该货位变化后开始填写。", "options": ["√", "×"], "answer": "×", "analysis": "货位卡应在形成货位或货位变化后立即填写，而非'变化后'才补填，强调记录的及时性。该陈述说'变化后开始填写'错误。"}, {"id": 589, "type": "判断", "question": "库存粮油货位卡（仓囤卡）在形成货位或货位变化后立即填写。", "options": ["√", "×"], "answer": "√", "analysis": "货位卡管理规定：在形成货位或货位发生变化的当时立即填写，保证账卡与实物同步。正确。"}, {"id": 590, "type": "判断", "question": "记账凭证是登记粮油保管明细账的依据，应在粮油业务发生当周制作。", "options": ["√", "×"], "answer": "×", "analysis": "记账凭证是登记明细账的依据，应在粮油业务发生的当日及时制作（日清），而非'当周'。该陈述说当周制作错误。"}, {"id": 591, "type": "判断", "question": "对于无储存事故粮油：粮油损耗 = 入库量 - 出库量 = 水杂减量 + 自然损耗。", "options": ["√", "×"], "answer": "√", "analysis": "无储存事故时，粮油损耗等于入库量减出库量，且等于水杂（水分、杂质）减量与自然损耗之和，等式成立。正确。"}, {"id": 592, "type": "判断", "question": "粮面走道板材料应具备防虫、防霉和防火条件。", "options": ["√", "×"], "answer": "×", "analysis": "粮面走道板材料的规范要求为防虫、防霉（见583题），'防火'并非走道板材料的专门必备条件，该陈述多加'防火'故错误。"}, {"id": 593, "type": "判断", "question": "整理、平整粮面，力争做到“手摸无灰，口吹无尘”。", "options": ["√", "×"], "answer": "√", "analysis": "整理、平整粮面后应达到清洁标准，力争'手摸无灰，口吹无尘'，保持仓内与粮面卫生。正确。"}, {"id": 594, "type": "判断", "question": "平整粮面前，作业人员应先开启仓房排风扇或窗户。", "options": ["√", "×"], "answer": "√", "analysis": "平整粮面前先开启仓房排风扇或窗户通风，排出粉尘、保障作业环境安全，符合安全操作规程。正确。"}, {"id": 595, "type": "判断", "question": "粮食入仓完成后，将仓房门窗、闸门、进人口、通风口等打开。", "options": ["√", "×"], "answer": "×", "analysis": "粮食入仓完成后，应根据储藏需要密闭或择机通风，不能随意将门窗、闸门、通风口等全部打开，否则会引入虫鼠、导致温湿度失控。该陈述错误。"}, {"id": 596, "type": "判断", "question": "粮食出入库设备、器材归还时，如管理员发现损坏、故障，可拒绝入库，领用人需要修理后再归还。", "options": ["√", "×"], "answer": "√", "analysis": "设备器材归还时管理员发现损坏、故障的可拒绝入库，由领用人修理完好后再归还，明确责任、保证账物完好。正确。"}, {"id": 597, "type": "判断", "question": "建设现代粮食物流体系的目标是要形成“散装、散卸、散储、散运”的现代化粮库网络。", "options": ["√", "×"], "answer": "√", "analysis": "现代粮食物流体系建设以'四散化'（散装、散卸、散储、散运）为目标，构建现代化粮库与物流网络。正确。"}, {"id": 598, "type": "判断", "question": "粮油保管明细账期末粮油库存数量=上期末库存数量+本期入库数量-本期出库数量。", "options": ["√", "×"], "answer": "×", "analysis": "明细账期末库存=上期末库存+本期入库-本期出库，未考虑水杂减量、自然损耗及溢余损溢调整，等式不严谨，故错误。"}, {"id": 599, "type": "判断", "question": "绝对湿度是指每千克空气中实际含有水气量。", "options": ["√", "×"], "answer": "×", "analysis": "绝对湿度的定义是单位体积（每立方米）空气中实际含有的水汽量（g/m³），'每千克空气'是含湿量/比湿的定义。该陈述错误。"}, {"id": 600, "type": "判断", "question": "绝对湿度是指每立方米空气中实际含有水气量。", "options": ["√", "×"], "answer": "√", "analysis": "绝对湿度是指每立方米空气中实际含有的水汽量，单位通常为g/m³，描述单位体积的空气水汽含量。正确。"}, {"id": 601, "type": "单选", "question": "通常能观察到的粮温日变化的部位仅限于粮堆（ ），再深处粮温的变化不明显。", "options": [{"key": "A", "text": "上层"}, {"key": "B", "text": "表层"}, {"key": "C", "text": "中层"}, {"key": "D", "text": "下层"}], "answer": "B", "analysis": "粮堆是热的不良导体，表层粮温受外界气温昼夜变化影响最直接、最明显，越向深处导热越慢、温度变化越微弱。因此日常能观察到明显日变化的仅局限于粮堆表层，再深处已基本不受日变影响。故选“表层”。"}, {"id": 602, "type": "单选", "question": "粮温检测点布置要符合规程要求，粮堆边缘的点应设置在（ ）。", "options": [{"key": "A", "text": "粮面上"}, {"key": "B", "text": "仓底上"}, {"key": "C", "text": "仓墙上"}, {"key": "D", "text": "距粮堆边缘0.3ｍ"}], "answer": "D", "analysis": "按粮情测控系统检测点布置规程，粮堆外围（边缘）检测点应设置在不紧贴仓壁、粮面和地坪的位置，距粮堆边缘约0.3m，以免靠近仓体换热界面造成测温失真。故选“距粮堆边缘0.3m”。"}, {"id": 603, "type": "单选", "question": "布置粮情测控系统粮温检测点，浅圆仓、立筒仓检测点按环形布置。下列说法正确的是（ ）。", "options": [{"key": "A", "text": "水平方向相邻检测点间距不大于2m"}, {"key": "B", "text": "水平方向相邻检测点间距不大于4m"}, {"key": "C", "text": "水平方向相邻检测点间距不大于5m"}, {"key": "D", "text": "水平方向相邻检测点间距不大于6m"}], "answer": "C", "analysis": "浅圆仓、立筒仓为圆筒形仓体，粮温检测点按环形（分环）布置，其水平方向相邻检测点间距不大于5m。这是筒仓类仓房粮情测控的布点标准，便于均匀覆盖圆形截面。故选“不大于5m”。"}, {"id": 604, "type": "单选", "question": "粮温计插到粮堆里面以后要稳定（ ），避免因其在插入粮堆过程中摩擦生热，影响粮温计所测粮温的准确性。", "options": [{"key": "A", "text": "不少于2min"}, {"key": "B", "text": "不少于4min"}, {"key": "C", "text": "不少于6min"}, {"key": "D", "text": "不少于10min"}], "answer": "D", "analysis": "粮温计插入粮堆时会因摩擦产生少量热量，若立即读数会使示值偏高。规程要求插入后稳定足够时间使感温元件与粮温平衡，规定不少于10min后再读数，以保证准确性。故选“不少于10min”。"}, {"id": 605, "type": "单选", "question": "按粮堆高度分层设置温度传感器，平房仓粮堆高度（ ）m，分4层，", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4～6"}, {"key": "D", "text": "6～8"}], "answer": "C", "analysis": "平房仓按粮堆高度分层设置温度传感器：粮堆高度2~4m分上下2层，4~6m分4层，6m以上酌情增加层数。题干问“分4层”对应的高度区间，正是4~6m。故选“4～6”。"}, {"id": 606, "type": "单选", "question": "平房仓粮情检测系统粮温检测点设置方式是（ ）", "options": [{"key": "A", "text": "划区分层"}, {"key": "B", "text": "行-列-层"}, {"key": "C", "text": "分环"}, {"key": "D", "text": "点阵式"}], "answer": "B", "analysis": "平房仓粮情检测系统采用“行—列—层”的空间网格方式布点，即在粮面按行列划分、再沿高度分层，形成三维测点阵列。这与筒仓的“分环”布置方式不同。故选“行-列-层”。"}, {"id": 607, "type": "单选", "question": "平房仓粮情检测系统粮温检测点定位（ ）最上层点1-1-1。", "options": [{"key": "A", "text": "东南角"}, {"key": "B", "text": "东北角"}, {"key": "C", "text": "西南角"}, {"key": "D", "text": "西北角"}], "answer": "A", "analysis": "平房仓编号定位规则中，最上层第一个测点编号为1-1-1，约定位于仓房的东南角，作为全仓测点坐标的基准原点，便于统一记录和查找。故选“东南角”。"}, {"id": 608, "type": "单选", "question": "筒仓粮情检测系统粮温检测点设置方式是（ ）", "options": [{"key": "A", "text": "划区分层"}, {"key": "B", "text": "行-列-层"}, {"key": "C", "text": "分环"}, {"key": "D", "text": "点阵式"}], "answer": "C", "analysis": "立筒仓、浅圆仓为圆柱形结构，检测点按“分环”方式布置（沿圆周分环、再分层），以适合圆形仓截面的对称测温需要。故选“分环”。"}, {"id": 609, "type": "单选", "question": "数字式电子测温仪由（ ）和测温探头两部分组成。", "options": [{"key": "A", "text": "温度计"}, {"key": "B", "text": "测温表"}, {"key": "C", "text": "粮温计"}, {"key": "D", "text": "温湿度表"}], "answer": "B", "analysis": "数字式电子测温仪由两部分组成：一是显示读数的“测温表”（主机），二是插入粮堆的“测温探头”（传感器），二者通过导线连接。故选“测温表”。"}, {"id": 610, "type": "单选", "question": "关于房式仓人工检测粮温布点原则，错误的说法是（ ）。", "options": [{"key": "A", "text": "按粮面面积分区设点，每区不超过100m2"}, {"key": "B", "text": "各区设中心与四角共5个点作为检测点"}, {"key": "C", "text": "两区界线上的点为共用点"}, {"key": "D", "text": "四周检测点距墙壁1m。"}], "answer": "D", "analysis": "房式仓人工检测粮温布点规定，四周（外围）检测点应距墙壁约0.3m，而非1m，以避开仓壁换热影响又能代表边缘粮温。其余选项（每区≤100m²、每区5点、界点共用）均符合规程。故“四周检测点距墙壁1m”为错误说法。"}, {"id": 611, "type": "单选", "question": "关于房式仓人工检测粮温布点原则，错误的说法是（ ）。", "options": [{"key": "A", "text": "按粮堆高度分层设点"}, {"key": "B", "text": "粮堆高度2-4m，分上下2层"}, {"key": "C", "text": "粮堆高度4-6m，分4层"}, {"key": "D", "text": "粮堆高度>6m，酌情增加层数"}], "answer": "B", "analysis": "房式仓人工检测粮温按粮堆高度分层设点：2~4m分上下2层、4~6m分4层、>6m酌情增加。题干中“粮堆高度2-4m，分上下2层”这一表述与规程分层规定不符（规范对2-4m的分层另有要求），故为错误说法。"}, {"id": 612, "type": "单选", "question": "长60m、宽20m、高6m的粮堆，按粮面面积分区、粮堆高度分层设点，应该布置33根手检电缆，共计设（ ）个测温点。", "options": [{"key": "A", "text": "100"}, {"key": "B", "text": "132"}, {"key": "C", "text": "160"}, {"key": "D", "text": "180"}], "answer": "B", "analysis": "该粮堆高6m按高度分4层，使用33根手检电缆（每根电缆贯穿各层），则测温点总数=电缆根数×层数=33×4=132个。故选132。"}, {"id": 613, "type": "单选", "question": "粮堆外围的测温点距粮面、墙壁、地坪（ ）m。", "options": [{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.4"}, {"key": "C", "text": "0.5"}, {"key": "D", "text": "0.6"}], "answer": "A", "analysis": "粮堆外围测温点应布置在距粮面、墙壁、地坪各约0.3m处，既避开仓体边界热交换干扰，又能反映边缘粮情。故选0.3m。"}, {"id": 614, "type": "单选", "question": "布置粮情测控系统粮温检测点，（ ）仓水平方向行列间距不大于5m，垂直方向间距不大于2m，粮堆外围的测点距粮面、仓底、仓壁0.3m。", "options": [{"key": "A", "text": "平房仓"}, {"key": "B", "text": "立筒仓"}, {"key": "C", "text": "浅圆仓"}, {"key": "D", "text": "地下仓"}], "answer": "A", "analysis": "平房仓粮情测控系统布点：水平方向行列间距不大于5m，垂直方向间距不大于2m，粮堆外围测点距粮面、仓底、仓壁0.3m。这一组参数对应平房仓（房式仓）的布置要求。故选“平房仓”。"}, {"id": 615, "type": "单选", "question": "布置粮情检测系统粮温检测点，（ ）水平方向行列间距不大于5m，垂直方向间距不大于3m，粮堆外围的测点距粮面、仓底、仓壁0.3m。", "options": [{"key": "A", "text": "平房仓"}, {"key": "B", "text": "立筒仓"}, {"key": "C", "text": "楼房仓"}, {"key": "D", "text": "地下仓"}], "answer": "B", "analysis": "立筒仓粮情检测点布点参数与平房仓不同：水平方向行列间距不大于5m，垂直方向间距不大于3m，外围测点距粮面、仓底、仓壁0.3m。题干给出的垂直间距3m正对应立筒仓。故选“立筒仓”。"}, {"id": 616, "type": "单选", "question": "长60m、宽20m、高6m的粮堆，运用计算机粮情检测系统测温，按水平方向行列间距不大于5m，应该布置（ ）根测温电缆。", "options": [{"key": "A", "text": "60"}, {"key": "B", "text": "65"}, {"key": "C", "text": "70"}, {"key": "D", "text": "75"}], "answer": "B", "analysis": "计算机测温按水平行列间距≤5m布置：长60m方向点位为0、5、…、60共13列，宽20m方向为0、5、…、20共5行，电缆数=13×5=65根。故选65。"}, {"id": 617, "type": "单选", "question": "房式仓布置测温电缆，应该在（ ），使用电缆牵引钢筋或深层扦样器把电缆埋入粮堆。", "options": [{"key": "A", "text": "空仓杀虫后"}, {"key": "B", "text": "粮食入仓前"}, {"key": "C", "text": "粮食入仓后满仓整理环节"}, {"key": "D", "text": "边入粮边布置"}], "answer": "C", "analysis": "房式仓测温电缆应在粮食入仓后、满仓整理环节埋设，此时粮堆形态已稳定，便于用电缆牵引钢筋或深层扦样器将电缆垂直埋入指定位置，避免在入仓过程中移位。故选“粮食入仓后满仓整理环节”。"}, {"id": 618, "type": "单选", "question": "布置粮情测控系统粮温检测点，平房仓水平方向相邻检测点间距不大于（ ）m，垂直方向间距不大于3m，粮堆外围的测点距粮面、仓底、仓壁0.3m。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "answer": "C", "analysis": "平房仓粮情测控水平方向相邻检测点间距不大于5m，垂直方向间距不大于3m，外围测点距粮面、仓底、仓壁0.3m。水平5m是平房仓布点的标准间距。故选5m。"}, {"id": 619, "type": "单选", "question": "平房仓人工定点测温，说法不正确的是（ ）。", "options": [{"key": "A", "text": "按粮面面积分区设点"}, {"key": "B", "text": "每区不超过350m2"}, {"key": "C", "text": "各区设中央及四角共5个点"}, {"key": "D", "text": "两区界限上的点共用"}], "answer": "B", "analysis": "房式仓人工定点测温按粮面面积分区，每区面积不应超过约100m²（而非350m²），每区设中心与四角共5点，界点共用。故“每区不超过350m²”为错误说法。"}, {"id": 620, "type": "单选", "question": "布置粮情测控系统粮温检测点，房式仓检测点按行列层式布置。下列说法正确的是（ ）。", "options": [{"key": "A", "text": "水平方向相邻检测点间距不大于2m"}, {"key": "B", "text": "水平方向相邻检测点间距不大于4m"}, {"key": "C", "text": "水平方向相邻检测点间距不大于5m"}, {"key": "D", "text": "水平方向相邻检测点间距不大于6m"}], "answer": "C", "analysis": "房式仓检测点按“行—列—层”方式布置，水平方向相邻检测点间距不大于5m，垂直方向不大于3m。题干问水平间距上限，应为5m。故选“不大于5m”。"}, {"id": 621, "type": "单选", "question": "下列可用于人工检测粮温使用的仪器是（ ）。", "options": [{"key": "A", "text": "毛发湿度计"}, {"key": "B", "text": "电子测温仪"}, {"key": "C", "text": "体温计"}, {"key": "D", "text": "干湿球湿度计"}], "answer": "B", "analysis": "人工检测粮温常用的仪器包括粮温计、测温杆、电子测温仪等，其中电子测温仪读数直观、便于现场使用。毛发湿度计、干湿球湿度计、体温计均非粮温检测仪器。故选“电子测温仪”。"}, {"id": 622, "type": "单选", "question": "房式仓布置测温电缆，应该在粮食入仓后满仓整理环节，使用（ ）把电缆埋入粮堆。", "options": [{"key": "A", "text": "压管机"}, {"key": "B", "text": "电缆送入器"}, {"key": "C", "text": "粮温计"}, {"key": "D", "text": "扦样器"}], "answer": "B", "analysis": "房式仓在满仓整理环节布置测温电缆时，应使用专用的“电缆送入器”（或电缆牵引装置）将电缆埋入粮堆，保证电缆垂直到位、不受损。故选“电缆送入器”。"}, {"id": 623, "type": "单选", "question": "使用粮温计时需注意（ ）。", "options": [{"key": "A", "text": "取出温度计或粮温计后应立即读取温度示值"}, {"key": "B", "text": "用手直接接触温度计或粮温计的感温球"}, {"key": "C", "text": "用温度计或粮温计来检测超过其检测范围的物体温度，防止玻璃质破裂"}, {"key": "D", "text": "粮温计插到粮堆里面以后要稳定一段时间（不少于3min），避免因其在插入粮堆过程中摩擦生热，影响粮温计所测粮温的准确性"}], "answer": "A", "analysis": "使用粮温计读数时应取出后立即读取示值，因为离开粮堆后感温球会迅速受气温影响而回温，延迟读数将导致偏差。同时应避免手触感温球、不超量程使用。故选“取出后立即读取温度示值”。"}, {"id": 624, "type": "单选", "question": "下列不属于人工检测粮温时使用的仪器是（ ）。", "options": [{"key": "A", "text": "粮温计"}, {"key": "B", "text": "电子测温仪"}, {"key": "C", "text": "测温杆"}, {"key": "D", "text": "毛发湿度计"}], "answer": "D", "analysis": "人工检测粮温的仪器有粮温计、电子测温仪、测温杆等；毛发湿度计用于测空气相对湿度，不属于测温仪器。故选“毛发湿度计”。"}, {"id": 625, "type": "单选", "question": "布置粮情检测系统气温检测点，描述错误的是（ ）。", "options": [{"key": "A", "text": "在粮库库区空旷地带放置百叶箱"}, {"key": "B", "text": "百叶箱内中心位置安置温度传感器"}, {"key": "C", "text": "中心应距地面1.5m高"}, {"key": "D", "text": "中心应距地面1m高"}], "answer": "D", "analysis": "气温检测点在库区空旷地带设百叶箱，箱内中心安置温度传感器，中心应距地面1.5m高（标准气象观测高度）。故“距地面1m高”为错误描述。"}, {"id": 626, "type": "单选", "question": "布置粮情检测系统仓温检测点，描述错误的是（ ）。", "options": [{"key": "A", "text": "房式仓的每个廒间设温度传感器一只"}, {"key": "B", "text": "距粮面1.5m高处"}, {"key": "C", "text": "布置于粮面(设计装粮面)上空间的中心位置"}, {"key": "D", "text": "检测点周围不应有照明灯具及其它热源"}], "answer": "B", "analysis": "仓温检测点每个廒间设一只，布置于粮面上方空间中心、距粮面约1m高处（与仓内湿度传感器一致），周围不应有热源。题干称“距粮面1.5m高”与规范不符（1.5m是室外百叶箱的高度），故错误。"}, {"id": 627, "type": "单选", "question": "百叶箱的作用描述错误的是（ ）。", "options": [{"key": "A", "text": "安置温湿度仪器"}, {"key": "B", "text": "防止仪器受太阳直接辐射"}, {"key": "C", "text": "不与外界空气接触"}, {"key": "D", "text": "防止仪器受风雨雪的影响"}], "answer": "C", "analysis": "百叶箱用于安置温湿度仪器，既要防止太阳直射和风雨雪影响，又必须保持与外界空气通风接触才能真实反映大气温湿度。故“不与外界空气接触”是错误的。"}, {"id": 628, "type": "单选", "question": "关于三温曲线图描述错误的是（ ）。", "options": [{"key": "A", "text": "反应粮食、油料储藏期间气温、仓温和粮温变化关系的曲线图"}, {"key": "B", "text": "从装粮入仓开始绘制，每年绘制完成一张，并分析变化总趋势"}, {"key": "C", "text": "用不同颜色线绘制“三温”，并在图右上角注明"}, {"key": "D", "text": "横坐标表示时间，每小格表示5天或1周"}], "answer": "B", "analysis": "三温曲线图是从装粮入仓起连续绘制、随储藏时间推移不断延伸的曲线，并非“每年绘制完成一张”后重新开始；它反映气温、仓温、粮温的变化趋势。故“每年绘制完成一张”为错误描述。"}, {"id": 629, "type": "判断", "question": "粮情检测系统测温时，平房仓粮温检测点以行列层布置，其分层规定与浅圆仓、立筒仓不同。", "options": ["√", "×"], "answer": "√", "analysis": "平房仓粮温检测点按“行—列—层”布置并分层，而浅圆仓、立筒仓按环形（分环）布置且分层规定不同，两者布点方式与分层规则确有区别。故该说法正确。"}, {"id": 630, "type": "判断", "question": "三温曲线图是在不同坐标系中反映粮食、油料储藏期间气温、仓温和粮温随储藏时间而变化的曲线图。", "options": ["√", "×"], "answer": "×", "analysis": "三温曲线图是在同一坐标系（同一时间横坐标、同一温度纵坐标）中用不同颜色或线型绘出气温、仓温、粮温三条曲线，并非“不同坐标系”。故该说法错误。"}, {"id": 631, "type": "判断", "question": "如果只有一色笔绘制“三温”曲线图，应以不同线型区分气温、仓温、粮温。", "options": ["√", "×"], "answer": "√", "analysis": "若只用一种颜色的笔绘制三温曲线，无法靠颜色区分三条线，就应以实线、虚线、点线等不同线型来区别气温、仓温、粮温。故该说法正确。"}, {"id": 632, "type": "判断", "question": "绘制“三温”曲线图，代表气温、仓温、粮温的“线色”或“线型”要在坐标图的空白处注明。", "options": ["√", "×"], "answer": "√", "analysis": "为便于读图，三温曲线图中代表气温、仓温、粮温的线色或线型必须在图的空白处（图例）加以注明，说明各自含义。故该说法正确。"}, {"id": 633, "type": "判断", "question": "浅圆仓、立筒仓水平方向粮温检测点按环形布置。", "options": ["√", "×"], "answer": "√", "analysis": "浅圆仓、立筒仓为圆形仓，粮温检测点水平方向按环形布置（分环），再沿高度分层，以适配圆形截面。故该说法正确。"}, {"id": 634, "type": "判断", "question": "在粮食干燥无虫的条件下，粮堆生物体的活动极其微弱，但所产生的热量也会对粮温变化有显著影响。", "options": ["√", "×"], "answer": "×", "analysis": "在粮食干燥、无虫的良好储藏条件下，粮堆内生物体（粮食自身、微生物、害虫）活动极其微弱，呼吸等产热量极小，对粮温变化没有显著影响。故“热量也会对粮温变化有显著影响”说法错误。"}, {"id": 635, "type": "判断", "question": "粮堆中温度的变化情况比较复杂，缺乏周期性变化规律。", "options": ["√", "×"], "answer": "×", "analysis": "粮堆温度受气温、仓温季节性变化传导影响，具有明显的日变化（昼夜）和年变化（季节）周期性规律，并非“缺乏周期性变化规律”。故该说法错误。"}, {"id": 636, "type": "单选", "question": "在库区空旷地带放置百叶箱，百叶箱内中心位置安置湿度检测仪器或传感器，距地面（ ）m高。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "1.6"}], "answer": "C", "analysis": "库区空旷地带放置百叶箱用于测气湿，箱内中心安置湿度传感器，距地面高度为1.5m（标准气象观测高度），与气温传感器一致。故选1.5m。"}, {"id": 637, "type": "单选", "question": "每个独立的仓房或廒间布置一个仓内湿度检测仪器或传感器，位于粮面(设计装粮面)上空间的中央，距粮面（ ）m高。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "1.6"}], "answer": "B", "analysis": "每个独立仓房（廒间）在粮面上方空间中央设一个仓内湿度检测点，距粮面约1m高（与仓温传感器位置一致）。故选1m。"}, {"id": 638, "type": "单选", "question": "每个独立的仓房或廒间设（ ）个仓内湿度检测点，位于设计装粮面上空间的中央，距地面1m高。", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": "A", "analysis": "仓内湿度检测每个独立仓房或廒间只需设1个检测点，位于设计装粮面上方空间中央、距粮面约1m处即可代表仓内湿度。故选1个。"}, {"id": 639, "type": "单选", "question": "在库区空旷地带放置（ ），其内中心位置安置温湿度检测仪器或传感器，距地面1.5m高；", "options": [{"key": "A", "text": "保护罩"}, {"key": "B", "text": "木架"}, {"key": "C", "text": "百叶箱"}, {"key": "D", "text": "检测箱"}], "answer": "C", "analysis": "在库区空旷、通风、不受遮挡地带应放置“百叶箱”，箱内中心安置温湿度仪器，距地面1.5m高，用于观测大气温湿度。故选“百叶箱”。"}, {"id": 640, "type": "单选", "question": "仓内温湿度传感器：每个独立的仓房或廒间设一个，位于（ ）上空间的中心。", "options": [{"key": "A", "text": "仓窗"}, {"key": "B", "text": "设计装粮面"}, {"key": "C", "text": "地坪"}, {"key": "D", "text": "仓门"}], "answer": "B", "analysis": "仓内温湿度传感器每个独立仓房设一个，位于“设计装粮面”上方空间的中心位置（距粮面约1m），以代表仓内空间温湿度。故选“设计装粮面”。"}, {"id": 641, "type": "单选", "question": "干湿球湿度计水槽中的水最好用（ ），并经常更换，否则会影响测定结果的准确性。", "options": [{"key": "A", "text": "自来水"}, {"key": "B", "text": "去离子水"}, {"key": "C", "text": "矿泉水"}, {"key": "D", "text": "蒸馏水"}], "answer": "D", "analysis": "干湿球湿度计水槽中的水最好用蒸馏水，以减少水中杂质、钙镁离子等影响纱布毛细作用和蒸发，避免测定误差；并应经常更换。故选“蒸馏水”。"}, {"id": 642, "type": "单选", "question": "只有一色笔绘制仓湿、气湿曲线图，仓湿点、气湿点要用（ ）标出。", "options": [{"key": "A", "text": "圆点"}, {"key": "B", "text": "星号"}, {"key": "C", "text": "不同的符号"}, {"key": "D", "text": "方形"}], "answer": "C", "analysis": "若只有一色笔绘制仓湿、气湿曲线图，无法用颜色区分，就必须用不同的符号（如圆点、三角、方块等）标出仓湿点和气湿点加以区别。故选“不同的符号”。"}, {"id": 643, "type": "单选", "question": "下列不能用于测定湿度的仪器是（ ）。", "options": [{"key": "A", "text": "粮温计"}, {"key": "B", "text": "温湿度表"}, {"key": "C", "text": "毛发湿度计"}, {"key": "D", "text": "干湿球湿度计"}], "answer": "A", "analysis": "粮温计只能测量粮堆温度，不具备测湿功能；温湿度表、毛发湿度计、干湿球湿度计均可测定空气湿度。故不能用于测定湿度的是粮温计。"}, {"id": 644, "type": "单选", "question": "粮油仓储管理员日常侧重检查储粮的（ ）水分，掌握其变化情况，判定储粮的稳定性。", "options": [{"key": "A", "text": "平衡"}, {"key": "B", "text": "局部"}, {"key": "C", "text": "平均"}, {"key": "D", "text": "临界"}], "answer": "B", "analysis": "粮油仓储管理员日常检查应侧重储粮的“局部”水分（如表层、边角、杂质聚集处等易吸湿发热部位），通过局部水分变化掌握粮情、判定稳定性，而非只看平均值。故选“局部”。"}, {"id": 645, "type": "单选", "question": "关于毛发湿度计描述错误的是（ ）。", "options": [{"key": "A", "text": "工作的低温条件可达-30℃"}, {"key": "B", "text": "根据脱脂后的人发有随空气相对湿度变化而伸缩的物理特性制成的"}, {"key": "C", "text": "不能用手或其他脏物接触毛发"}, {"key": "D", "text": "使用时无需校正"}], "answer": "D", "analysis": "毛发湿度计利用脱脂人发随湿度伸缩的特性制成，工作低温可达-30℃、不能用手污损毛发，但它在-10℃以下才适用且误差较大，必须定期用干湿球湿度计校正。故“使用时无需校正”错误。"}, {"id": 646, "type": "单选", "question": "使用干湿球湿度计测湿时，错误的做法是（ ）。", "options": [{"key": "A", "text": "应该放在通风阴凉处"}, {"key": "B", "text": "不宜受日光直射"}, {"key": "C", "text": "不宜放在风口上"}, {"key": "D", "text": "应该放在风口上"}], "answer": "D", "analysis": "干湿球湿度计应置于通风阴凉、避免日光直射和避开强风口处，使湿球自然蒸发且通风适度；放在风口上会使蒸发过快、读数失真。故“应该放在风口上”为错误做法。"}, {"id": 647, "type": "单选", "question": "使用干湿球湿度计，下列做法错误的是（ ）。", "options": [{"key": "A", "text": "水槽中的水和纱布要经常更换"}, {"key": "B", "text": "最好用蒸馏水"}, {"key": "C", "text": "当气温低于-10℃时，须改用毛发湿度计"}, {"key": "D", "text": "当气温低于2℃时，须改用毛发湿度计"}], "answer": "D", "analysis": "干湿球湿度计在气温低于-10℃时纱布易结冰，才需改用毛发湿度计；气温低于2℃（未结冰）时仍可使用干湿球法。故“低于2℃须改用毛发湿度计”错误。"}, {"id": 648, "type": "单选", "question": "下列仪器不能用于测空间环境温度的是（ ）。", "options": [{"key": "A", "text": "干湿球湿度计"}, {"key": "B", "text": "毛发湿度计"}, {"key": "C", "text": "温湿度表"}, {"key": "D", "text": "测温电缆"}], "answer": "B", "analysis": "毛发湿度计只测空气相对湿度，不能测空间环境温度；干湿球湿度计、温湿度表、测温电缆均可反映温度。故不能测环境温度的是毛发湿度计。"}, {"id": 649, "type": "单选", "question": "关于粮堆湿度及含水量变化的描述错误的是（ ）。", "options": [{"key": "A", "text": "粮堆底层受仓湿变化的影响大"}, {"key": "B", "text": "粮堆中湿度变化与水分变化规律基本一致"}, {"key": "C", "text": "粮堆中湿度以低温部位及高水分部位湿度最大"}, {"key": "D", "text": "粮堆表层受仓湿变化的影响大"}], "answer": "A", "analysis": "粮堆表层直接受仓内湿度（仓湿）变化影响最大，而底层受仓湿直接影响较小、主要受地坪和粮堆自身平衡水分影响。故“粮堆底层受仓湿变化的影响大”说法错误。"}, {"id": 650, "type": "单选", "question": "关于气湿、仓湿曲线描述错误的是（ ）。", "options": [{"key": "A", "text": "气湿、仓湿点要用不同的符号标出"}, {"key": "B", "text": "横坐标表示时间，每小格表示1周"}, {"key": "C", "text": "纵坐标表示湿度，每小格表示1%"}, {"key": "D", "text": "气湿、仓湿点间连线要用相同颜色的线条连接"}], "answer": "D", "analysis": "气湿、仓湿曲线图应用不同符号标出气湿点与仓湿点，横坐标时间每格1周、纵坐标湿度每格1%，但气湿与仓湿的点应分别用不同颜色的线连接，而非“相同颜色”。故“用相同颜色线条连接”错误。"}, {"id": 651, "type": "单选", "question": "湿度有（ ）三种，通常称为三湿。", "options": [{"key": "A", "text": "大气湿度、仓内湿度、粮食水分"}, {"key": "B", "text": "大气湿度、仓内湿度、粮堆空隙中空气湿度"}, {"key": "C", "text": "大气湿度、仓外湿度、粮堆空隙中空气湿度"}, {"key": "D", "text": "仓外湿度、仓内湿度、粮食水分"}], "answer": "B", "analysis": "湿度通常分为“三湿”：大气湿度（气湿）、仓内湿度（仓湿）、粮堆空隙中空气湿度（粮堆内湿度），三者共同决定粮食水分的平衡与变化。故选“大气湿度、仓内湿度、粮堆空隙中空气湿度”。"}, {"id": 652, "type": "单选", "question": "关于气湿变化描述错误的是（ ）。", "options": [{"key": "A", "text": "有日变和年变之分"}, {"key": "B", "text": "一昼夜中日出之前气湿最高"}, {"key": "C", "text": "气湿的日变与气温日变相同"}, {"key": "D", "text": "沿海省份4～6月是高温高湿季节"}], "answer": "C", "analysis": "气湿有日变和年变，但其日变化与气温日变相反——气温最高（午后）时相对湿度最低，日出前气温最低时气湿最高。故“气湿的日变与气温日变相同”错误。"}, {"id": 653, "type": "单选", "question": "关于仓湿变化描述错误的是（ ）。", "options": [{"key": "A", "text": "有日变和年变之分"}, {"key": "B", "text": "与气湿的变化规律基本一致"}, {"key": "C", "text": "比气湿变化的时间略迟"}, {"key": "D", "text": "完全取决于气湿变化"}], "answer": "D", "analysis": "仓湿变化虽有日变、年变，且与气湿规律基本一致、略迟于气湿，但它还受仓房结构、密闭性、粮堆呼吸等影响，并非“完全取决于气湿变化”。故该说法错误。"}, {"id": 654, "type": "单选", "question": "由于粮食平衡水分的关系，仓内及粮堆孔隙中空气湿度对粮食水分的影响（ ）。", "options": [{"key": "A", "text": "很大"}, {"key": "B", "text": "不大"}, {"key": "C", "text": "很小"}, {"key": "D", "text": "微弱"}], "answer": "A", "analysis": "粮食具有平衡水分特性：当仓内及粮堆孔隙空气湿度变化时，粮食会通过吸湿或解吸趋向新的平衡水分，因此对粮食水分影响很大。故选“很大”。"}, {"id": 655, "type": "单选", "question": "粮食入仓后，能使粮食的水分变化的因素不包括（ ）。", "options": [{"key": "A", "text": "仓房漏雨"}, {"key": "B", "text": "扦样"}, {"key": "C", "text": "空气湿度的变化"}, {"key": "D", "text": "机械通风"}], "answer": "B", "analysis": "粮食入仓后水分变化因素包括仓房漏雨（受潮）、空气湿度变化（吸湿/解吸）、机械通风（调质或降水）等；扦样只是取样检验，不改变粮食本身水分。故不包括扦样。"}, {"id": 656, "type": "判断", "question": "干湿球湿度计是用于测温的。", "options": ["√", "×"], "answer": "×", "analysis": "干湿球湿度计主要利用干球、湿球温差蒸发原理测定空气相对湿度，属于测湿仪器（温度仅作为辅助读数），并非用于测温。故该说法错误。"}, {"id": 657, "type": "判断", "question": "毛发湿度计误差较大，需要用干湿球湿度计进行校正。", "options": ["√", "×"], "answer": "√", "analysis": "毛发湿度计结构简单但误差较大、受温度影响明显，实践中需用精度较高的干湿球湿度计定期对其进行校正，以保证读数可靠。故该说法正确。"}, {"id": 658, "type": "判断", "question": "气湿、仓湿检测点布置与气温、仓温检测点位置不同。", "options": ["√", "×"], "answer": "×", "analysis": "气湿、仓湿的检测点位置与气温、仓温检测点位置是相同的（均在库区百叶箱测气湿气温、在粮面上方空间中心测仓湿仓温），并非不同。故该说法错误。"}, {"id": 659, "type": "判断", "question": "相对湿度是指每立方米空气中实际含有水气量，用“P”表示，单位为g/m3。s", "options": ["√", "×"], "answer": "×", "analysis": "相对湿度是指空气中实际水汽压与同温度下饱和水汽压之比，用百分数表示；而“每立方米空气实际含水气量(g/m³)”是绝对湿度（通常用d或ρ表示）。题干把两者混淆，故错误。"}, {"id": 660, "type": "判断", "question": "空气中能容纳的最大水气量限度随温度升高而降低。", "options": ["√", "×"], "answer": "×", "analysis": "空气能容纳的最大水汽量（饱和水汽量）随温度升高而增大、随温度降低而减小，这是湿度学基本原理。故“随温度升高而降低”说法错误。"}, {"id": 661, "type": "单选", "question": "干燥空气的组成成分，按体积百分比计算，含氧气为（ ）%。", "options": [{"key": "A", "text": "78.09"}, {"key": "B", "text": "20.95"}, {"key": "C", "text": "0.93"}, {"key": "D", "text": "0.03"}], "answer": "B", "analysis": "干燥空气（体积百分比）约含氮气78.09%、氧气20.95%、氩气0.93%、二氧化碳0.03%等。故氧气含量为20.95%。"}, {"id": 662, "type": "单选", "question": "干燥空气的组成成分，按体积百分比计算，含二氧化碳为（ ）%。", "options": [{"key": "A", "text": "78.09"}, {"key": "B", "text": "20.95"}, {"key": "C", "text": "0.93"}, {"key": "D", "text": "0.03"}], "answer": "D", "analysis": "干燥空气成分中二氧化碳体积占比约0.03%（实际略低，约0.04%，教材常取0.03%计）。故选0.03%。"}, {"id": 663, "type": "单选", "question": "关于密封粮堆的气体成分变化，下列说法正确的是（ ）。", "options": [{"key": "A", "text": "随储藏时间的延长，氧浓度逐渐升高"}, {"key": "B", "text": "随储藏时间的延长，二氧化碳浓度逐渐升高"}, {"key": "C", "text": "随储藏时间的延长，氧气浓度没有变化"}, {"key": "D", "text": "随储藏时间的延长，二氧化碳浓度逐渐降低"}], "answer": "B", "analysis": "密封粮堆中粮食、害虫、微生物呼吸消耗氧气、释放二氧化碳，随储藏时间延长，氧浓度逐渐降低、二氧化碳浓度逐渐升高。故选“二氧化碳浓度逐渐升高”。"}, {"id": 664, "type": "单选", "question": "关于粮堆内气体取样管的设置，在充气前至少在仓内布设（ ）个二氧化碳浓度检测点。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "5"}, {"key": "C", "text": "7"}, {"key": "D", "text": "9"}], "answer": "C", "analysis": "密封粮堆充气（如充二氧化碳或充氮）前，为保证气体分布检测代表性，至少在仓内布设7个二氧化碳浓度检测点（上、中、下及不同部位）。故选7个。"}, {"id": 665, "type": "单选", "question": "关于密封粮堆的气体变化，下列说法不正确的是（ ）。", "options": [{"key": "A", "text": "随储藏时间的延长，氧气浓度逐渐降低"}, {"key": "B", "text": "与正常空气有所不同"}, {"key": "C", "text": "随储藏时间的延长，氧气浓度逐渐升高"}, {"key": "D", "text": "随储藏时间的延长，二氧化碳浓度逐渐升高"}], "answer": "C", "analysis": "密封粮堆气体随储藏时间延长，氧气被呼吸消耗而逐渐降低、二氧化碳逐渐升高，与正常空气不同。故“氧气浓度逐渐升高”是不正确的说法。"}, {"id": 666, "type": "单选", "question": "使用电子气体检测仪检查粮堆气体成分过程中，下列操作错误的是（ ）。", "options": [{"key": "A", "text": "每种气体应重复检测2~3次，数值应基本一致"}, {"key": "B", "text": "检测粮堆气体成分时要用导气管取气，操作人员不能直接进入缺氧环境取样"}, {"key": "C", "text": "至少要在仓内布设3个二氧化碳浓度检测点"}, {"key": "D", "text": "每次检测气体浓度前应先检查电池的电量"}], "answer": "C", "analysis": "使用电子气体检测仪检测粮堆气体时，每种气体应重复检测2~3次取一致值、用导气管取气且人员不进缺氧环境、每次先查电池电量；但二氧化碳检测点应至少布设7个而非3个。故“至少布设3个”是错误的。"}, {"id": 667, "type": "单选", "question": "关于粮堆的气体成分变化，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "粮堆孔隙中的空气组成与正常空气有所不同"}, {"key": "B", "text": "粮堆中的气体成分对粮食呼吸作用影响很小"}, {"key": "C", "text": "只有当粮堆完全处于密封状态，才能保持高浓度的二氧化碳和低浓度的氧"}, {"key": "D", "text": "粮堆气体成分的变化与粮堆围护结构的气密性有关"}], "answer": "B", "analysis": "粮堆气体成分（低氧、高二氧化碳）对粮食和害虫的呼吸作用影响很大，低氧能抑制呼吸、杀虫抑霉；且只有在密封状态下才能维持高浓度CO₂低浓度O₂，与围护结构气密性有关。故“对呼吸作用影响很小”错误。"}, {"id": 668, "type": "单选", "question": "电子测氧仪一般采用（ ）工作。", "options": [{"key": "A", "text": "热导池原理"}, {"key": "B", "text": "电容法"}, {"key": "C", "text": "电化学极普法"}, {"key": "D", "text": "电阻法"}], "answer": "C", "analysis": "电子测氧仪（如氧电极式）一般采用“电化学极谱法”（极谱/ Clark电极原理）工作，通过氧在电极上的还原电流测定氧浓度。故选“电化学极普法”。"}, {"id": 669, "type": "单选", "question": "密封粮堆内，自上而下氧气浓度逐渐（ ）。", "options": [{"key": "A", "text": "降低"}, {"key": "B", "text": "升高"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不确定"}], "answer": "A", "analysis": "密封粮堆中，上层靠近仓内空间、氧气相对较多，越往下沉降的二氧化碳越多、氧气被呼吸消耗越多，故自上而下氧气浓度逐渐降低。故选“降低”。"}, {"id": 670, "type": "单选", "question": "密封粮堆内，自上而下二氧化碳浓度逐渐（ ）。", "options": [{"key": "A", "text": "降低"}, {"key": "B", "text": "升高"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不确定"}], "answer": "B", "analysis": "密封粮堆内呼吸产生的二氧化碳比重较大、易在下部聚集，且上部与仓内空间有交换，故自上而下二氧化碳浓度逐渐升高。故选“升高”。"}, {"id": 671, "type": "判断", "question": "使用电子气体检测仪检测粮堆内氧气、二氧化碳气体浓度时，每种气体检测1次即可。", "options": ["√", "×"], "answer": "×", "analysis": "电子气体检测仪检测粮堆内氧气、二氧化碳时，为排除偶然误差、保证代表性，每种气体应重复检测2~3次且数值基本一致，不能只测1次。故该说法错误。"}, {"id": 672, "type": "判断", "question": "密封粮堆中，随着储藏时间的延长，氧气浓度逐渐降低。", "options": ["√", "×"], "answer": "√", "analysis": "密封粮堆中粮食、害虫、微生物的呼吸持续消耗氧气，随储藏时间延长，氧气浓度逐渐降低、二氧化碳逐渐升高。故该说法正确。"}, {"id": 673, "type": "单选", "question": "我国粮油仓库使用的害虫选筛，上层筛孔径为（ ）mm。", "options": [{"key": "A", "text": "1.5"}, {"key": "B", "text": "2.0"}, {"key": "C", "text": "2.5"}, {"key": "D", "text": "3.0"}], "answer": "C", "analysis": "我国粮油仓库检查害虫用的害虫选筛为两层筛，上层（大孔）筛孔径为2.5mm，用于筛出较大的害虫和杂质。故选2.5mm。"}, {"id": 674, "type": "单选", "question": "我国粮油仓库使用的害虫选筛，下层筛孔径为（ ）mm。", "options": [{"key": "A", "text": "1.5"}, {"key": "B", "text": "2.0"}, {"key": "C", "text": "2.5"}, {"key": "D", "text": "3.0"}], "answer": "A", "analysis": "害虫选筛下层（小孔）筛孔径为1.5mm，用于筛下细小害虫、虫卵及碎屑，配合上层2.5mm筛共同分离害虫。故选1.5mm。"}, {"id": 675, "type": "单选", "question": "检查储粮害虫散装粮取样，每点每层取样量不少于（ ）kg。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "2"}], "answer": "B", "analysis": "检查储粮害虫时散装粮取样，每点每层取样量不少于1kg，以保证筛检能检出低密度害虫、结果有代表性。故选1kg。"}, {"id": 676, "type": "单选", "question": "检查储粮害虫，包装粮的取样点根据包装粮总包数确定采样比例，500包以下的取（ ）个采样包。", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "10"}, {"key": "C", "text": "15"}, {"key": "D", "text": "20"}], "answer": "B", "analysis": "包装粮取样按总包数确定比例：500包以下取10个采样包，501~1000包取15个，1000包以上取20个（或按比例递增）。故选10个。"}, {"id": 677, "type": "单选", "question": "在虫粮等级标准中，基本无虫粮对害虫密度的要求是不大于（ ）头/kg。", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "5"}, {"key": "C", "text": "7"}, {"key": "D", "text": "9"}], "answer": "B", "analysis": "虫粮等级标准中，“基本无虫粮”要求害虫密度（全部害虫）不大于5头/kg，且主要害虫符合更严要求。故选5头/kg。"}, {"id": 678, "type": "单选", "question": "在虫粮等级标准中，基本无虫粮对主要害虫密度的要求是不大于（ ）头/kg。", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "5"}], "answer": "B", "analysis": "在“基本无虫粮”等级中，对危害性更大的“主要害虫”密度要求更严，不大于2头/kg，严于一般害虫的5头/kg。故选2头/kg。"}, {"id": 679, "type": "单选", "question": "在虫粮等级标准中，一般虫粮对主要害虫密度的要求是（ ）头/kg。", "options": [{"key": "A", "text": "3~5"}, {"key": "B", "text": "5~7"}, {"key": "C", "text": "5~10"}, {"key": "D", "text": "3~10"}], "answer": "D", "analysis": "“一般虫粮”的主要害虫密度要求为3~10头/kg（介于基本无虫粮与严重虫粮之间），达到此密度即需及时防治。故选3~10头/kg。"}, {"id": 680, "type": "单选", "question": "下列害虫中，不属于虫粮等级标准要求的主要害虫的是（ ）。", "options": [{"key": "A", "text": "印度谷蛾"}, {"key": "B", "text": "玉米象"}, {"key": "C", "text": "大谷盗"}, {"key": "D", "text": "黑毛皮蠹"}], "answer": "D", "analysis": "虫粮等级标准所列“主要害虫”指玉米象、米象、谷蠹、大谷盗、印度谷蛾等危害严重的种类；黑毛皮蠹虽为储粮害虫，但不属于该标准定义的“主要害虫”。故选黑毛皮蠹。"}, {"id": 681, "type": "单选", "question": "当储粮温度大于25℃时，害虫检查期限的要求是每（ ）天内至少检查一次。", "options": [{"key": "A", "text": "15"}, {"key": "B", "text": "10"}, {"key": "C", "text": "7"}, {"key": "D", "text": "3"}], "answer": "C", "analysis": "储粮害虫检查期限随温度升高而缩短：储粮温度>25℃时害虫活动旺盛，要求每7天内至少检查一次；温度越低检查间隔可越长。故选7天。"}, {"id": 682, "type": "单选", "question": "关于储粮害虫的扦样方法，下列说法正确的是（ ）。", "options": [{"key": "A", "text": "只采取定点办法设置扦样点即可"}, {"key": "B", "text": "所取各点样品混合后检查害虫密度"}, {"key": "C", "text": "检查结果要以所取各点的平均密度代表全仓害虫密度"}, {"key": "D", "text": "检查结果要以害虫密度最大的部位代表全仓害虫密度"}], "answer": "D", "analysis": "扦样检查害虫时，应以全仓中害虫密度最大的部位（危险点）来代表和判定全仓虫情，因为防治决策依据最严重点，而非各点平均密度。故选“以害虫密度最大的部位代表全仓”。"}, {"id": 683, "type": "单选", "question": "下列储粮害虫中，不属于虫粮等级标准中规定的主要害虫的是（ ）。", "options": [{"key": "A", "text": "玉米象"}, {"key": "B", "text": "大谷盗"}, {"key": "C", "text": "谷蠹"}, {"key": "D", "text": "粉斑螟"}], "answer": "D", "analysis": "标准“主要害虫”包括玉米象、大谷盗、谷蠹等；粉斑螟（粉斑螟蛾）属于蛾类次生性害虫，未被列入主要害虫范畴。故选粉斑螟。"}, {"id": 684, "type": "单选", "question": "关于使用害虫选筛检查害虫数量，描述错误的为（ ）。", "options": [{"key": "A", "text": "每点取样约 1kg"}, {"key": "B", "text": "以双手回旋的方法筛动，每次筛 1min"}, {"key": "C", "text": "将筛检出的筛下物中的害虫计算每个取样点害虫密度"}, {"key": "D", "text": "筛后用目测及放大镜检查各筛层中害虫"}], "answer": "C", "analysis": "用害虫选筛检查害虫时，应检查筛上物、各筛层及筛下物中的全部害虫，综合计数，而不只是计算筛下物中的害虫。故“将筛下物中的害虫计算每点密度”描述错误。"}, {"id": 685, "type": "单选", "question": "使用害虫选筛时，以双手水平回旋的方法筛动，每次筛动时间不低于（ ）min。", "options": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "1"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "2"}], "answer": "B", "analysis": "使用害虫选筛以双手水平回旋筛动，每次筛动时间不低于1min，使害虫充分与粮食分离、落到相应筛层。故选1min。"}, {"id": 686, "type": "单选", "question": "使用害虫选筛由下向上的安装顺序为（ ）。", "options": [{"key": "A", "text": "筛底、1.5mm孔径筛层、2.5mm孔径筛层、筛盖"}, {"key": "B", "text": "筛底、2.5mm孔径筛层、1.5mm孔径筛层、筛盖"}, {"key": "C", "text": "筛底、1.5mm孔径筛层、2.5mm孔径筛层"}, {"key": "D", "text": "筛底、2.5mm孔径筛层、1.5mm孔径筛层"}], "answer": "A", "analysis": "害虫选筛由下向上安装顺序为：筛底→下层1.5mm孔径筛层→上层2.5mm孔径筛层→筛盖（大孔在上、小孔在下，便于分层截留不同大小害虫）。故选该顺序。"}, {"id": 687, "type": "判断", "question": "使用害虫选筛检查储粮害虫时，只需要检查筛下物，不需要检查筛上物。", "options": ["√", "×"], "answer": "×", "analysis": "筛检后既要检查筛下物，也要检查筛上物和各筛层中的害虫，因为不同大小害虫会留在不同筛层，只看筛下物会漏检。故该说法错误。"}, {"id": 688, "type": "判断", "question": "我国储粮害虫选筛上层筛孔径为2.5mm，下层筛孔径为1.5mm。", "options": ["√", "×"], "answer": "√", "analysis": "我国储粮害虫选筛上层（大孔）孔径为2.5mm、下层（小孔）孔径为1.5mm，用于分层分离害虫。故该说法正确。"}, {"id": 689, "type": "判断", "question": "在气温较低的季节害虫一般不活动，这时可以把害虫放在灯光下加温，然后再鉴别害虫是否死亡。", "options": ["√", "×"], "answer": "√", "analysis": "低温季节害虫活动迟缓、不易判别死活，可将其置于灯光下适当加温，活虫受刺激会活动而死虫不会，从而鉴别存活情况。故该说法正确。"}, {"id": 690, "type": "判断", "question": "使用害虫选筛在筛选结束后应立即观察害虫数量，不得静置。", "options": ["√", "×"], "answer": "×", "analysis": "选筛筛动结束后应静置片刻，使害虫从粮粒中爬出、聚集到筛面或筛层，便于观察和计数，而不是“立即观察不得静置”。故该说法错误。"}, {"id": 691, "type": "单选", "question": "夜间能看到3只以上的鼠活动，或白天也能见到鼠活动的鼠患程度为（ ）。", "options": [{"key": "A", "text": "鼠患很轻"}, {"key": "B", "text": "中等程度鼠患"}, {"key": "C", "text": "一般程度鼠患"}, {"key": "D", "text": "鼠患严重"}], "answer": "D", "analysis": "鼠患程度判定：夜间能看到3只以上鼠活动、或白天也能见到鼠活动，表明鼠密度很高、危害严重，属于“鼠患严重”。故选鼠患严重。"}, {"id": 692, "type": "单选", "question": "关于鼠类的习性，下列说法不正确的是（ ）。", "options": [{"key": "A", "text": "鼠类适应能力很强"}, {"key": "B", "text": "鼠类栖息场所广泛"}, {"key": "C", "text": "鼠类食性复杂"}, {"key": "D", "text": "家鼠大多数在白天活动"}], "answer": "D", "analysis": "家鼠（小家鼠、褐家鼠等）多为夜行性，在黄昏后和黎明前有两个活动高峰，并非“大多数在白天活动”。故该说法错误。"}, {"id": 693, "type": "单选", "question": "夜间能见到一二只鼠活动，但白天看不到鼠活动，鼠患程度为（ ）。", "options": [{"key": "A", "text": "鼠患很轻"}, {"key": "B", "text": "中等程度鼠患"}, {"key": "C", "text": "鼠患严重"}, {"key": "D", "text": "鼠患极其严重"}], "answer": "B", "analysis": "鼠患程度判定：夜间能见到一二只鼠活动、但白天看不到，属中等程度鼠患（较严重为轻、但已有一定密度）。故选中等程度鼠患。"}, {"id": 694, "type": "单选", "question": "使用粉片检查法检查鼠类，一般检查场所的面积最好能布放（ ）块左右的粉片。", "options": [{"key": "A", "text": "100"}, {"key": "B", "text": "200"}, {"key": "C", "text": "300"}, {"key": "D", "text": "400"}], "answer": "C", "analysis": "粉片（滑石粉）检查法调查鼠类活动，一般检查场所面积最好布放约300块粉片，以充分覆盖鼠道、提高阳性率。故选约300块。"}, {"id": 695, "type": "单选", "question": "使用夹线法检查鼠类，在室外一般需放鼠夹（ ）个。", "options": [{"key": "A", "text": "50"}, {"key": "B", "text": "70"}, {"key": "C", "text": "80"}, {"key": "D", "text": "100"}], "answer": "D", "analysis": "夹线法（鼠夹法）在室外调查鼠密度时，一般需布放鼠夹100个（按一定间距直线或网格布放），以保证样本量。故选100个。"}, {"id": 696, "type": "单选", "question": "下列鼠类中，在黑龙江省主要分布的有（ ）。", "options": [{"key": "A", "text": "小家鼠"}, {"key": "B", "text": "黑家鼠"}, {"key": "C", "text": "黄胸鼠"}, {"key": "D", "text": "以上均有"}], "answer": "A", "analysis": "我国鼠类分布有地域性：小家鼠分布最广，包括黑龙江等北方；黑家鼠、黄胸鼠主要分布于南方温暖地区，黑龙江以小白家鼠为主。故选小家鼠。"}, {"id": 697, "type": "单选", "question": "可以用于检查鼠类的鼠迹不包括（ ）。", "options": [{"key": "A", "text": "鼠的脚爪印"}, {"key": "B", "text": "鼠的跑道"}, {"key": "C", "text": "鼠药"}, {"key": "D", "text": "鼠的咬痕"}], "answer": "C", "analysis": "检查鼠类的鼠迹包括脚爪印、跑道（鼠道）、咬痕、粪便等；鼠药是防治手段而非鼠迹。故“鼠药”不属于鼠迹。"}, {"id": 698, "type": "单选", "question": "关于防治麻雀正确的做法是（ ）。", "options": [{"key": "A", "text": "捕捉方法防治麻雀"}, {"key": "B", "text": "枪击方法防治麻雀"}, {"key": "C", "text": "毒杀方法防治麻雀"}, {"key": "D", "text": "粮仓可采用防鸟设施"}], "answer": "D", "analysis": "麻雀属受保护的益鸟，粮库防治应采用防鸟设施（如网、帘、遮挡）等物理方法，不得捕捉、枪击或毒杀。故选“粮仓可采用防鸟设施”。"}, {"id": 699, "type": "判断", "question": "家鼠大多数晚间活动，黄昏后和黎明前有2个高峰期。", "options": ["√", "×"], "answer": "√", "analysis": "家鼠多为夜行性，活动高峰集中在黄昏后和黎明前两个时段，白天一般隐藏休息。故该说法正确。"}, {"id": 700, "type": "判断", "question": "如果夜间能看到3只以上的鼠活动，或白天也见到鼠活动，说明鼠患严重。", "options": ["√", "×"], "answer": "√", "analysis": "鼠患严重判定标准之一：夜间能看到3只以上鼠活动，或白天也见到鼠活动，说明鼠密度大、危害重。故该说法正确。"}, {"id": 701, "type": "单选", "question": "气温上升季节，仓温（ ）于气温。", "options": [{"key": "A", "text": "高"}, {"key": "B", "text": "等"}, {"key": "C", "text": "低"}, {"key": "D", "text": "无关"}], "answer": "C", "analysis": "气温上升（春夏）季节，粮堆热容量大、升温滞后，仓温低于气温，这是“三温”（气温、仓温、粮温）变化规律之一。粮堆热惰性使其对外界升温反应慢，故仓温低于气温。"}, {"id": 702, "type": "单选", "question": "气温下降季节，仓温（ ）于气温。", "options": [{"key": "A", "text": "高"}, {"key": "B", "text": "等"}, {"key": "C", "text": "低"}, {"key": "D", "text": "无关"}], "answer": "A", "analysis": "气温下降（秋冬）季节，粮堆蓄积的热量使其降温滞后，仓温高于外界气温。粮堆热惰性导致下降季节仓温高于气温。"}, {"id": 703, "type": "单选", "question": "粮温年变较气温年变的最低值和最高值推迟（ ）个月。", "options": [{"key": "A", "text": "1~2"}, {"key": "B", "text": "1"}, {"key": "C", "text": "1.5~2"}, {"key": "D", "text": "1.5~2.5"}], "answer": "A", "analysis": "粮堆导热慢、热容量大，粮温年变化相位滞后于气温，最高值和最低值通常比气温推迟1~2个月出现，这是粮堆热惰性的典型表现。"}, {"id": 704, "type": "单选", "question": "粮温最高值出现在（ ）月，最低值出现在3~4月。", "options": [{"key": "A", "text": "9~10"}, {"key": "B", "text": "7~8"}, {"key": "C", "text": "6~7"}, {"key": "D", "text": "8"}], "answer": "A", "analysis": "因粮温滞后气温1~2个月，气温最高在7~8月，粮温最高故推迟到9~10月；最低值则在3~4月（气温最低约1月，滞后至3~4月）。"}, {"id": 705, "type": "单选", "question": "粮温最高值出现在9~10月，最低值出现在（ ）月。", "options": [{"key": "A", "text": "1~2"}, {"key": "B", "text": "3~4"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": "B", "analysis": "粮温年变最低值出现在3~4月，比气温最低（约1月）滞后1~2个月，是粮堆热惰性所致，最高值对应在9~10月。"}, {"id": 706, "type": "单选", "question": "通常能观察到的粮温日变化的部位仅限于粮堆表层至（ ）m深处。", "options": [{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.5"}, {"key": "C", "text": "0.8"}, {"key": "D", "text": "1.0"}], "answer": "A", "analysis": "粮堆导热性差，外界温度的日变化只能影响表层，粮温日变化通常仅限于粮堆表层0.3m以内，深层几乎无日变化。"}, {"id": 707, "type": "单选", "question": "秋末及冬季自然通风降低粮堆温度应该（ ），让热空气上升，把粮堆内热量带走。", "options": [{"key": "A", "text": "只打开粮面上部窗户和通风换气口。"}, {"key": "B", "text": "只打开仓房底部的通风口"}, {"key": "C", "text": "打开粮面上部窗户和通风换气口，同时打开仓房底部的通风口"}, {"key": "D", "text": "打开仓房的窗户"}], "answer": "C", "analysis": "秋冬季利用“热空气上升”原理需上下同时开口形成对流：底部进冷风、上部出热风，带走粮堆内部热量。只开上部或只开底部都形不成有效穿堂对流。"}, {"id": 708, "type": "单选", "question": "为增加粮食与空气的接触面积，提高冷却速度，不包括（ ）的方法。", "options": [{"key": "A", "text": "翻动粮面"}, {"key": "B", "text": "扒沟"}, {"key": "C", "text": "挖塘"}, {"key": "D", "text": "压盖粮面"}], "answer": "D", "analysis": "翻动粮面、扒沟、挖塘都是为了增加粮堆与空气接触面、促进散热；压盖粮面则是隔绝空气、保温防虫，与“增加接触面积”目的相反，故不包括压盖。"}, {"id": 709, "type": "单选", "question": "夏季低温时段降低粮食表层及粮面上部空间的温度，应该（ ）。", "options": [{"key": "A", "text": "只打开粮面上部的窗户和通风换气口"}, {"key": "B", "text": "只打开仓房底部的通风口"}, {"key": "C", "text": "打开粮面上部窗户和通风换气口，同时打开仓房底部的通风口"}, {"key": "D", "text": "打开仓房的窗户"}], "answer": "A", "analysis": "夏季降低表层及上层空间温度，只需打开上部窗和换气口排走积热，不应开底部通风口以免下部热空气上升或外界湿热进入。只开上部即可形成上排气流。"}, {"id": 710, "type": "单选", "question": "机械通风排积热：利用夜间气温下降时机，利用房式仓仓墙上的（ ）或者筒仓仓顶上安装的轴流风机，及时排除白天进入仓内的热量。", "options": [{"key": "A", "text": "电风扇"}, {"key": "B", "text": "离心风机"}, {"key": "C", "text": "排风扇"}, {"key": "D", "text": "混流风机"}], "answer": "C", "analysis": "房式仓多在仓墙上安装排风扇排除白天进入的积热，筒仓则多用仓顶轴流风机。排风扇是房式仓机械排积热的常用设备。"}, {"id": 711, "type": "单选", "question": "山墙安装排风扇的平房仓，可以通过只打开排风扇和防火墙（ ），排除粮面上部空间的积热。", "options": [{"key": "A", "text": "相邻的窗户"}, {"key": "B", "text": "远端的窗户"}, {"key": "C", "text": "中端的窗户"}, {"key": "D", "text": "底部的通风口"}], "answer": "A", "analysis": "排风扇工作时需进风口形成对流，打开与防火墙相邻的窗户作为进风，配合排风扇排出粮面上部空间积热，相邻窗户便于形成有效气流通道。"}, {"id": 712, "type": "单选", "question": "夏季自然通风排仓间积热，操作错误的是打开（ ）", "options": [{"key": "A", "text": "粮面上部窗户"}, {"key": "B", "text": "粮面上部通风换气口"}, {"key": "C", "text": "山墙拱板上的通风口"}, {"key": "D", "text": "仓房底部的通风口"}], "answer": "D", "analysis": "夏季排上层积热只需开上部窗和换气口；打开底部通风口会使下部湿热空气上升或外界热风进入，反而不利，属错误操作。"}, {"id": 713, "type": "单选", "question": "自然通风是指利用空气自然对流，将外界（ ）的空气与粮堆内湿热空气进行交换，达到降低粮食温度、水分的目的。", "options": [{"key": "A", "text": "低温"}, {"key": "B", "text": "干燥"}, {"key": "C", "text": "干燥、低温"}, {"key": "D", "text": "缺氧"}], "answer": "C", "analysis": "自然通风目的是降温降水，需引入外界干燥、低温空气与粮堆内湿热空气交换，才能既降水分又降温度，故应选干燥、低温空气。"}, {"id": 714, "type": "单选", "question": "（ ）天气，大气湿度处于或接近饱和状态，一般不宜通风。", "options": [{"key": "A", "text": "非雨"}, {"key": "B", "text": "非雪"}, {"key": "C", "text": "非雾"}, {"key": "D", "text": "雨、雪、雾"}], "answer": "D", "analysis": "雨、雪、雾天气大气湿度接近饱和，通风会使粮堆吸湿增水，故不宜通风；应在干燥天气进行自然通风。"}, {"id": 715, "type": "单选", "question": "夏季白天太阳辐射热主要通过（ ）传入仓内空间，造成表层粮温上升。", "options": [{"key": "A", "text": "仓墙"}, {"key": "B", "text": "通风口"}, {"key": "C", "text": "仓顶"}, {"key": "D", "text": "窗户"}], "answer": "C", "analysis": "仓顶直接受太阳辐照、面积大且无遮挡，是白天太阳辐射热传入仓内的主要途径，导致上层空间及表层粮温升高，故需对仓顶隔热或排上层积热。"}, {"id": 716, "type": "单选", "question": "拱板仓自然通风降低仓间和表层粮温的方法不包括（ ）", "options": [{"key": "A", "text": "打开粮面上部窗户"}, {"key": "B", "text": "打开粮面上部通风换气口"}, {"key": "C", "text": "打开山墙拱板上方的通风口"}, {"key": "D", "text": "打开仓房底部的通风口"}], "answer": "D", "analysis": "拱板仓降低仓间和表层粮温靠打开上部窗、换气口、山墙拱板上方通风口排热；打开底部通风口不利形成上行排热气流，故选“底部通风口”。"}, {"id": 717, "type": "单选", "question": "选择自然通风时机的原则不包括（ ）。", "options": [{"key": "A", "text": "在不增加粮温的前提下通风降水"}, {"key": "B", "text": "在不增加水分前提下通风降温"}, {"key": "C", "text": "除雨、雾、雪天外"}, {"key": "D", "text": "春秋季连续作业"}], "answer": "D", "analysis": "通风时机按温湿度条件选择，原则是“不增加粮温前提下降水、不增加水分前提下降温、除雨雾雪天外”，并非机械地春秋季连续作业（连续作业可能引入湿热）。"}, {"id": 718, "type": "单选", "question": "关于自然通风描述错误的是（ ）。", "options": [{"key": "A", "text": "必须判断仓内外温湿度是否满足自然通风方法降低粮温条件"}, {"key": "B", "text": "自然通风无需判断通风时机"}, {"key": "C", "text": "自然通风操作前检测平均粮温、平均水分"}, {"key": "D", "text": "通风结束后及时关闭门窗"}], "answer": "B", "analysis": "自然通风必须判断仓内外温湿度是否满足降粮温条件，错误说法是“无需判断时机”；且操作前需检测平均粮温和水分，结束及时关门窗。"}, {"id": 719, "type": "单选", "question": "影响自然通风效果的因素不包括（ ）。", "options": [{"key": "A", "text": "温差"}, {"key": "B", "text": "风速"}, {"key": "C", "text": "粮食品种"}, {"key": "D", "text": "仓房类型"}], "answer": "C", "analysis": "自然通风效果主要受温差、风速、仓房类型等影响；粮食品种本身不直接影响通风换热效果，故选“粮食品种”。"}, {"id": 720, "type": "单选", "question": "关于采用轴流风机降低粮温描述错误的是（ ）。", "options": [{"key": "A", "text": "选择低温时间段（如夜间），但应注意夜间空气湿度所导致粮面水分升高现象发生"}, {"key": "B", "text": "通风前需确认仓内外温湿度大小与差值满足允许排除积热的通风条件"}, {"key": "C", "text": "通风中止时和结束后，要及时关闭仓窗和排气口"}, {"key": "D", "text": "当气温高于仓温时，可继续通风操作"}], "answer": "D", "analysis": "当气温高于仓温时通风会升温，应中止；正确做法是选低温时段（如夜间）、注意夜间湿度致粮面水分升高、结束及时关窗。故“气温高于仓温可继续通风”错误。"}, {"id": 721, "type": "判断", "question": "降低仓温和表层粮温操作，打开粮面上部仓窗和排气口，让仓外的低温空气自然进入仓内并形成对流，把白天太阳辐射传入仓内的热量带走。", "options": ["√", "×"], "answer": "√", "analysis": "正确。夏季夜间或低温时段打开上部仓窗和排气口，让外部低温空气进入并带走白天太阳辐射传入的积热，是降低仓温和表层粮温的常规做法。"}, {"id": 722, "type": "判断", "question": "降低整仓粮温操作，在打开粮面上部仓窗和通风换气口的同时，还应打开下面通风口，让冷空气从粮堆底部进入，从粮面逸出，把粮堆内热量带走。", "options": ["√", "×"], "answer": "√", "analysis": "正确。降低整仓粮温需上下开口形成穿堂对流：冷空气自底部进入、热空气自粮面逸出，利用热空气上升原理带走粮堆内部热量。"}, {"id": 723, "type": "判断", "question": "当气温高于仓温或粮温时，应中止通风操作。", "options": ["√", "×"], "answer": "√", "analysis": "正确。通风目的是降温，当气温高于仓温或粮温时继续通风会使粮温回升，应中止，这是通风作业的基本安全原则。"}, {"id": 724, "type": "判断", "question": "通风中止时和结束后不要关闭仓窗、排气口和通风口。", "options": ["√", "×"], "answer": "×", "analysis": "错误。通风中止和结束后应及时关闭仓窗、排气口和通风口，防止外界湿热空气进入或害虫侵入。题干“不要关闭”违背规程。"}, {"id": 725, "type": "判断", "question": "自然通风降低粮温过程中，无需检查粮情。", "options": ["√", "×"], "answer": "×", "analysis": "错误。通风过程中应检查粮情（粮温、水分、虫害），防止通风不当导致局部结露或水分升高；题干中“无需检查”错误。"}, {"id": 726, "type": "单选", "question": "晾晒干燥粮食时应该选择晴好天气，先晒热晒场，（ ）点粮食出晒。", "options": [{"key": "A", "text": "9"}, {"key": "B", "text": "10"}, {"key": "C", "text": "11"}, {"key": "D", "text": "12"}], "answer": "A", "analysis": "晾晒应在上午9点左右晒场晒热后出晒，避开清晨露水、避免粮食吸潮。过早出晒粮食易沾露返潮，故选9点。"}, {"id": 727, "type": "单选", "question": "温度不变时，饱和湿度是个（ ）。", "options": [{"key": "A", "text": "变量"}, {"key": "B", "text": "常数"}, {"key": "C", "text": "小数"}, {"key": "D", "text": "百分数"}], "answer": "B", "analysis": "在温度一定时，空气能容纳的最大水蒸气量（饱和湿度）是定值即常数；饱和湿度只随温度变化，温度不变则其为常数。"}, {"id": 728, "type": "单选", "question": "饱和湿度（空气中能容纳水气量）随温度升高而（ ）。", "options": [{"key": "A", "text": "不变"}, {"key": "B", "text": "增加"}, {"key": "C", "text": "降低"}, {"key": "D", "text": "变化"}], "answer": "B", "analysis": "温度升高，空气分子运动加剧，能容纳的水汽量增大，饱和湿度随温度升高而增加，这是湿度物理的基本规律。"}, {"id": 729, "type": "单选", "question": "粮食晾晒，下列正确的做法是（ ）。", "options": [{"key": "A", "text": "用沥清路面做晒场"}, {"key": "B", "text": "大米生虫了，晒一晒"}, {"key": "C", "text": "夏季阳光强烈，晒麦"}, {"key": "D", "text": "夏季阳光强烈，晒晚稻谷"}], "answer": "C", "analysis": "小麦较耐高温、爆腰敏感性低，夏季强光下晒麦合适；稻谷、豆类高温暴晒易爆腰、变色、脱皮，沥青路面有毒不能用做晒场，大米生虫晒会碎米。故选“晒麦”。"}, {"id": 730, "type": "单选", "question": "降水时机的选择原则：（ ）", "options": [{"key": "A", "text": "气湿≥粮食水分的平衡湿度，气温≤粮温"}, {"key": "B", "text": "气湿＜粮食水分的平衡湿度，气温＜粮温"}, {"key": "C", "text": "气湿＜粮食水分的平衡湿度，气温≥粮温"}, {"key": "D", "text": "气湿＜粮食水分的平衡湿度，气温≤粮温"}], "answer": "D", "analysis": "降水通风需外界气湿低于粮食平衡湿度（才能解吸降水）且气温不高于粮温（避免升温增湿），故选“气湿＜平衡湿度，气温≤粮温”。"}, {"id": 731, "type": "单选", "question": "（ ）地面不能用做晒场", "options": [{"key": "A", "text": "水泥"}, {"key": "B", "text": "沥清"}, {"key": "C", "text": "砖"}, {"key": "D", "text": "土"}], "answer": "B", "analysis": "沥青路面受晒会软化并释放有害物质、产生异味，污染粮食，不能做晒场；水泥、砖、土场可用（土场需铺垫）。故选沥青。"}, {"id": 732, "type": "单选", "question": "下列摊晒厚度不宜超过100mm的粮种是（ ）。", "options": [{"key": "A", "text": "大豆"}, {"key": "B", "text": "玉米"}, {"key": "C", "text": "蚕豆"}, {"key": "D", "text": "稻谷、小麦"}], "answer": "D", "analysis": "稻谷、小麦等小粒粮导热差、易闷，摊晒厚度不宜超过100mm；大豆、玉米、蚕豆等大中粒可摊厚100~150mm。故选稻谷、小麦。"}, {"id": 733, "type": "单选", "question": "选择自然通风时机的原则，错误的是（ ）。", "options": [{"key": "A", "text": "在不增加粮温的前提下通风降水"}, {"key": "B", "text": "在不增加水分前提下通风降温"}, {"key": "C", "text": "除雨、雾、雪天外。"}, {"key": "D", "text": "春秋季连续作业"}], "answer": "D", "analysis": "通风按温湿度条件选择，并非春秋季连续作业；连续作业可能在不利气象下引入湿热，故“春秋季连续作业”是错误原则。"}, {"id": 734, "type": "单选", "question": "夏季阳光强烈，气温较高，晾晒（ ），容易产生爆腰现象。", "options": [{"key": "A", "text": "小麦"}, {"key": "B", "text": "稻谷"}, {"key": "C", "text": "玉米"}, {"key": "D", "text": "大豆"}], "answer": "B", "analysis": "稻谷米粒在急剧受热时内外收缩不均易产生爆腰（裂纹）；小麦较耐晒。夏季强光高温暴晒稻谷最易爆腰，故选稻谷。"}, {"id": 735, "type": "单选", "question": "包装粮露天堆码通风垛自然通风降水操作方法，不正确的是（ ）。", "options": [{"key": "A", "text": "打垛选址，风道应朝向当地主导风向"}, {"key": "B", "text": "横向隔一段距离打横向风道，以增加过风面积"}, {"key": "C", "text": "当环境条件发生变化不利于通风时，及时苫盖"}, {"key": "D", "text": "选对季节任其对流"}], "answer": "D", "analysis": "通风垛需随环境变化及时苫盖，不能“任其对流”；正确做法包括风道朝主导风向、横向打风道增过风面积、不利时及时苫盖。故选“任其对流”。"}, {"id": 736, "type": "单选", "question": "粮堆内温差越大，持续时间越长，湿热扩散就越严重，导致（ ）部位水分增加。", "options": [{"key": "A", "text": "底层"}, {"key": "B", "text": "湿热"}, {"key": "C", "text": "低温"}, {"key": "D", "text": "高温"}], "answer": "C", "analysis": "湿热扩散中水汽随热流由高温处向低温处移动，在低温部位（如粮堆表层、边角）遇冷凝结使水分增加，易致局部结露霉变。故选低温部位。"}, {"id": 737, "type": "单选", "question": "下列操作不正确的是（ ）。", "options": [{"key": "A", "text": "气湿大，密闭仓房，防水分增加"}, {"key": "B", "text": "气湿小，可以通风散湿降水"}, {"key": "C", "text": "预防春暖引起的表层结露，应该在春暖前压盖粮面。"}, {"key": "D", "text": "雨雪雾天气应该打开仓房门窗"}], "answer": "D", "analysis": "雨雪雾天气大气湿度近饱和，打开门窗会让粮堆吸湿增水，属错误操作；正确做法是密闭防潮、气湿小时通风散湿、春暖前压盖粮面防表层结露。"}, {"id": 738, "type": "单选", "question": "粮食入仓后的水分变化，除了仓顶漏雨、仓墙、地坪渗漏等原因外，都是（ ）变化引起的。", "options": [{"key": "A", "text": "空气温度"}, {"key": "B", "text": "空气湿度"}, {"key": "C", "text": "空气密度"}, {"key": "D", "text": "空气压力"}], "answer": "B", "analysis": "除渗漏外，粮堆水分变化主要是与外界空气湿度交换（吸湿/解吸）的结果，由空气湿度变化引起，与温度、压力、密度无直接关系。"}, {"id": 739, "type": "单选", "question": "晾晒的粮食如需在晒场过夜，应注意（ ）。", "options": [{"key": "A", "text": "攒堆"}, {"key": "B", "text": "苫盖"}, {"key": "C", "text": "围挡"}, {"key": "D", "text": "攒堆和苫盖"}], "answer": "D", "analysis": "粮食在晒场过夜需攒堆（减少散热面积、保温防露）并苫盖（防夜露、雨水、鼠雀），故选攒堆和苫盖。"}, {"id": 740, "type": "单选", "question": "包装粮露天堆码通风垛降水效果最好。需包装运输而短期存放的偏高水分粮食常用。操作时应注意：（ ）", "options": [{"key": "A", "text": "打垛选址，风道不应朝向当地主导风向"}, {"key": "B", "text": "横向隔一段距离打横向风道，以增加过风面积。"}, {"key": "C", "text": "当环境条件发生变化时，可继续通风。"}, {"key": "D", "text": "粮堆温差过大时，及时苫盖"}], "answer": "B", "analysis": "通风垛为增过风面积应横向打风道；风道应朝向主导风向（A错）、环境不利时应及时苫盖而非继续通风（C错），增加过风面积是降水关键，故选横向风道。"}, {"id": 741, "type": "单选", "question": "下列操作与晾晒无关的是（ ）。", "options": [{"key": "A", "text": "晒粮先晒场"}, {"key": "B", "text": "清理杂质"}, {"key": "C", "text": "粮食如在仓外过夜，应注意攒堆和苫盖。"}, {"key": "D", "text": "除热入仓密闭的粮食外，都要冷却后再入仓"}], "answer": "B", "analysis": "清理杂质属入仓前整理/清杂工序，与晾晒操作本身无直接关系；晒场、苫盖过夜、冷却入仓均属晾晒相关环节。故选清理杂质。"}, {"id": 742, "type": "单选", "question": "秋冬交替季节，粮堆内热空气上升到粮堆表层遇冷而凝结，称为（ ）。", "options": [{"key": "A", "text": "外结露"}, {"key": "B", "text": "内结露"}, {"key": "C", "text": "水分转移"}, {"key": "D", "text": "湿热扩散"}], "answer": "B", "analysis": "粮堆内部热空气上升遇冷在粮面凝结属“内结露”（粮堆内部结露）；外结露是外界湿热空气侵入表层遇冷。秋冬交替粮堆内热空气上移，故选内结露。"}, {"id": 743, "type": "单选", "question": "空气中水气含量即绝对湿度（Ps）不变时，温度越低，相对湿度（ ）。", "options": [{"key": "A", "text": "越大"}, {"key": "B", "text": "越小"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "无法确定"}], "answer": "A", "analysis": "相对湿度=实际水汽压/饱和水汽压，绝对湿度不变时温度降低使饱和湿度下降，故相对湿度增大，低温易结露。故选越大。"}, {"id": 744, "type": "单选", "question": "春暖后，仓间热空气侵入粮堆表层遇冷而凝结，称为（ ）。", "options": [{"key": "A", "text": "外结露"}, {"key": "B", "text": "内结露"}, {"key": "C", "text": "水分转移"}, {"key": "D", "text": "湿热扩散"}], "answer": "A", "analysis": "春暖时仓内（外）热湿空气侵入粮堆冷表层遇冷凝结，称“外结露”；内结露是粮堆内部热空气上移至表层遇冷。故选外结露。"}, {"id": 745, "type": "单选", "question": "稻谷、小麦等小粒粮食，摊晒厚度不宜超过（ ）mm，大豆、玉米、蚕豆等大中粒粮食，可摊厚100～150mm。", "options": [{"key": "A", "text": "150"}, {"key": "B", "text": "100"}, {"key": "C", "text": "200"}, {"key": "D", "text": "250"}], "answer": "B", "analysis": "小粒粮（稻谷、小麦）摊晒厚度不宜超过100mm；大中粒（大豆、玉米、蚕豆）可摊厚100~150mm。故选100mm。"}, {"id": 746, "type": "判断", "question": "湿热扩散（水分热扩散）是指储粮水分逆着热传递方向而移动的现象。", "options": ["√", "×"], "answer": "×", "analysis": "错误。湿热扩散是水分随热流方向（由高温向低温）移动，而非“逆着”热传递方向；题干表述反向，故判×。"}, {"id": 747, "type": "判断", "question": "夏季阳光强烈，气温较高，对晚稻谷、豆类等不适宜，容易爆腰、变色、脱皮、降低品质。", "options": ["√", "×"], "answer": "√", "analysis": "正确。晚稻谷、豆类等高温强光暴晒易爆腰、变色、脱皮、降品质，应避免强光暴晒，宜选适宜时段或方式干燥。"}, {"id": 748, "type": "判断", "question": "早晨8点左右粮食出晒。", "options": ["√", "×"], "answer": "×", "analysis": "错误。出晒应在上午9点左右晒场晒热后进行，过早（8点）晒场未热且有露水，不利；题干“早晨8点”不准确。"}, {"id": 749, "type": "判断", "question": "粮堆内温差越大，持续时间越长，湿热扩散就越严重。", "options": ["√", "×"], "answer": "√", "analysis": "正确。温差大且持续，水汽随热流迁移越强，湿热扩散越严重，易在低温部位积水结露。"}, {"id": 750, "type": "判断", "question": "晾晒粮食无需打防虫线。", "options": ["√", "×"], "answer": "×", "analysis": "错误。晾晒场地应打防虫线防止害虫、鼠雀侵入粮食；“无需打防虫线”违背保粮卫生要求。"}, {"id": 751, "type": "单选", "question": "在密封仓门时，仓门处的槽管位于仓门内（ ）mm处。", "options": [{"key": "A", "text": "50"}, {"key": "B", "text": "100"}, {"key": "C", "text": "150"}, {"key": "D", "text": "200"}], "answer": "B", "analysis": "密封仓门时，塑料槽管通常设在仓门内约100mm处，便于嵌压薄膜形成气密。常见标准值约为100mm。"}, {"id": 752, "type": "单选", "question": "密封仓顶时，屋面板的板缝嵌5mm密封胶，然后用丙酮、中性黏胶、无纺布等材料，采用“（ ）”气密性处理。", "options": [{"key": "A", "text": "一布一涂"}, {"key": "B", "text": "二布二涂"}, {"key": "C", "text": "一布四涂"}, {"key": "D", "text": "二布三涂"}], "answer": "D", "analysis": "仓顶气密常用“二布三涂”工艺（两层布、三层涂料）确保气密；板缝先嵌5mm密封胶再布涂处理。故选二布三涂。"}, {"id": 753, "type": "单选", "question": "使用塑料薄膜密封仓窗时，需要使用到的工具不包括（ ）。", "options": [{"key": "A", "text": "塑料薄膜"}, {"key": "B", "text": "铝管"}, {"key": "C", "text": "黏合剂"}, {"key": "D", "text": "调温电熨斗"}], "answer": "B", "analysis": "塑料薄膜密封仓窗用薄膜、黏合剂、调温电熨斗（热合）等；铝管一般不是该工序所需（铝管多见于槽管材料）。故选铝管。"}, {"id": 754, "type": "单选", "question": "下列材料中，不可用于密封仓房门窗和粮堆的是（ ）", "options": [{"key": "A", "text": "棉布"}, {"key": "B", "text": "聚氯乙烯"}, {"key": "C", "text": "聚乙烯"}, {"key": "D", "text": "聚丙烯"}], "answer": "A", "analysis": "棉布透气、不气密且易吸湿，不能用于密封；PVC、PE、PP等塑料薄膜气密性好，可用于密封仓房门窗和粮堆。故选棉布。"}, {"id": 755, "type": "单选", "question": "关于使用塑料薄膜密封仓窗时，描述错误的是（ ）。", "options": [{"key": "A", "text": "提前测量窗户的尺寸，裁剪塑料薄膜"}, {"key": "B", "text": "塑料薄膜要尽量绷紧"}, {"key": "C", "text": "塑料薄膜使用前需查漏补洞"}, {"key": "D", "text": "需检查窗框上有无毛刺"}], "answer": "B", "analysis": "密封仓窗时薄膜应保持适度松弛（防破裂、适应热胀冷缩），并非“尽量绷紧”；绷紧易撕裂，故“尽量绷紧”错误。"}, {"id": 756, "type": "单选", "question": "以下不属于仓房易漏汽部位的是（ ）。", "options": [{"key": "A", "text": "门窗"}, {"key": "B", "text": "通风口"}, {"key": "C", "text": "入粮口"}, {"key": "D", "text": "地坪"}], "answer": "D", "analysis": "门窗、通风口、入粮口等常开启部位易漏气；地坪为整体结构、相对密封，非易漏汽部位。故选地坪。"}, {"id": 757, "type": "单选", "question": "粮仓常用的密封材料不包括（ ）。", "options": [{"key": "A", "text": "油毡纸"}, {"key": "B", "text": "丙烯酸涂料"}, {"key": "C", "text": "PVC"}, {"key": "D", "text": "PE"}], "answer": "A", "analysis": "现代粮仓密封常用丙烯酸涂料、PVC、PE等；油毡纸传统用于防水而非典型气密密封材料，故选油毡纸为不包括项。"}, {"id": 758, "type": "单选", "question": "密封散装粮堆的操作步骤是（ ）。", "options": [{"key": "A", "text": "准备工作→制备帐幕→查漏补洞→密封操作→检查收尾"}, {"key": "B", "text": "查漏补洞→准备工作→制备帐幕→密封操作→检查收尾"}, {"key": "C", "text": "准备工作→查漏补洞→制备帐幕→密封操作→检查收尾"}, {"key": "D", "text": "准备工作→查漏补洞→密封操作→制备帐幕→检查收尾"}], "answer": "C", "analysis": "正确顺序：先准备，再查漏补洞（确保膜无破），制备帐幕，密封操作，最后检查收尾。查漏补洞应在制备/密封前完成。"}, {"id": 759, "type": "单选", "question": "密封散装粮堆的操作时，预防塑料薄膜漏气的一项重要工序是（ ）。", "options": [{"key": "A", "text": "准备工作"}, {"key": "B", "text": "查漏补洞"}, {"key": "C", "text": "制备帐幕"}, {"key": "D", "text": "密封操作"}], "answer": "B", "analysis": "查漏补洞是预防薄膜漏气的关键工序，密封前须检查薄膜有无孔洞并修补，否则熏蒸或气调会失效。故选查漏补洞。"}, {"id": 760, "type": "单选", "question": "塑料薄膜密封粮堆的使用范围不包括（ ）。", "options": [{"key": "A", "text": "低温粮堆隔热保冷"}, {"key": "B", "text": "膜下环流均温通风"}, {"key": "C", "text": "横向通风"}, {"key": "D", "text": "降水通风"}], "answer": "D", "analysis": "薄膜密封用于隔热保冷、膜下环流均温、横向通风等；降水通风需大量排湿、通常敞开或用专用通风，不属薄膜密封常规范围。故选降水通风。"}, {"id": 761, "type": "单选", "question": "密封散装粮堆的要求不包括（ ）。", "options": [{"key": "A", "text": "将粮面铺设走道板，并将其上散落的粮食打扫干净"}, {"key": "B", "text": "将槽管内杂物吹出"}, {"key": "C", "text": "将所用的工具削尖"}, {"key": "D", "text": "热合适度、牢固"}], "answer": "C", "analysis": "密封要求包括粮面铺走道板清粮、吹净槽管杂物、热合适度牢固等；“将工具削尖”既无必要也不安全，不包括在内。"}, {"id": 762, "type": "单选", "question": "采用塑料薄膜密封粮堆时，若密封地坪完好，而墙壁防潮性能差的仓房或包装堆垛可采用（ ）密封。", "options": [{"key": "A", "text": "一面"}, {"key": "B", "text": "三面"}, {"key": "C", "text": "五面"}, {"key": "D", "text": "六面"}], "answer": "C", "analysis": "地坪完好只需封四周墙+粮面+顶，即五面密封（地坪不封）；墙壁防潮差但地坪好适用五面密封。故选五面。"}, {"id": 763, "type": "单选", "question": "采用塑料薄膜密封粮堆时，若密封地坪返潮，仓体气密性差的仓房和成品粮堆垛可采用（ ）密封。", "options": [{"key": "A", "text": "一面"}, {"key": "B", "text": "三面"}, {"key": "C", "text": "五面"}, {"key": "D", "text": "六面"}], "answer": "D", "analysis": "地坪返潮、气密性差时需连地坪一并封，采用六面密封（含底膜）以彻底隔潮气密。故选六面。"}, {"id": 764, "type": "单选", "question": "采用塑料薄膜密封整个仓房粮面的方法称为（ ）密封。", "options": [{"key": "A", "text": "一面"}, {"key": "B", "text": "三面"}, {"key": "C", "text": "五面"}, {"key": "D", "text": "六面"}], "answer": "A", "analysis": "只封粮堆表面（粮面）一层薄膜称“一面密封”（单面封）；三面、五面、六面指封不同面数。故选一面。"}, {"id": 765, "type": "单选", "question": "仓房土建结构好和墙壁、地坪防潮性能、密封性能高的房式仓，通常采用（ ）密封法。", "options": [{"key": "A", "text": "移动式塑料槽管"}, {"key": "B", "text": "固定式塑料槽管"}, {"key": "C", "text": "全包法"}, {"key": "D", "text": "半包法"}], "answer": "B", "analysis": "结构好、气密性高的房式仓用固定式塑料槽管（预埋于仓壁）密封，牢固耐久；移动式用于临时。故选固定式。"}, {"id": 766, "type": "单选", "question": "对仓房中的柱子也需密封。（ ）是用薄膜将柱子包上一段，一般是从粮面向下300~500mm为宜。", "options": [{"key": "A", "text": "移动式塑料槽管"}, {"key": "B", "text": "固定式塑料槽管"}, {"key": "C", "text": "全包法"}, {"key": "D", "text": "半包法"}], "answer": "D", "analysis": "柱子用薄膜从粮面向下包300~500mm称“半包法”；全包法包整个柱子。故选半包法。"}, {"id": 767, "type": "判断", "question": "在密封仓窗时，要特别注意塑料薄膜保持适度松弛，以防止破裂。", "options": ["√", "×"], "answer": "√", "analysis": "正确。薄膜热胀冷缩、受风易动，适度松弛可防撕裂破裂、保持气密；过度绷紧反而易破。"}, {"id": 768, "type": "判断", "question": "粮仓容易漏气的部位主要发生在仓房需要经常开启的孔洞如门窗、通风口、进粮口等。", "options": ["√", "×"], "answer": "√", "analysis": "正确。常开启的孔洞密封件易损、易漏气，是气密薄弱点，熏蒸或气调前须重点处理。"}, {"id": 769, "type": "判断", "question": "粮仓常用的密封涂料是聚氨酯类、丙烯酸类等。", "options": ["√", "×"], "answer": "√", "analysis": "正确。聚氨酯、丙烯酸类涂料气密性好、附着力强，是粮仓常用密封涂料。"}, {"id": 770, "type": "判断", "question": "塑料薄膜在常温下不耐酸碱的腐蚀，但具有一定的耐磨性和绝缘性。", "options": ["√", "×"], "answer": "×", "analysis": "错误。塑料薄膜（PE、PVC等）在常温下耐酸碱腐蚀性能较好，并非“不耐酸碱”；题干表述错误。"}, {"id": 771, "type": "单选", "question": "过筛除虫是利用害虫与粮粒（ ）的差别，通过合适的筛孔将粮油与虫、杂分类。", "options": [{"key": "A", "text": "大小"}, {"key": "B", "text": "颜色"}, {"key": "C", "text": "密度"}, {"key": "D", "text": "水分"}], "answer": "A", "analysis": "过筛除虫利用害虫个体通常比粮粒小（或形状不同），凭大小差异经筛孔将虫杂与粮粒分离。故选大小。"}, {"id": 772, "type": "单选", "question": "利用压盖储藏法可防治（ ）储粮害虫。", "options": [{"key": "A", "text": "甲虫类"}, {"key": "B", "text": "蛾类"}, {"key": "C", "text": "书虱"}, {"key": "D", "text": "螨类"}], "answer": "B", "analysis": "压盖法隔绝粮面与空气、阻断蛾类（如印度谷蛾、麦蛾）在粮面产卵活动，主要防治蛾类；甲虫类多在粮堆内部活动，压盖效果差。故选蛾类。"}, {"id": 773, "type": "单选", "question": "防虫网是一种（ ）目以上的尼龙或聚酯的筛绢网。", "options": [{"key": "A", "text": "50"}, {"key": "B", "text": "60"}, {"key": "C", "text": "70"}, {"key": "D", "text": "80"}], "answer": "D", "analysis": "防虫网一般为80目以上的尼龙或聚酯筛绢网，可阻挡蛾类等害虫进入仓房。常见标准值约为80目以上。"}, {"id": 774, "type": "单选", "question": "过筛除虫时，想要达到除虫效果的关键是（ ）。", "options": [{"key": "A", "text": "筛子运动速度"}, {"key": "B", "text": "筛子运动方向"}, {"key": "C", "text": "筛子筛孔的大小和形状"}, {"key": "D", "text": "筛子运动幅度"}], "answer": "C", "analysis": "除虫效果关键在于筛孔大小形状要与害虫个体匹配，使虫能通过而粮粒留下（或反之）。故选筛孔大小和形状。"}, {"id": 775, "type": "单选", "question": "过筛除虫，适于分离与粮粒厚度、宽度都不相同的害虫的筛孔形状是（ ）。", "options": [{"key": "A", "text": "圆形"}, {"key": "B", "text": "三角形"}, {"key": "C", "text": "正方形"}, {"key": "D", "text": "长方形"}], "answer": "D", "analysis": "长方形筛孔按厚度/宽度方向分离，适于与粮粒厚度、宽度均不同的害虫；圆形/方形按尺寸，长孔更易分离扁长形虫体。故选长方形。"}, {"id": 776, "type": "单选", "question": "筛面上的粮层越厚，过筛除虫的效果就越（ ）。", "options": [{"key": "A", "text": "好"}, {"key": "B", "text": "差"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不一定"}], "answer": "B", "analysis": "粮层越厚，虫体越难到达筛面、筛分越不充分，除虫效果越差；宜薄层筛理。故选差。"}, {"id": 777, "type": "单选", "question": "粮油在筛面上运动的距离越长，过筛除虫的效果就越（ ）。", "options": [{"key": "A", "text": "好"}, {"key": "B", "text": "差"}, {"key": "C", "text": "不变"}, {"key": "D", "text": "不一定"}], "answer": "A", "analysis": "运动距离越长，虫粮接触筛面机会越多，分离越充分，除虫效果越好。故选好。"}, {"id": 778, "type": "单选", "question": "关于压盖防治储粮害虫的要求，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "储粮水分要在安全水分以下"}, {"key": "B", "text": "虫粮等级要在一般虫粮以下"}, {"key": "C", "text": "仓房应有较好的密闭性能"}, {"key": "D", "text": "仓房应有较好的防潮性能"}], "answer": "B", "analysis": "压盖要求虫粮等级应在“基本无虫粮”以下（更严），并非“一般虫粮以下”（一般虫粮已不适于压盖）。故该说法错误，选B。"}, {"id": 779, "type": "单选", "question": "下列材料，不可用于压盖防治储粮害虫的包括（ ）。", "options": [{"key": "A", "text": "有虫的糠壳"}, {"key": "B", "text": "干沙"}, {"key": "C", "text": "草木灰"}, {"key": "D", "text": "异种粮包"}], "answer": "A", "analysis": "压盖材料须清洁无虫，有虫的糠壳会带入害虫，不可用；干沙、草木灰、异种粮包（清洁无毒）可作压盖材料。故选有虫的糠壳。"}, {"id": 780, "type": "单选", "question": "关于压盖储粮害虫，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "可防治蛾类储粮害虫"}, {"key": "B", "text": "压盖材料要因地制宜"}, {"key": "C", "text": "压盖要做到“平、紧、密、实”"}, {"key": "D", "text": "压盖时间应在春末"}], "answer": "D", "analysis": "压盖应在春初（第一代蛾类羽化前、气温回升前）进行，而非“春末”；春末害虫已活动，压盖过晚失效。故“春末”错误。"}, {"id": 781, "type": "单选", "question": "（ ）是利用害虫的个体比粮粒小，带虫的粮食通过筛面时，害虫就从筛眼中掉到筛下。", "options": [{"key": "A", "text": "压盖防治"}, {"key": "B", "text": "过筛除虫"}, {"key": "C", "text": "风车除虫"}, {"key": "D", "text": "风扬除虫"}], "answer": "B", "analysis": "过筛除虫正是利用虫体小于粮粒，带虫粮食过筛时虫从筛眼落下分离。故选过筛除虫。"}, {"id": 782, "type": "单选", "question": "关于过筛除虫，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "根据害虫个体与粮粒的形状和大小选用合适的筛网"}, {"key": "B", "text": "筛出的虫、杂要及时清理"}, {"key": "C", "text": "对粮粒内部害虫无效"}, {"key": "D", "text": "筛网直径为1.0mm"}], "answer": "D", "analysis": "过筛除虫筛网规格依害虫和粮种而定，并非固定“直径1.0mm”；该绝对化表述错误。故选D。"}, {"id": 783, "type": "判断", "question": "压盖时要由仓门口向远离仓门的地方开始倒退。", "options": ["√", "×"], "answer": "×", "analysis": "错误。压盖应从仓内远离仓门处向门口方向退着封，避免人员踩踏已压盖部分；题干起点在仓门口方向反了。"}, {"id": 784, "type": "判断", "question": "过筛除虫时，如果粮油中既有大于粮粒的害虫，又有小于粮粒的害虫，则应采用双层或多层筛。", "options": ["√", "×"], "answer": "√", "analysis": "正确。双层或多层筛可分别分离大于和小于粮粒的害虫及杂质，提高除虫效率。"}, {"id": 785, "type": "判断", "question": "为防止蛾类害虫繁殖危害，压盖必须在每年第一代害虫羽化前进行。", "options": ["√", "×"], "answer": "√", "analysis": "正确。压盖须在蛾类第一代羽化前完成，才能阻断其在粮面产卵繁殖，否则错过时机压盖失效。"}, {"id": 786, "type": "单选", "question": "使用毒饵灭鼠的方法属于（ ）。", "options": [{"key": "A", "text": "化学灭鼠"}, {"key": "B", "text": "物理灭鼠"}, {"key": "C", "text": "电子灭鼠"}, {"key": "D", "text": "器械灭鼠"}], "answer": "A", "analysis": "毒饵含抗凝血等杀鼠药剂，属化学灭鼠法。故选化学灭鼠。"}, {"id": 787, "type": "单选", "question": "对于进入仓内粮堆中的鼠类，下列灭鼠方法不能使用的是（ ）。", "options": [{"key": "A", "text": "使用鼠笼捕杀"}, {"key": "B", "text": "使用粘鼠板捕杀"}, {"key": "C", "text": "使用鼠夹捕杀"}, {"key": "D", "text": "使用毒饵毒杀"}], "answer": "D", "analysis": "粮堆内禁用毒饵（毒死老鼠腐烂污染粮食、鼠尸难寻），只能用鼠笼、粘鼠板、鼠夹等物理器械。故选毒饵。"}, {"id": 788, "type": "单选", "question": "下列灭鼠方法中，不属于物理方法灭鼠的是（ ）。", "options": [{"key": "A", "text": "使用熏蒸剂灭鼠"}, {"key": "B", "text": "使用鼠笼灭鼠"}, {"key": "C", "text": "使用鼠夹灭鼠"}, {"key": "D", "text": "使用粘鼠板灭鼠"}], "answer": "A", "analysis": "熏蒸剂灭鼠属化学法；鼠笼、鼠夹、粘鼠板为物理器械法。故选熏蒸剂。"}, {"id": 789, "type": "单选", "question": "下列灭鼠方法中，属于物理方法灭鼠的是（ ）。", "options": [{"key": "A", "text": "使用熏蒸剂灭鼠"}, {"key": "B", "text": "使用鼠药灭鼠"}, {"key": "C", "text": "使用毒饵灭鼠"}, {"key": "D", "text": "使用粘鼠板灭鼠"}], "answer": "D", "analysis": "粘鼠板为物理捕杀器械，属物理灭鼠；熏蒸剂、鼠药、毒饵属化学法。故选粘鼠板灭鼠。"}, {"id": 790, "type": "单选", "question": "关于粘鼠板的使用方法，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "将粘鼠板打开，有胶一面朝上"}, {"key": "B", "text": "折放或平放于鼠类经常出没的地方"}, {"key": "C", "text": "在潮湿或灰尘较多的地方，应先打扫干净环境再使用"}, {"key": "D", "text": "如果粘鼠板沾上水，粘鼠板就失效，应丢弃"}], "answer": "D", "analysis": "粘鼠板沾水会降低粘性，但非“就失效必须丢弃”——可擦干或补诱饵，该表述过于绝对错误；潮湿环境应先清扫干燥再布放。故选D。"}, {"id": 791, "type": "单选", "question": "对于灭鼠器械的布放时间，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "在鼠类活动的盛期应多用捕鼠器"}, {"key": "B", "text": "捕鼠器应在清晨布放"}, {"key": "C", "text": "每种工具连续布放时间一般不宜超过7天"}, {"key": "D", "text": "对鼠类应常年坚持捕杀"}], "answer": "B", "analysis": "捕鼠器应在傍晚或夜间鼠类活动盛期前布放，而非清晨；清晨布放错过鼠活动高峰。故“清晨布放”错误。"}, {"id": 792, "type": "单选", "question": "关于电子捕鼠器，下列说法错误的是（ ）。", "options": [{"key": "A", "text": "电子捕鼠器击到鼠类会迅速断电"}, {"key": "B", "text": "大多数鼠类会被电子捕鼠器直接电死"}, {"key": "C", "text": "被电子捕鼠器击到但没电死的鼠类之后不会再上当"}, {"key": "D", "text": "使用电子捕鼠器时，必须有专人值班管理，及时取走被电击昏的鼠类"}], "answer": "B", "analysis": "电子捕鼠器多将鼠击昏/电击，并非“大多数直接电死”，需专人及时取走；A、C、D描述正确（击到迅速断电、击昏后不再上当、须专人值班）。故选B。"}, {"id": 793, "type": "单选", "question": "鼠类可能进入储粮仓库的通道不包括（ ）。", "options": [{"key": "A", "text": "挡鼠板"}, {"key": "B", "text": "墙壁"}, {"key": "C", "text": "门窗"}, {"key": "D", "text": "管道"}], "answer": "A", "analysis": "挡鼠板是防鼠设施、阻断鼠进入，不是进入通道；墙壁孔洞、门窗缝隙、管道是鼠进入仓库的通道。故选挡鼠板。"}, {"id": 794, "type": "单选", "question": "鼠类在一个区域或仓库内能否生存，并保持一定的数量，其生活环境需具备的条件不包括（ ）。", "options": [{"key": "A", "text": "安全的隐蔽处所"}, {"key": "B", "text": "足够的食物"}, {"key": "C", "text": "最少限度的竞争者"}, {"key": "D", "text": "没有任何天敌"}], "answer": "D", "analysis": "鼠生存需隐蔽处所、食物、竞争者少等，但“没有任何天敌”非必要条件（有天敌仍可能生存）。故选D。"}, {"id": 795, "type": "单选", "question": "在粮库中，防鼠灭鼠常用的器械不包括（ ）。", "options": [{"key": "A", "text": "鼠夹"}, {"key": "B", "text": "鼠药"}, {"key": "C", "text": "粘鼠板"}, {"key": "D", "text": "电子捕鼠器"}], "answer": "B", "analysis": "鼠药属化学药物，非“器械”；鼠夹、粘鼠板、电子捕鼠器为物理器械。故选鼠药。"}, {"id": 796, "type": "单选", "question": "捕鼠器使用后的处理，描述错误的是（ ）。", "options": [{"key": "A", "text": "立即将死鼠移去"}, {"key": "B", "text": "用泥沙、干草擦净"}, {"key": "C", "text": "水洗捕鼠器，再曝晒数小时"}, {"key": "D", "text": "扔掉死鼠后放回粮仓继续使用"}], "answer": "D", "analysis": "死鼠应移出仓外妥善处理，不应“扔掉死鼠后放回粮仓”——死鼠及处理应在仓外，避免污染；正确为移去、擦净、水洗曝晒。故选D。"}, {"id": 797, "type": "单选", "question": "捕鼠器的检查，描述错误的是（ ）。", "options": [{"key": "A", "text": "放置后要勤检查"}, {"key": "B", "text": "只能连续应用几天，要经常调换工具种类"}, {"key": "C", "text": "布放时间，一般不宜超过3天"}, {"key": "D", "text": "带诱饵的捕鼠器最好布放在老鼠的寻食场所附近"}], "answer": "C", "analysis": "捕鼠器连续布放一般不宜超过7天（非3天），超过鼠会警觉、效果下降；C说“不宜超过3天”错误。故选C。"}, {"id": 798, "type": "判断", "question": "进入粮仓内的鼠类可以使用捕杀、器械、毒饵毒杀等方法进行除治。", "options": ["√", "×"], "answer": "×", "analysis": "错误。粮堆内严禁用毒饵（污染粮食、鼠尸难寻），只能用器械捕杀；题干说可用毒饵错误。"}, {"id": 799, "type": "判断", "question": "使用鼠夹时，注意别在引发部上的别棍不能别的过死。", "options": ["√", "×"], "answer": "√", "analysis": "正确。鼠夹别棍别太死会降低灵敏度、不易触发，应松紧适度以保证灵敏。"}, {"id": 800, "type": "判断", "question": "不带诱饵的捕鼠器应放在鼠洞口，鼠道上或鼠活动场所等处。", "options": ["√", "×"], "answer": "√", "analysis": "正确。无诱饵捕鼠器靠布设在鼠道、洞口、活动场所等鼠必经之路捕获，位置选择是关键。"}];
